// 文法詳解 N3(老師口吻,scripts/gen-grammar-detail.mjs 產生、build-grammar-detail.mjs 合併;改風格改 scripts/grammar-detail-samples.js 再重產)。
// key=文法 id;value=HTML(渲染時 .gd-jp 日文過 furiganaHTML→furigana+即點即查;中文解說不動)。
window.GRAMMAR_DETAIL = window.GRAMMAR_DETAIL || {};
Object.assign(window.GRAMMAR_DETAIL, {
  "n3-41": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜わけだ」就是中文的<b>「難怪～」「原來如此，所以才～」</b>，也可以是<b>「也就是說～」</b>。你手上已經有一個事實，又知道了背後的原因（或把資訊算一算），兩邊一接起來，心裡「喔～說得通了」，這時候就用わけだ。<br>（<span class='gd-jp'>わけ</span>寫成漢字是「訳」，意思是道理、原因。）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>難怪</span>早就覺得奇怪的事，現在知道原因了，恍然大悟。常跟<span class='gd-jp'>道理で</span>（難怪）、<span class='gd-jp'>〜のか</span>（原來～啊）一起出現。</div><div class='gd-ex-line'>・<span class='gd-jp'>道理で寒いわけだ。雪が降っている。</span>（難怪這麼冷，原來在下雪）</div><div class='gd-ex-line'>・<span class='gd-jp'>3年も住んでいたのか。日本語が上手なわけだ。</span>（住了三年啊，難怪日文這麼好）</div><div class='gd-sec'><span class='gd-tag'>也就是說</span>把前面的資訊換個說法，或算出結果，等於在說「所以結論就是～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>8時に出て9時に着いたから、1時間かかったわけだ。</span>（8點出門、9點到，也就是說花了一個小時）</div><div class='gd-ex-line'>・<span class='gd-jp'>「明日は会社が休みです。」「じゃあ、ゆっくり寝られるわけですね。」</span>（「明天公司放假。」「那也就是說可以好好睡一覺囉。」）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：普通形直接接（普通形＝沒有ます的說法，過去式、否定都可以）<br><span class='gd-pair'><span class='gd-jp'>眠れない</span> → <span class='gd-jp'>眠れないわけだ</span></span><span class='gd-pair'><span class='gd-jp'>かかった</span> → <span class='gd-jp'>かかったわけだ</span></span><br><b>い形容詞</b>：直接接<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いわけだ</span></span><br><b>な形容詞</b>：要留著「な」<br><span class='gd-pair'><span class='gd-jp'>上手</span> → <span class='gd-jp'>上手なわけだ</span></span><br><b>名詞</b>：加「な」（比較正式的文章用「である」）<br><span class='gd-pair'><span class='gd-jp'>休み</span> → <span class='gd-jp'>休みなわけだ</span></span><br>對別人講要有禮貌，就換成<span class='gd-jp'>わけです</span>。聊天時常縮成<span class='gd-jp'>わけか</span>、<span class='gd-jp'>わけね</span>。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・な形容詞和名詞後面<b>不能直接接わけ</b>：說<span class='gd-jp'>上手なわけだ</span>，不是「上手わけだ」。<br>・わけだ不是隨口猜。前面一定要有<b>已經知道的事實或理由</b>，你只是把它跟結果接起來。<br>・用在別人的缺點上，像<span class='gd-jp'>だから失敗したわけだ</span>（難怪會失敗），聽起來有「怪不得嘛」的味道，對長輩、客人要小心。<br>・別跟<span class='gd-jp'>わけがない</span>、<span class='gd-jp'>わけではない</span>、<span class='gd-jp'>わけにはいかない</span>搞混，只差幾個字，意思完全不一樣。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>はずだ</b>也是「根據理由下判斷」，關鍵差別在<b>結果還不確定的時候</b>：只是照理推測，就只能用はずだ，不能用わけだ。同一個情境：田中先生在美國住了十年。<br><span class='gd-tag'>わけだ</span>你已經聽過他講英文，覺得好流利，現在知道原因：<br><span class='gd-jp'>10年もアメリカにいたのか。英語がうまいわけだ。</span>（在美國待了十年啊，難怪英文那麼好）<br><span class='gd-tag'>はずだ</span>你還沒聽過他講英文，只能照理推測（這時候不能用わけだ）：<br><span class='gd-jp'>10年もアメリカにいたから、英語がうまいはずだ。</span>（他在美國待了十年，照理說英文應該很好）<br>再一個：<span class='gd-jp'>彼は来ると言っていたから、来るはずだ。</span>（他說會來，所以應該會來）人還沒出現、結果還沒確定，就是はずだ。<br>不過在「難怪」的用法上，はずだ也可以用，像<span class='gd-jp'>道理で寒いはずだ。</span>、<span class='gd-jp'>10年もアメリカにいたのか。英語がうまいはずだ。</span>都很自然，意思和わけだ差不多。<br>如果連理由都沒有，只是隨口猜「應該會吧」，那是<span class='gd-jp'>だろう</span>／<span class='gd-jp'>でしょう</span>，不是はずだ，也不是わけだ。</div><div class='gd-warn'>判斷小訣竅：結果還沒確定、只是照理推測時，只能用はずだ；結果已經擺在眼前，你在說「難怪／原來如此」時，わけだ和はずだ都可以。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>わけ家族接著學：<span class='gd-jp'>わけがない</span>（不可能）、<span class='gd-jp'>わけではない</span>（並不是～）、<span class='gd-jp'>わけにはいかない</span>（道理上不能～）。另外，說明完理由要收尾時，常說<span class='gd-jp'>というわけで</span>（就是這樣，所以～）：<span class='gd-jp'>というわけで、明日は休みます。</span>（就是這樣，所以我明天請假）</div>",
  "n3-42": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜わけがない」就是中文的<b>「怎麼可能～」「哪有可能～」</b>。「わけ」在這裡是「道理」，「わけがない」字面上是「沒有這種道理」，意思就是你很肯定地說：這件事<b>根本不可能</b>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>斷定不可能</span>根據常識，或你對某個人的了解，覺得這件事絕對不會發生。</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなに簡単に成功するわけがない。</span>（不可能那麼簡單就成功）</div><div class='gd-ex-line'>・<span class='gd-jp'>こんな値段で本物が手に入るわけがない。</span>（這種價錢不可能買到真品）</div><div class='gd-ex-line'>・<span class='gd-jp'>あんなに練習したんだから、負けるわけがない。</span>（練習得那麼認真，不可能會輸）</div><div class='gd-sec'><span class='gd-tag'>反駁對方</span>朋友聊天時回一句「才不可能咧」。口語常把「が」省掉，說成「わけない」。</div><div class='gd-ex-line'>・<span class='gd-jp'>宝くじなんて、当たるわけないよ。</span>（樂透那種東西，怎麼可能中啦）</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなわけないでしょ。</span>（怎麼可能啦）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：直接接，否定、過去也可以。<br><span class='gd-pair'><span class='gd-jp'>負ける</span> → <span class='gd-jp'>負けるわけがない</span></span><span class='gd-pair'><span class='gd-jp'>知らない</span> → <span class='gd-jp'>知らないわけがない</span></span><br><b>い形容詞</b>：直接接。<br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いわけがない</span></span><br><b>な形容詞</b>：把「だ」換成「な」。<br><span class='gd-pair'><span class='gd-jp'>好きだ</span> → <span class='gd-jp'>好きなわけがない</span></span><br><b>名詞</b>：把「だ」換成「の」，正式一點可以用「である」。<br><span class='gd-pair'><span class='gd-jp'>本物だ</span> → <span class='gd-jp'>本物のわけがない</span></span><br>要講得禮貌一點，就說「<span class='gd-jp'>わけがありません</span>」。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・な形容詞、名詞不能把「だ」直接留著接：<span class='gd-jp'>好きだわけがない</span>、<span class='gd-jp'>本物だわけがない</span>都是錯的。<br>・「〜ないわけがない」是兩個否定疊在一起，意思反而是<b>「一定會」</b>：<span class='gd-jp'>彼が期限を守らないわけがない。</span>（他不可能不遵守期限＝他一定會守期限）<br>・中文的「不可能」跟「不能」很像，日文差很多。「明天要考試，不能去玩」是你<b>不方便、不應該</b>去，要用わけにはいかない：<span class='gd-jp'>明日は試験だから、遊びに行くわけにはいかない。</span>（明天要考試，不能去玩）寫成<span class='gd-jp'>遊びに行くわけがない</span>，就變成「我怎麼可能去玩」了。<br>・語氣很強，有種「你在說什麼傻話」的味道。對主管、長輩直接回<span class='gd-jp'>そんなわけないです</span>會很衝，可以改說<span class='gd-jp'>それはないと思います</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>情境：你拿蛋糕給田中，他說不用了。旁邊的人問你：「田中是不是討厭蛋糕？」<br><b>わけがない</b>＝<b>強烈否定</b>，口氣像「哪有可能啦」：</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんがケーキが嫌いなわけがないよ。毎日食べてるもん。</span>（田中怎麼可能討厭蛋糕，他每天都在吃耶）</div><div class='gd-sec'><b>はずがない</b>＝<b>照道理推論</b>不會這樣，口氣比較冷靜：</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは甘いものが大好きだから、ケーキが嫌いなはずがない。</span>（田中最愛吃甜的，照理說不可能討厭蛋糕）</div><div class='gd-sec'>這兩個很多時候可以互換。差別在はずがない偏「根據手上的線索推出來不會」，わけがない偏「從道理上就說不通」，口語裡情緒更強。<br><b>わけではない</b>＝<b>「並不是～」</b>，只是修正誤會，完全沒有「不可能」的意思。換田中自己解釋，就會說：</div><div class='gd-ex-line'>・<span class='gd-jp'>甘いものが嫌いなわけではない。今はおなかがいっぱいなだけだ。</span>（並不是討厭甜食，只是現在肚子很飽而已）</div><div class='gd-warn'>判斷小訣竅：想說「怎麼可能」用わけがない；想說「照理說不會」用はずがない；想說「並不是～」用わけではない。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>「わけ」家族還有：<span class='gd-jp'>わけではない</span>（並不是～）、<span class='gd-jp'>わけにはいかない</span>（不能～），再加上意思最接近的<span class='gd-jp'>はずがない</span>，一起學最不會搞混。</div>",
  "n3-43": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜わけではない」就是中文的<b>「並不是～」「也不是說～」</b>。對方可能以為是那樣，你出來澄清：「不是你想的那樣啦」。很像台灣人常講的「我不是討厭啦，只是…」，後面常常會接真正的原因。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>澄清誤會</span>對方好像誤會你了，你把話講清楚。</div><div class='gd-ex-line'>・<span class='gd-jp'>反対しているわけではありません。ちょっと心配なだけです。</span>（我並不是反對，只是有點擔心）</div><div class='gd-ex-line'>・<span class='gd-jp'>別に怒っているわけじゃないよ。</span>（我又不是在生氣啦）</div><div class='gd-sec'><span class='gd-tag'>不是全部都那樣</span>跟「<span class='gd-jp'>みんな</span>」「<span class='gd-jp'>いつも</span>」「<span class='gd-jp'>全部</span>」一起用，意思是「不一定都是這樣」。</div><div class='gd-ex-line'>・<span class='gd-jp'>日本人がみんな納豆が好きなわけではない。</span>（並不是每個日本人都喜歡納豆）</div><div class='gd-ex-line'>・<span class='gd-jp'>高い服がいつもいいわけではない。</span>（貴的衣服不一定都比較好）</div><div class='gd-sec'><span class='gd-tag'>委婉拒絕</span>不想把話說死，先否定一個可能的誤會，再講理由。</div><div class='gd-ex-line'>・<span class='gd-jp'>料理が嫌いなわけじゃないけど、毎日はちょっと…。</span>（我不是討厭做菜，只是每天做有點…）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面放「普通形」，也就是不加ます的說法（辭書形、ない形、た形都可以）。<br><b>動詞</b>：<span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くわけではない</span></span><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったわけではない</span></span><br><b>い形容詞</b>：<span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>忙しいわけではない</span></span><br><b>な形容詞</b>：要加<b>な</b>　<span class='gd-pair'><span class='gd-jp'>嫌い</span> → <span class='gd-jp'>嫌いなわけではない</span></span><br><b>名詞</b>：加<b>な</b>，或用「という」　<span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生というわけではない</span></span></div><div class='gd-sec'>講話時常說成<b>わけじゃない</b>，比較客氣就說<b>わけではありません</b>或<b>わけじゃありません</b>。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・な形容詞跟名詞後面<b>不能接だ</b>：要說<span class='gd-jp'>嫌いなわけではない</span>，不能說「嫌いだわけではない」。<br>・這裡的「わけ」不是「理由」的意思，不要翻成「沒有理由」。<br>・它比直接否定柔和：<span class='gd-jp'>嫌いじゃない</span>是「不討厭」，<span class='gd-jp'>嫌いなわけじゃない</span>是「也不是說討厭（而是有別的原因）」，所以後面通常會補一句說明。<br>・前面放否定時是雙重否定：<span class='gd-jp'>行きたくないわけじゃない。</span>（也不是不想去），意思是其實有點想去。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣在講一家店貴不貴：<br><b>わけではない</b>＝<b>並不是</b>：<span class='gd-jp'>この店、高いわけではないけど、ちょっと遠い。</span>（這家店並不是貴，只是有點遠）<br><b>わけがない</b>＝<b>不可能</b>：<span class='gd-jp'>100円ショップだから、高いわけがない。</span>（是百元商店，不可能貴）<br><b>わけだ</b>＝<b>難怪</b>：<span class='gd-jp'>有名なシェフの店か。高いわけだ。</span>（原來是名廚的店，難怪這麼貴）</div><div class='gd-warn'>判斷小訣竅：「並不是～」用わけではない，「不可能～」用わけがない，「難怪～」用わけだ。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>「<span class='gd-jp'>〜ないことはない</span>」（也不是不～）跟「〜ないわけではない」意思接近，都是「勉強算是可以」的口氣：<span class='gd-jp'>辛い料理も食べられないことはない。</span>（辣的菜也不是不能吃）</div>",
  "n3-44": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜わけにはいかない」就是中文的<b>「總不能～吧」</b>。重點不是你做不到，而是照道理、看情面、顧身分，<b>不好這麼做</b>。主管還在加班，你心裡想「總不能自己先走吧」，就是這個感覺。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>不能做</span>辭書形＋わけにはいかない<br><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰るわけにはいかない</span></span>（總不能回去）</div><div class='gd-sec'><span class='gd-tag'>不能不做</span>ない形＋わけにはいかない，意思變成<b>非做不可</b>。<br><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないわけにはいかない</span></span>（總不能不去＝非去不可）<br>ない形就是動詞「不～」的說法，例如<span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行かない</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べない</span></span>。</div><div class='gd-sec'>對長輩、客人講要客氣一點，就把いかない換成いきません：<span class='gd-jp'>休むわけにはいきません</span>（我不能請假）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>總不能做</span>理由上、立場上不好做。</div><div class='gd-ex-line'>・<span class='gd-jp'>車で来たから、お酒を飲むわけにはいかない。</span>（我開車來的，總不能喝酒）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は大事な会議だから、休むわけにはいかない。</span>（明天有重要的會議，不能請假）</div><div class='gd-sec'><span class='gd-tag'>總不能不做</span>其實不太想，但人情、責任擺在那裡，只好做。</div><div class='gd-ex-line'>・<span class='gd-jp'>先輩に頼まれたから、手伝わないわけにはいかない。</span>（學長拜託我的，總不能不幫）</div><div class='gd-ex-line'>・<span class='gd-jp'>約束したから、行かないわけにはいかない。</span>（都約好了，不能不去）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>わけにもいかない</span>把は換成も，變成「<b>也</b>不能～」，常用在左右為難的時候。</div><div class='gd-ex-line'>・<span class='gd-jp'>早く帰りたいけど、先に帰るわけにもいかない。</span>（很想早點回家，但也不好意思先走）</div><div class='gd-sec'>講話快的時候，は有時會省略，說成<span class='gd-jp'>わけにいかない</span>，意思一樣。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・「不會、能力做不到」不能用它。「我不會游泳」是<span class='gd-jp'>泳げない</span>，不是泳ぐわけにはいかない。<br>・結尾是<b>いかない</b>，不是いけない。「わけにはいけない」是錯的。<br>・前面是肯定還是否定，意思剛好相反：<span class='gd-jp'>飲むわけにはいかない</span>＝不能喝；<span class='gd-jp'>飲まないわけにはいかない</span>＝不能不喝。<br>・單純「不想做」不要用它，那是<span class='gd-jp'>行きたくない</span>。わけにはいかない背後一定有一個「照理說」的理由。<br>・大多用在講<b>自己</b>的處境，是說話的人覺得「我總不能～」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講公司聚餐，看看差在哪：<br><b>可能形的否定</b>＝條件上做不到：<span class='gd-jp'>熱があって、飲み会に行けない。</span>（發燒了，去不了）<br><b>わけにはいかない</b>＝人情、立場上總不能：<span class='gd-jp'>部長も来るから、行かないわけにはいかない。</span>（部長也會來，總不能不去）<br><b>わけがない</b>＝我判斷不可能：<span class='gd-jp'>田中さんは忙しいから、来るわけがない。</span>（田中那麼忙，不可能會來）<br><b>わけではない</b>＝並不是：<span class='gd-jp'>飲み会が嫌いなわけではない。</span>（我並不是討厭聚餐）</div><div class='gd-warn'>判斷小訣竅：「做不到」用可能形，「總不能～」是わけにはいかない，「不可能」是わけがない，「並不是」是わけではない。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>N2 的「〜ざるを得ない」也是「不得不～」，語氣比較硬、比較書面：<span class='gd-jp'>行かざるを得ない。</span>（不得不去）</div>",
  "n3-61": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜べきだ」就是中文的<b>「本來就應該～」「做人就該～」</b>。它不是在猜事情會怎樣，而是在講<b>是非對錯</b>，表示你覺得這樣做才對。像我們說「借錢就應該還」，日文就是<span class='gd-jp'>借りたお金は返すべきだ。</span></div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞辭書形＋べきだ</b><br><span class='gd-pair'><span class='gd-jp'>守る</span> → <span class='gd-jp'>守るべきだ</span></span>（應該遵守）<br><span class='gd-pair'><span class='gd-jp'>謝る</span> → <span class='gd-jp'>謝るべきだ</span></span>（應該道歉）</div><div class='gd-sec'><b>說「不應該」</b>：一樣用辭書形，把「だ」換成「ではない」。<br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言うべきではない</span></span>（不應該說）</div><div class='gd-sec'><b>する比較特別</b>：<span class='gd-jp'>するべき</span>、<span class='gd-jp'>すべき</span>兩個都對。文章、新聞裡比較常看到<span class='gd-jp'>すべき</span>，講話時兩種都聽得到。<br><span class='gd-pair'><span class='gd-jp'>確認する</span> → <span class='gd-jp'>確認すべきだ</span></span></div><div class='gd-sec'><b>名詞、な形容詞</b>：後面加「であるべきだ」。<br><span class='gd-pair'><span class='gd-jp'>公平</span> → <span class='gd-jp'>公平であるべきだ</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>先生は公平であるべきだ。</span>（老師應該要公平）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>べきだ／べきです</span>說出你覺得「該做」的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>約束は守るべきだ。</span>（約定就應該遵守）</div><div class='gd-ex-line'>・<span class='gd-jp'>若いうちに、いろいろな経験をするべきです。</span>（趁年輕應該多體驗各種事情）</div><div class='gd-sec'><span class='gd-tag'>べきではない</span>你覺得「不該做」的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>人の悪口を言うべきではない。</span>（不應該說別人壞話）</div><div class='gd-sec'><span class='gd-tag'>べきだった</span>回頭看、帶著後悔：當初應該做，可是沒做。反過來<span class='gd-jp'>べきではなかった</span>就是「當初不該做的」。</div><div class='gd-ex-line'>・<span class='gd-jp'>あのとき、ちゃんと謝るべきだった。</span>（那時候應該好好道歉的）</div><div class='gd-ex-line'>・<span class='gd-jp'>あんなこと、言うべきではなかった。</span>（那種話真不該說）</div><div class='gd-sec'><span class='gd-tag'>べき＋名詞</span>「該～的…」，直接放在名詞前面。</div><div class='gd-ex-line'>・<span class='gd-jp'>今やるべきことは何だろう。</span>（現在該做的事是什麼呢）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・否定不要說「言わないべき」，要說<span class='gd-jp'>言うべきではない</span>。べき前面固定用辭書形。<br>・する不會變成「しべき」，只有<span class='gd-jp'>するべき</span>或<span class='gd-jp'>すべき</span>。<br>・語氣很強，帶有「你這樣做才對」的說教感。對上司、長輩直接說「〜べきです」，很容易聽起來像在教訓人。想給建議，改用<span class='gd-jp'>〜たほうがいいと思います</span>；就算要用べき，也至少加上<span class='gd-jp'>と思います</span>，讓語氣緩和一點。<br>・べき是<b>說話的人自己覺得</b>該做，不是規定。法律、校規那種非做不可的事，要用<span class='gd-jp'>〜なければならない</span>：<span class='gd-jp'>日本では、車は左側を走らなければならない。</span>（在日本，車子必須靠左行駛）這裡換成べき，會變成像在發表個人意見，很奇怪。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>べき vs はず</b>：中文的「應該」其實有兩種意思，日文分成兩種說法。<br><b>べき</b>＝<b>該做</b>（是非判斷）<br><b>はず</b>＝<b>應該會、應該是</b>（推測）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは約束を守るべきだ。</span>（田中應該遵守約定：我認為他該這樣做）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは約束を守るはずだ。</span>（田中應該會守約：我推測他會）</div><div class='gd-sec'><b>べきではない vs ものではない</b>：兩個都能翻成「不應該」。<span class='gd-jp'>ものではない</span>是在講社會常識、大家都知道的道理，很像長輩教小孩「做人本來就不該這樣」；<span class='gd-jp'>べきではない</span>比較像說話的人自己的判斷和主張。</div><div class='gd-ex-line'>・<span class='gd-jp'>約束を破るものではない。</span>（約定本來就不能毀：做人的常識）</div><div class='gd-ex-line'>・<span class='gd-jp'>約束を破るべきではない。</span>（不應該毀約：我認為這樣不對）</div><div class='gd-warn'>判斷小訣竅：「該做／不該做」用べき，「應該會／應該是」用はず；用「做人本來就不該～」這種講常識的口氣，就用ものではない。</div>",
  "n3-3": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'><span class='gd-jp'>〜について</span>就是中文的<b>「關於～」「針對～」</b>。你先丟出一個話題，後面再接「說、問、查、想」這類動詞，告訴對方你在聊、在研究的<b>內容</b>是什麼。</div><div class='gd-ex-line'>・<span class='gd-jp'>この映画についてどう思う？</span>（你覺得這部電影怎麼樣？）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>後面接動詞</b>：名詞＋について<br><span class='gd-pair'><span class='gd-jp'>日本の文化</span> → <span class='gd-jp'>日本の文化について調べる</span></span>（查日本文化）<br><b>後面接名詞</b>：名詞＋<b>についての</b>＋名詞<br><span class='gd-pair'><span class='gd-jp'>日本の文化</span> → <span class='gd-jp'>日本の文化についての本</span></span>（關於日本文化的書）<br><b>前面是一整句</b>：先加「こと」或「か」，把它變成一個話題。<br><span class='gd-pair'><span class='gd-jp'>留学する</span> → <span class='gd-jp'>留学することについて</span></span>（關於留學這件事）<br><span class='gd-pair'><span class='gd-jp'>どうする</span> → <span class='gd-jp'>どうするかについて話し合う</span></span>（討論要怎麼做）</div><div class='gd-sec'>記憶小幫手：<span class='gd-jp'>について</span>本來是「に＋就いて」，有「就著這件事」的感覺，所以是在講某個主題。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>について＋動詞</span>最基本的用法，後面多半是「說、寫、問、查、想」。</div><div class='gd-ex-line'>・<span class='gd-jp'>将来について考えたことある？</span>（你有想過將來的事嗎？）</div><div class='gd-ex-line'>・<span class='gd-jp'>旅行の予定について話しましょう。</span>（來聊聊旅行的計畫吧）</div><div class='gd-sec'><span class='gd-tag'>についての＋名詞</span>修飾後面的名詞，像中文「關於～的…」。</div><div class='gd-ex-line'>・<span class='gd-jp'>日本の歴史についての本を読んでいます。</span>（我在讀一本關於日本歷史的書）</div><div class='gd-sec'><span class='gd-tag'>については</span>把話題拎出來單獨講，有「～的部分呢」的感覺。</div><div class='gd-ex-line'>・<span class='gd-jp'>料金については、受付で聞いてください。</span>（費用的部分，請到櫃檯詢問）</div><div class='gd-sec'><span class='gd-tag'>につきまして</span>超客氣的版本，客服、公司公告很常聽到。</div><div class='gd-ex-line'>・<span class='gd-jp'>この件につきましては、後ほどご連絡いたします。</span>（這件事我們稍後再跟您聯絡）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・後面接名詞時一定要加「の」：<span class='gd-jp'>日本の文化について本</span>是錯的，要說<span class='gd-jp'>日本の文化についての本</span>。<br>・前面是動詞時要先加こと：<span class='gd-jp'>日本で働くについて</span>是錯的，要說<span class='gd-jp'>日本で働くことについて</span>。<br>・中文「關於」很好用，但<span class='gd-jp'>について</span>後面要接跟「內容」有關的動作（說、問、查、想、討論）。小心<span class='gd-jp'>先生について行く</span>是另一個詞，意思是「跟著老師走」，不是「關於老師去」。<br>・<span class='gd-jp'>私について</span>（關於我）跟<span class='gd-jp'>私にとって</span>（對我來說）只差一點點，意思完全不同。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講「孩子」，換一個詞意思就差很多：<br><b>について</b>＝談論的<b>主題</b>：<span class='gd-jp'>子どもの教育について話す。</span>（談孩子的教育）<br><b>に対して</b>＝態度、動作<b>衝著誰</b>：<span class='gd-jp'>子どもに対して優しい。</span>（對孩子很溫柔）<br><b>にとって</b>＝站在誰的<b>立場</b>評價：<span class='gd-jp'>子どもにとって大切なことだ。</span>（對孩子來說是很重要的事）</div><div class='gd-sec'>還有一個意思幾乎一樣的<b>に関して</b>，大多數時候可以互換，只是比較正式、比較硬，常見於公告、新聞、報告：<br><span class='gd-jp'>新しいルールについて説明します。</span>（我來說明新規定，平常講話）<br><span class='gd-jp'>新しいルールに関して説明します。</span>（就新規定進行說明，比較正式）<br>修飾名詞時，<span class='gd-jp'>についての</span>對應的是<span class='gd-jp'>に関する</span>。</div><div class='gd-warn'>判斷小訣竅：在講「聊什麼、查什麼」用について；「對誰怎麼樣」用に対して；「對誰來說」用にとって；寫正式文件想講「關於」，可以換成に関して。</div>",
  "n3-2": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜に対して」有兩個意思：<br>第一個是<b>「對～」「針對～」</b>，像一支箭頭，指出態度、動作、反應是朝著誰或什麼去的。<br>第二個是<b>「相對於～」</b>，把兩邊擺在一起比：A 是這樣，B 卻是那樣。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>態度的對象</span>對某人很嚴格、很溫柔、很有禮貌。</div><div class='gd-ex-line'>・<span class='gd-jp'>先生は学生に対して厳しい。</span>（老師對學生很嚴格）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は誰に対しても優しい。</span>（她對誰都很溫柔）</div><div class='gd-sec'><span class='gd-tag'>回應的對象</span>針對問題、意見、提案做出回答或反應。</div><div class='gd-ex-line'>・<span class='gd-jp'>質問に対して、丁寧に答えた。</span>（針對問題，很仔細地回答了）</div><div class='gd-ex-line'>・<span class='gd-jp'>新しいルールに対して、反対の意見が多い。</span>（對新規定持反對意見的人很多）</div><div class='gd-sec'><span class='gd-tag'>對比</span>兩邊明顯不一樣的時候。</div><div class='gd-ex-line'>・<span class='gd-jp'>兄が静かなのに対して、弟はにぎやかだ。</span>（哥哥很安靜，相對地弟弟很吵鬧）</div><div class='gd-ex-line'>・<span class='gd-jp'>東京は雨だったのに対して、大阪は晴れていた。</span>（東京下雨，相對地大阪是晴天）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>「對～」的用法</b>：名詞直接加に対して。<br><span class='gd-pair'><span class='gd-jp'>お客様</span> → <span class='gd-jp'>お客様に対して</span></span><br>後面要接名詞的時候，改成<b>に対する</b>：<br><span class='gd-pair'><span class='gd-jp'>先生に対して</span> → <span class='gd-jp'>先生に対する態度</span>（對老師的態度）</span></div><div class='gd-sec'><b>「相對於～」的用法</b>：前面放一整句話，再加<b>のに対して</b>。<br>動詞、い形容詞直接接：<span class='gd-pair'><span class='gd-jp'>よく食べる</span> → <span class='gd-jp'>よく食べるのに対して</span></span><br>な形容詞、名詞要先加「な」：<span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなのに対して</span></span><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生なのに対して</span></span><br>過去的事就用過去形：<span class='gd-pair'><span class='gd-jp'>雨だった</span> → <span class='gd-jp'>雨だったのに対して</span></span></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面的助詞是<b>に</b>，不是を：寫成「先生を対して」是錯的。<br>・後面接名詞要用<b>に対する</b>：說「先生に対して態度」是錯的，要說<span class='gd-jp'>先生に対する態度</span>。<br>・對比用法前面一定要有「の」：說「静かに対して」是錯的，要說<span class='gd-jp'>静かなのに対して</span>。<br>・中文的「對」很萬用，日文可不是每個「對」都能換成に対して。「對身體好」是<span class='gd-jp'>体にいい</span>；「對日本文化有興趣」是<span class='gd-jp'>日本文化に興味がある</span>；「對我來說」是<span class='gd-jp'>私にとって</span>。<br>・に対して聽起來比較正式。日常聊天說「對朋友很好」，講<span class='gd-jp'>友達に優しい</span>就很自然了。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣都是「新規定」這件事，換個說法，意思就不一樣：<br><b>について</b>＝話題是什麼（關於～）：<span class='gd-jp'>新しいルールについて説明した。</span>（說明了關於新規定的內容）<br><b>に対して</b>＝態度、反應朝向誰或什麼（對～）：<span class='gd-jp'>新しいルールに対して、文句を言う人が多い。</span>（對新規定抱怨的人很多）<br><b>にとって</b>＝站在誰的立場來評價（對～來說）：<span class='gd-jp'>学生にとって、新しいルールは厳しすぎる。</span>（對學生來說，新規定太嚴了）</div><div class='gd-sec'>最容易搞混的是這一組：<br><span class='gd-jp'>先生は学生に対して厳しい。</span>（老師對學生很嚴：嚴格的是老師）<br><span class='gd-jp'>この試験は学生にとって難しい。</span>（這個考試對學生來說很難：覺得難的是學生）<br>另外，<b>に関して</b>的意思跟について一樣，只是比較正式。</div><div class='gd-warn'>判斷小訣竅：講「關於什麼話題」用について；講「對誰怎麼樣、對什麼有反應」用に対して；講「對誰來說是怎樣」用にとって。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>接著學<span class='gd-jp'>〜にとって</span>和<span class='gd-jp'>〜に関して</span>，把這幾個「對、關於」一次分清楚。</div>",
  "n3-8": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜にとって」就是中文的<b>「對～來說」</b>。先講是站在誰的角度，後面再說這件事對他來說<b>重不重要、難不難、好不好</b>。同一件事，換個人來看，感受可能完全不一樣，にとって就是用來交代「這是誰的感受」。</div><div class='gd-ex-line'>・<span class='gd-jp'>私にとって、家族が一番大切です。</span>（對我來說，家人最重要）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞直接加にとって就好，最常放人，也可以放動物、公司、國家。<br><span class='gd-pair'><span class='gd-jp'>私</span> → <span class='gd-jp'>私にとって</span></span><span class='gd-pair'><span class='gd-jp'>外国人</span> → <span class='gd-jp'>外国人にとって</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>外国人にとって、敬語は難しい。</span>（對外國人來說，敬語很難）</div><div class='gd-ex-line'>・<span class='gd-jp'>猫にとって、この部屋は暑すぎるかもしれない。</span>（對貓來說，這個房間可能太熱了）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>にとって</span>可以放句首，也可以放句中，表示「站在某人的立場來看」這件事怎麼樣，後面加不加逗號都可以。</div><div class='gd-ex-line'>・<span class='gd-jp'>この経験は私にとって大きな財産だ。</span>（這段經驗對我來說是很大的財富）</div><div class='gd-sec'><span class='gd-tag'>にとっては</span>多了一個は，帶有「對他來說是這樣，對別人就不一定」的比較感。</div><div class='gd-ex-line'>・<span class='gd-jp'>大人にとっては短い時間でも、子供にとっては長い。</span>（對大人來說很短的時間，對小孩來說卻很長）</div><div class='gd-sec'><span class='gd-tag'>にとっての＋名詞</span>要把「對～來說的…」整個黏成一個名詞，中間要加<b>の</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>子供にとっての幸せを考えてみましょう。</span>（來想想對孩子來說的幸福是什麼）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・にとって後面接的是<b>評價</b>：大切、難しい、便利、貴重、意味がある這類。不能接「對人的態度或動作」。「老師對學生很親切」要說<span class='gd-jp'>先生は学生に対して親切だ</span>，說成先生は学生にとって親切だ是錯的。<br>・中文的「對」一個字包山包海，日文要分開。不要看到「對」就反射寫にとって。<br>・の的問題：<span class='gd-jp'>私にとって、幸せは家族と過ごす時間です。</span>這句完全正確，にとって是在修飾整句話。只有要做成「對～來說的＋名詞」這種一整塊名詞，例如放在を前面當受詞時，才一定要用<span class='gd-jp'>にとっての</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣跟「學生」有關，換個文法意思就不同：<br><b>にとって</b>＝站在學生的角度<b>評價</b>：<span class='gd-jp'>学生にとって、この先生は怖い存在だ。</span>（對學生來說，這位老師是可怕的存在）<br><b>に対して</b>＝態度、動作<b>朝向</b>學生：<span class='gd-jp'>この先生は学生に対して厳しい。</span>（這位老師對學生很嚴格）<br><b>について</b>＝講話、思考的<b>主題</b>：<span class='gd-jp'>先生は学生について話した。</span>（老師談到了學生的事）</div><div class='gd-sec'>另一個常搞混的是<b>として</b>，它是「以～的身分」：<br><span class='gd-jp'>親として、子供を守りたい。</span>（身為父母，我想保護孩子）<br><span class='gd-jp'>親にとって、子供は宝物だ。</span>（對父母來說，孩子是寶貝）</div><div class='gd-warn'>判斷小訣竅：後面是「重要、難、珍貴」這種感受評價，用にとって；後面是「嚴格、親切、反對」這種對人的態度，用に対して；後面是「說、調查、討論」，用について；想說「身為～」，用として。</div>",
  "n3-28": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜に関して」就是<b>「關於～」「有關～」</b>，意思跟「〜について」差不多，但聽起來比較<b>正式、比較硬</b>。就像中文平常聊天說「關於那件事」，公司公告、新聞就會寫「有關本案」。你在新聞、公司通知、學校公告、客服回覆裡會很常看到它。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面一律接<b>名詞</b>，後面要接什麼，決定用哪個樣子：</div><div class='gd-sec'><span class='gd-tag'>後面接句子</span>名詞＋に関して，後面接一整句話（做什麼、怎麼樣）。</div><div class='gd-ex-line'>・<span class='gd-jp'>事故の原因に関して、今調べています。</span>（關於事故原因，現在正在調查）</div><div class='gd-ex-line'>・<span class='gd-jp'>この件に関して、何か質問はありますか。</span>（關於這件事，有什麼問題嗎？）</div><div class='gd-sec'><span class='gd-tag'>後面接名詞</span>名詞＋に関する＋名詞，用來修飾後面的東西，變成「有關～的〇〇」。</div><div class='gd-ex-line'>・<span class='gd-jp'>環境問題に関する本を探しています。</span>（我在找有關環境問題的書）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本の文化に関するレポートを書きました。</span>（我寫了一份關於日本文化的報告）</div><div class='gd-sec'>後面接名詞時，也可以說<span class='gd-jp'>に関しての</span>，例如<span class='gd-jp'>環境問題に関しての本</span>，意思一樣。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>に関しては</span>加上「は」，有「〇〇的部分呢」的感覺，常用在說明或回答問題。</div><div class='gd-ex-line'>・<span class='gd-jp'>料金に関しては、こちらをご覧ください。</span>（費用的部分，請看這邊）</div><div class='gd-sec'><span class='gd-tag'>に関しまして</span>更客氣的版本，商務電話、正式場合說明時很常聽到。</div><div class='gd-ex-line'>・<span class='gd-jp'>この件に関しまして、後ほどご連絡いたします。</span>（關於這件事，稍後會再跟您聯絡）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・後面接名詞時，要用<b>に関する</b>或<b>に関しての</b>。<span class='gd-jp'>環境問題に関して本</span>是錯的，要說<span class='gd-jp'>環境問題に関する本</span>。<br>・它很正式，跟朋友聊天用會怪怪的，像在開會。朋友之間說「昨天的電影」這種話題，用<span class='gd-jp'>について</span>就好。<br>・中文的「對～」不一定能換成に関して。「對客人很客氣」的「對」是態度朝向某人，要用<span class='gd-jp'>に対して</span>，不能用に関して。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>について</b>＝「關於～」，日常、正式都能用，範圍最廣。<b>に関して</b>意思一樣，只是更正式。<br><span class='gd-jp'>昨日の試合について話そうよ。</span>（來聊聊昨天的比賽吧：朋友聊天）<br><span class='gd-jp'>昨日の試合に関して、監督がコメントを発表した。</span>（關於昨天的比賽，教練發表了評論：新聞）<br>順便記一下：について後面接名詞是<span class='gd-jp'>についての</span>，例如<span class='gd-jp'>日本についての本</span>。</div><div class='gd-sec'><b>に対して</b>＝「對著～」，講的是態度、動作朝向誰。<br><span class='gd-jp'>お客様に対して、丁寧な言葉を使います。</span>（對客人要用禮貌的說法）<br>這句不能換成に関して，因為你不是在講「有關客人的話題」，而是「對著客人說話」。</div><div class='gd-sec'><b>にとって</b>＝「對～來說」，站在某人的立場來評價。<br><span class='gd-jp'>私にとって、家族が一番大切です。</span>（對我來說，家人最重要）</div><div class='gd-warn'>判斷小訣竅：中文能說成「有關～、～相關的」，就用に関して（正式）或について（日常）；「對著某人怎麼樣」用に対して；「對某人來說」用にとって。</div>",
  "n3-13": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜うちに」最常見的意思就是中文的<b>「趁～」</b>，像「打鐵趁熱」：現在這個狀態<b>之後會變</b>，所以要趁還來得及，趕快做。另外它還有一個意思是<b>「～著～著，不知不覺就…」</b>，兩個都很常用。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>趁～的時候</span>現在的狀態（熱、年輕、還是學生）不會一直持續，要把握機會。</div><div class='gd-ex-line'>・<span class='gd-jp'>熱いうちに召し上がってください。</span>（請趁熱吃）</div><div class='gd-ex-line'>・<span class='gd-jp'>学生のうちに、たくさん本を読んでおきたい。</span>（想趁還是學生的時候多讀點書）</div><div class='gd-ex-line'>・<span class='gd-jp'>両親が元気なうちに、一緒に旅行したい。</span>（想趁爸媽還健康的時候，跟他們一起去旅行）</div><div class='gd-sec'><span class='gd-tag'>趁還沒～</span>用ない形＋うちに，意思是「趁某件事還沒發生」，有一點趕時間的感覺。</div><div class='gd-ex-line'>・<span class='gd-jp'>暗くならないうちに帰ろう。</span>（趁天還沒黑回家吧）</div><div class='gd-ex-line'>・<span class='gd-jp'>忘れないうちに、メモしておこう。</span>（趁還沒忘，先記下來）</div><div class='gd-sec'><span class='gd-tag'>不知不覺就…</span>前面一直在做某件事，做著做著，後面就出現了一個變化。</div><div class='gd-ex-line'>・<span class='gd-jp'>話しているうちに、仲良くなった。</span>（聊著聊著就變熟了）</div><div class='gd-ex-line'>・<span class='gd-jp'>何度も聞いているうちに、歌詞を覚えた。</span>（聽了好幾次，就把歌詞記起來了）</div><div class='gd-ex-line'>・<span class='gd-jp'>知らないうちに寝てしまった。</span>（不知不覺就睡著了）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞ている形：<span class='gd-pair'><span class='gd-jp'>話している</span> → <span class='gd-jp'>話しているうちに</span></span><br>動詞ない形：<span class='gd-pair'><span class='gd-jp'>忘れない</span> → <span class='gd-jp'>忘れないうちに</span></span><br>い形容詞：直接接　<span class='gd-pair'><span class='gd-jp'>熱い</span> → <span class='gd-jp'>熱いうちに</span></span><br>な形容詞：要加な　<span class='gd-pair'><span class='gd-jp'>元気</span> → <span class='gd-jp'>元気なうちに</span></span><br>名詞：要加の　<span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生のうちに</span></span><br>動詞辭書形也可以接，但多半是「狀態」的動詞，像<span class='gd-jp'>日本にいるうちに</span>（趁還在日本的時候）。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・不能接た形：<b>×話したうちに</b>，要說<span class='gd-jp'>話しているうちに</span>。<br>・な形容詞跟名詞別接錯：<span class='gd-jp'>元気なうちに</span>不是元気のうちに；<span class='gd-jp'>学生のうちに</span>不是学生なうちに；い形容詞不加の，<span class='gd-jp'>若いうちに</span>不是若いのうちに。<br>・「ないうちに」看到否定別緊張，它是「<b>趁還沒</b>」，不是「沒有在～的時候」。<br>・「趁～」的用法，後面常接自己想做、要做的事：<span class='gd-jp'>〜ておこう</span>、<span class='gd-jp'>〜たい</span>、<span class='gd-jp'>〜てください</span>。<br>・「不知不覺」的用法，後面是自然發生的變化，常見<span class='gd-jp'>〜なった</span>、<span class='gd-jp'>〜てしまった</span>，不是自己要做的事。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>間に</b>＝單純講「在那段時間裡」，沒有特別的情緒：<span class='gd-jp'>日本にいる間に、富士山に登りたい。</span>（想在日本的期間爬富士山）<br><b>うちに</b>＝帶著「<b>趁還在，之後就沒機會了</b>」的感覺：<span class='gd-jp'>日本にいるうちに、富士山に登りたい。</span>（想趁還在日本的時候爬富士山）<br>如果時間有清楚的開始跟結束，像「3點到5點之間」，只能用<span class='gd-jp'>3時から5時の間に</span>，不能用うちに。</div><div class='gd-sec'><b>前に</b>跟<b>ないうちに</b>也很像：<br><span class='gd-jp'>雨が降る前に帰ろう。</span>（下雨前回家吧：單純講順序）<br><span class='gd-jp'>雨が降らないうちに帰ろう。</span>（趁還沒下雨趕快回家吧：比較有趕時間的感覺）</div><div class='gd-warn'>判斷小訣竅：想說「趁還來得及，快做」就用うちに；只是交代「在那段時間」用間に；只是講先後順序用前に。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>可以接著看「〜間に」跟「〜最中に」（正在～的時候），三個一起比較，講「時間」的說法就不會搞混。</div>",
  "n3-20": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ば〜ほど」就是中文的<b>「越～越～」</b>。像「越練越強」「越想越煩」，前面那件事做得越多、程度越高，後面的結果就跟著越明顯。<br>日文的做法是：<b>同一個詞講兩次</b>，第一次用ば形（「如果～」的形），第二次用原本的樣子，最後加ほど。</div><div class='gd-ex-line'>・<span class='gd-jp'>練習すればするほど上手になる。</span>（越練習越厲害）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>動詞</span>先變ば形，後面接同一個動詞的辭書形（字典上的原形），再加ほど。<br><b>第一類（五段動詞）</b>：最後一個音換成同一行的「え」段音，加ば。<br><span class='gd-pair'><span class='gd-jp'>読む</span> → む換成め → <span class='gd-jp'>読めば読むほど</span></span><br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行けば行くほど</span></span><br><b>第二類（一段動詞）</b>：把「る」拿掉，加れば。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べれば食べるほど</span></span><br><b>第三類</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>すればするほど</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来れば来るほど</span>（くればくるほど）</span><br>「<span class='gd-jp'>勉強する</span>」這種「名詞＋する」的動詞，第二次通常只留する：<span class='gd-jp'>勉強すればするほど</span>。</div><div class='gd-sec'><span class='gd-tag'>い形容詞</span>把「い」拿掉，加ければ，後面接原本的い形容詞＋ほど。<br><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安ければ安いほど</span></span></div><div class='gd-sec'><span class='gd-tag'>な形容詞</span>前面用なら，後面加な＋ほど。<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなら静かなほど</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語は勉強すればするほど面白くなる。</span>（日文越學越有趣）</div><div class='gd-ex-line'>・<span class='gd-jp'>この本は読めば読むほど好きになる。</span>（這本書越看越喜歡）</div><div class='gd-ex-line'>・<span class='gd-jp'>返事は早ければ早いほどいいです。</span>（越早回覆越好）</div><div class='gd-ex-line'>・<span class='gd-jp'>部屋は静かなら静かなほどいい。</span>（房間越安靜越好）</div><div class='gd-sec'>「<span class='gd-jp'>早ければ早いほどいい</span>」「<span class='gd-jp'>多ければ多いほどいい</span>」幾乎是固定說法，整句背起來很好用。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前後一定是<b>同一個詞</b>。中文是「越A越B」，日文是把A講兩次，B放在後面的句子裡。<br>・後面那次用原形，不要再用ば：是<span class='gd-jp'>考えれば考えるほど</span>，不是考えれば考えればほど。<br>・<span class='gd-jp'>いい</span>的ば形是<span class='gd-jp'>よければ</span>，不是いければ：<span class='gd-jp'>よければよいほど</span>。<br>・<span class='gd-jp'>来れば</span>念くれば，不是きれば。<br>・な形容詞前面是なら、後面是な，兩邊不一樣，別寫成<span class='gd-jp'>静かなら静かならほど</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>〜ば〜ほど</b>：<span class='gd-jp'>練習すればするほど上手になる。</span>（越練習越厲害）<br><b>〜ほど</b>（把前面的ば省掉）：<span class='gd-jp'>練習するほど上手になる。</span>（意思一樣）<br>省掉ば的版本比較簡短；有ば的版本把「越～越～」的感覺講得更清楚、更強烈。<br><b>〜とともに</b>：<span class='gd-jp'>年をとるとともに、体力が落ちる。</span>（隨著年紀增長，體力會下滑）<br>對照：<span class='gd-jp'>年をとればとるほど、体力が落ちる。</span>（年紀越大，體力越差）<br>とともに是「隨著～」，比較正式、書面；ば〜ほど是「越～越～」，口語跟書面都很常用。</div><div class='gd-warn'>判斷小訣竅：中文想講「越～越～」，就用ば〜ほど；想講比較正式的「隨著～」，才用とともに。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>單獨的「〜ほど」還有「到～的程度」的用法，例如<span class='gd-jp'>泣きたいほど痛い</span>（痛到想哭），可以接著看「〜ほど」那張卡。</div>",
  "n3-21": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「<span class='gd-jp'>〜ないことはない</span>」就是中文的<b>「也不是不～啦」</b>。兩個「不」疊在一起，意思其實是「可以」，但是<b>打了折的可以</b>：勉強做得到、有那個可能，只是不太想、不太積極。就像朋友約你凌晨四點去爬山，你回「也不是不能去啦…」，大家都聽得出來你不太想去。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞先變成ない形，後面加<span class='gd-jp'>ことはない</span>或<span class='gd-jp'>こともない</span>。<br><span class='gd-pair'><span class='gd-jp'>行ける</span> → <span class='gd-jp'>行けない</span> → <span class='gd-jp'>行けないことはない</span></span>（也不是不能去）<br><span class='gd-pair'><span class='gd-jp'>食べられる</span> → <span class='gd-jp'>食べられない</span> → <span class='gd-jp'>食べられないこともない</span></span>（也不是不能吃）<br>最常跟「能不能」的說法一起用，也就是<span class='gd-jp'>行ける</span>、<span class='gd-jp'>できる</span>、<span class='gd-jp'>食べられる</span>這種，因為這個句型本來就很常在講「做不做得到」。</div><div class='gd-sec'>還不熟ない形的話，複習一下：<br><b>第一類（五段動詞）</b>：最後一個音換成同一行的「あ」段音，再加ない。<span class='gd-pair'><span class='gd-jp'>行く</span> → く換成か → <span class='gd-jp'>行かない</span></span>；う結尾的要換成わ：<span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会わない</span></span><br><b>第二類（一段動詞）</b>：把「る」拿掉，加ない。<span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べない</span></span><br><b>第三類（する・来る）</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しない</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ない</span>（こない）</span></div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>勉強做得到</span>有點吃力，但硬要做還是可以。</div><div class='gd-ex-line'>・<span class='gd-jp'>この量なら、一人で食べられないことはない。</span>（這個份量的話，一個人也不是吃不完）</div><div class='gd-sec'><span class='gd-tag'>後面接但書</span>最常見的樣子是後面加「<span class='gd-jp'>けど</span>／<span class='gd-jp'>が</span>」，再講出真正的顧慮。</div><div class='gd-ex-line'>・<span class='gd-jp'>駅まで歩けないことはないけど、ちょっと遠いね。</span>（走到車站也不是走不到，只是有點遠耶）</div><div class='gd-ex-line'>・<span class='gd-jp'>行けないこともないが、あまり気が進まない。</span>（也不是不能去，只是不太想去）</div><div class='gd-sec'><span class='gd-tag'>保留地回答</span>被問的時候，不想一口答應、又不想直接拒絕。</div><div class='gd-ex-line'>・<span class='gd-jp'>明日までにできる？</span>（明天之前做得完嗎？）</div><div class='gd-ex-line'>・<span class='gd-jp'>できないことはないですけど…。</span>（也不是做不完啦…）</div><div class='gd-sec'><b>ことはない跟こともない差在哪？</b>意思幾乎一樣，可以互換。<span class='gd-jp'>こともない</span>多了一個「も」，口氣更軟、更含糊一點，像在說「其實…也算可以吧」。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・這句話的意思是<b>肯定</b>。<span class='gd-jp'>行けないことはない</span>＝可以去（只是不太情願），別看到兩個「不」就以為是「不能去」。<br>・它<b>不是爽快的「可以」</b>。朋友約你，你回<span class='gd-jp'>行けないことはない</span>，對方會覺得你不太想來。真心想去就說<span class='gd-jp'>行けるよ</span>、<span class='gd-jp'>いいね、行こう</span>。對主管或客戶這樣回，也容易被當成不太配合。<br>・前面一定是<b>ない形</b>。少了ない，<span class='gd-jp'>行くことはない</span>就變成「不必去」，意思完全不一樣。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講「卡拉OK」，只差前面接什麼，意思就完全不同：<br><b>ない形＋ことはない</b>＝也不是不～：<span class='gd-jp'>カラオケは行かないことはないけど、年に一回くらいかな。</span>（卡拉OK也不是不去啦，大概一年一次吧）<br><b>辭書形＋ことはない</b>＝不必～：<span class='gd-jp'>嫌なら、無理して行くことはないよ。</span>（不喜歡的話，不必勉強去啦）<br><b>た形＋ことはない</b>＝沒有～過：<span class='gd-jp'>カラオケには一度も行ったことはない。</span>（我一次也沒去過卡拉OK）<br><b>ないわけではない</b>＝並不是～：<span class='gd-jp'>カラオケが好きじゃないわけではない。</span>（我並不是不喜歡卡拉OK）<br>最後這個跟ないことはない很接近。差別在<span class='gd-jp'>わけではない</span>的重點是更正對方的誤會：「事情不是你想的那樣」；<span class='gd-jp'>ないことはない</span>的重點是「有可能、勉強可以」。</div><div class='gd-warn'>判斷小訣竅：前面有「ない」＋<span class='gd-jp'>ことはない</span>＝「也不是不～」；辭書形＋<span class='gd-jp'>ことはない</span>＝「不必～」；た形＋<span class='gd-jp'>ことはない</span>＝「沒有～過」，又是另一個意思；想更正別人的誤會，用<span class='gd-jp'>わけではない</span>。</div>",
  "n3-29": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜わりに」就是中文的<b>「以～來說，算是很…」「照理說應該～，結果卻…」</b>。先從前面那件事想像一個「應該會怎樣」，結果實際情況跟想的不一樣，就用わりに。像跟朋友說「這家店以這個價錢來說，份量很多欸」，就是わりに的感覺。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>好的意外</span>結果比想像中好。</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は、値段のわりに量が多い。</span>（這家店以價錢來說，份量算多）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼はよく食べるわりに、太らない。</span>（他那麼會吃，卻都不會胖）</div><div class='gd-sec'><span class='gd-tag'>不好的意外</span>結果比想像中差，有點失望的口氣。</div><div class='gd-ex-line'>・<span class='gd-jp'>よく勉強したわりに、点数が悪かった。</span>（以讀書讀的量來說，分數算差）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は体が大きいわりには、気が小さい。</span>（他塊頭那麼大，膽子卻很小）</div><div class='gd-sec'>想加強語氣，可以說成<b>わりには</b>，意思一樣。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：直接接，過去的事就用た形。<br><span class='gd-pair'><span class='gd-jp'>よく食べる</span> → <span class='gd-jp'>よく食べるわりに</span></span><br><span class='gd-pair'><span class='gd-jp'>勉強した</span> → <span class='gd-jp'>勉強したわりに</span></span><br><b>い形容詞</b>：直接接。<br><span class='gd-pair'><span class='gd-jp'>近い</span> → <span class='gd-jp'>近いわりに</span></span><br><b>な形容詞</b>：把だ換成な。<br><span class='gd-pair'><span class='gd-jp'>丈夫だ</span> → <span class='gd-jp'>丈夫なわりに</span></span><br><b>名詞</b>：加の。<br><span class='gd-pair'><span class='gd-jp'>年齢</span> → <span class='gd-jp'>年齢のわりに</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋は駅から近いわりに、家賃が安い。</span>（這間房子離車站很近，房租卻很便宜）</div><div class='gd-ex-line'>・<span class='gd-jp'>このかばんは丈夫なわりに軽い。</span>（這個包包很耐用，卻很輕）</div><div class='gd-ex-line'>・<span class='gd-jp'>父は年齢のわりに元気だ。</span>（我爸以他的年紀來說很有精神）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・な形容詞要用「な」、名詞要加「の」：是<span class='gd-jp'>丈夫なわりに</span>、<span class='gd-jp'>年齢のわりに</span>，不是丈夫だわりに、年齢わりに。<br>・一定要「跟預期不一樣」才能用。貴的東西好吃是理所當然，<span class='gd-jp'>値段が高いわりにおいしい</span>就很怪；要說<span class='gd-jp'>値段が高いわりにおいしくない</span>（那麼貴卻不好吃）才對。<br>・前面最好是有「高低、多少」可以比的東西：年紀、價錢、身高、讀書的量。<br>・後面是在描述、評價，不能接「請～」「～吧」這種要求或邀請。<br>・單獨放在形容詞前面的<span class='gd-jp'>わりに</span>（也常說<span class='gd-jp'>わりと</span>）是另一種用法，意思是「比想像中還～」：<span class='gd-jp'>今日のテストはわりに簡単だった。</span>（今天的考試比想像中簡單）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>にしては</b>也是「以～來說，出乎意料」，中文翻起來幾乎一樣，差別在前面放什麼。<br><b>わりに</b>：前面可以是「年紀、價錢」這種籠統的程度，也可以接形容詞、動詞。<br><b>にしては</b>：前面放具體的數字、身分或事實，像「60歳」「1000円」「初めて」，主要接名詞和動詞，不太接形容詞。</div><div class='gd-ex-line'>・<span class='gd-jp'>父は年齢のわりに若く見える。</span>（我爸以他的年紀來說看起來很年輕）</div><div class='gd-ex-line'>・<span class='gd-jp'>父は60歳にしては若く見える。</span>（以一個60歲的人來說，我爸看起來很年輕）</div><div class='gd-ex-line'>・<span class='gd-jp'>この料理は値段のわりにおいしい。</span>（這道菜以價錢來說很好吃）</div><div class='gd-ex-line'>・<span class='gd-jp'>この料理は1000円にしてはおいしい。</span>（這道菜以1000日圓來說很好吃）</div><div class='gd-sec'>反過來說「年齢にしては」「値段にしては」就不自然，因為「年紀」「價錢」不是一個具體的數字。</div><div class='gd-warn'>判斷小訣竅：前面是「年紀、價錢」這種籠統的程度，或是形容詞，用わりに；前面是「60歲、1000日圓、第一次」這種具體的數字或身分，用にしては。</div>",
  "n3-30": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜にしては」就是中文的<b>「以～來說，算是很…了／竟然…」</b>。你心裡對某個身分或事實有個預期，結果實際情況<b>跟預期不一樣</b>，就用它。<br>例如看到小朋友寫的字很漂亮，你會說「以小孩來說，字很漂亮耶」，這就是<span class='gd-jp'>子どもにしては、字がきれいだ。</span></div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>比預期好</span>本來沒抱太大期待，結果表現不錯，帶一點稱讚。</div><div class='gd-ex-line'>・<span class='gd-jp'>初めて作ったにしては、おいしいね。</span>（以第一次做來說，很好吃耶）</div><div class='gd-ex-line'>・<span class='gd-jp'>新人にしては、よくやっている。</span>（以新人來說，做得很不錯了）</div><div class='gd-sec'><span class='gd-tag'>比預期差</span>本來期待很高，結果讓人失望，帶一點吐槽。</div><div class='gd-ex-line'>・<span class='gd-jp'>有名な店にしては、あまりおいしくなかった。</span>（以名店來說，沒有很好吃）</div><div class='gd-sec'><span class='gd-tag'>天氣、時間</span>跟季節或時間該有的樣子不一樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>4月にしては寒いですね。</span>（以四月來說好冷喔）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>名詞</b>：直接接，中間<b>不加の、也不加だ</b>。<br><span class='gd-pair'><span class='gd-jp'>プロ</span> → <span class='gd-jp'>プロにしては</span></span><span class='gd-pair'><span class='gd-jp'>4月</span> → <span class='gd-jp'>4月にしては</span></span></div><div class='gd-sec'><b>動詞</b>：用普通形（辭書形、た形這類不加ます的說法）。<br><span class='gd-pair'><span class='gd-jp'>初めて作った</span> → <span class='gd-jp'>初めて作ったにしては</span></span><span class='gd-pair'><span class='gd-jp'>3年も住んでいる</span> → <span class='gd-jp'>3年も住んでいるにしては</span></span></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞後面直接接にしては，<b>不要加の</b>：說<span class='gd-jp'>子どもにしては</span>，不說子どものにしては。（加の的是<span class='gd-jp'>子どものわりに</span>，別混在一起。）<br>・前面放的要是<b>具體的身分、數字、事實</b>，像「新人」「60歳」「千円」「初めて」。「年齡」「價格」「身高」這種只是在講一個範圍的詞，不能直接接：說<span class='gd-jp'>値段にしては</span>不自然，要改成<span class='gd-jp'>値段のわりに</span>。<br>・い形容詞一般不直接接にしては，像「安いにしては」聽起來怪，這種要用<span class='gd-jp'>安いわりに</span>。<br>・後半句是你的<b>評價、感想</b>，不接「請～」「我要～」這種命令或決定。<br>・可以拿來講自己：<span class='gd-jp'>私にしては、よく頑張ったと思う。</span>（以我來說，算是很努力了）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>わりに</b>（n3-29）也是「跟預期不一樣」，中文常常都翻成「以～來說」，差別在<b>前面放什麼</b>。<br>同一個情境，一位看起來很年輕的阿伯：<br><span class='gd-jp'>あの人は60歳にしては若く見える。</span>（以60歲來說，他看起來很年輕）→ 前面是具體的「60歳」<br><span class='gd-jp'>あの人は年のわりに若く見える。</span>（他比實際年齡看起來年輕）→ 前面是「年齡」這種範圍詞<br>同一家便宜好吃的店：<br><span class='gd-jp'>千円にしてはおいしい。</span>（以一千塊來說很好吃）<br><span class='gd-jp'>値段のわりにおいしい。</span>／<span class='gd-jp'>安いわりにおいしい。</span>（以這價格來說很好吃／很便宜卻很好吃）<br>另外，にしては比較有「明明是～耶」那種當下的意外感，帶的評價也比較明顯。</div><div class='gd-sec'><b>として</b>（n3-5）也常翻成「以～」，但它是<b>站在那個身分的立場</b>，沒有「跟預期不同」的意思。<br><span class='gd-jp'>先生として、生徒を守りたい。</span>（身為老師，我想保護學生）<br><span class='gd-jp'>先生にしては、字が汚いね。</span>（以老師來說，字還真醜耶）</div><div class='gd-warn'>判斷小訣竅：前面是具體的身分、數字、事實，而且結果讓你意外，用にしては；前面是「年齡、價格」這種範圍詞或形容詞，用わりに；只是在說「身為～」的立場、沒有意外，用として。</div>",
  "n3-5": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜として」就是中文的<b>「身為～」「以～的身分」「當作～」</b>。前面放一個名詞，說明「是用什麼身分、什麼角色、什麼名目」在做這件事。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>身分・立場</span>以某個身分去做事，最常見。</div><div class='gd-ex-line'>・<span class='gd-jp'>留学生として日本に来ました。</span>（我以留學生的身分來到日本）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は医者として、また父として尊敬されている。</span>（他身為醫生、也身為父親，都很受尊敬）</div><div class='gd-sec'><span class='gd-tag'>當作・名目</span>把一樣東西當成某種用途。</div><div class='gd-ex-line'>・<span class='gd-jp'>これはお土産として買いました。</span>（這是買來當伴手禮的）</div><div class='gd-sec'><span class='gd-tag'>以哪個類別來說</span>說某樣東西「以～這個身分」出名、被看待。</div><div class='gd-ex-line'>・<span class='gd-jp'>京都は観光地として有名です。</span>（京都以觀光地聞名）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>很單純，<b>名詞直接加として</b>：<br><span class='gd-pair'><span class='gd-jp'>先生</span> → <span class='gd-jp'>先生として</span></span><span class='gd-pair'><span class='gd-jp'>趣味</span> → <span class='gd-jp'>趣味として</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>としての＋名詞</span>後面要接名詞時，中間加「の」。</div><div class='gd-ex-line'>・<span class='gd-jp'>親としての責任がある。</span>（有身為父母的責任）</div><div class='gd-sec'><span class='gd-tag'>私としては</span>「以我的立場來說」，用來客氣地表達自己的意見，開會、工作很常聽到。</div><div class='gd-ex-line'>・<span class='gd-jp'>私としては、この案に賛成です。</span>（以我個人的立場，我贊成這個方案）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・後面接名詞時要用<b>としての</b>：說<span class='gd-jp'>医者としての仕事</span>，不能說「医者として仕事」來表示「醫生這份工作」。<br>・中文「對學生來說，讀書很重要」裡的「對～來說」不是として。要說<span class='gd-jp'>学生にとって、勉強は大切だ。</span>寫成「学生として、勉強は大切だ」會很怪。<br>・として前面原則上放名詞，不要直接接動詞或形容詞。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>として</b>＝前面的名詞是<b>主角本身的身分、角色</b>：<br><span class='gd-jp'>父として、子どもを守りたい。</span>（身為父親，我想保護孩子：說話的人「是」父親）<br><b>にとって</b>＝前面的名詞是<b>站在誰的角度來感受、判斷</b>：<br><span class='gd-jp'>父にとって、子どもは一番大切だ。</span>（對父親來說，孩子是最重要的：從父親的眼光來看）<br>再看一組：<span class='gd-jp'>京都は観光地として有名だ。</span>（京都「是」觀光地，以這個身分出名）／<span class='gd-jp'>私にとって、京都は特別な場所だ。</span>（從我的角度來看，京都很特別）</div><div class='gd-warn'>判斷小訣竅：前面的名詞如果是主角本身的身分、角色、類別（他「是」醫生、京都「是」觀光地），就用として；如果是「站在誰的角度來感受、判斷」（對父母來說、對我來說），就用にとって。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同一課的<span class='gd-jp'>〜にとって</span>可以一起複習；另外<span class='gd-jp'>〜をはじめ（として）</span>（以～為首）裡也有として的影子。</div>",
  "n3-17": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜さえ〜ば」就是中文的<b>「只要～就～」</b>。意思是：別的都不用，<b>光有這一個條件就夠了</b>。像你說「只要有網路，在哪裡都能工作」，日文就會用這個句型。</div><div class='gd-ex-line'>・<span class='gd-jp'>時間さえあれば、もっと旅行したい。</span>（只要有時間，我想多去旅行）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>先複習「ば形」（如果～的說法）怎麼變，每個字分開看：<br><span class='gd-pair'><span class='gd-jp'>書く</span> → く換成け → <span class='gd-jp'>書けば</span></span><br><span class='gd-pair'><span class='gd-jp'>ある</span> → <span class='gd-jp'>あれば</span></span><br><span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よければ</span></span></div><div class='gd-sec'><span class='gd-tag'>名詞＋さえ＋〜ば</span>最常見。さえ放在你要強調的那個東西後面，後面接動詞或形容詞的ば形。</div><div class='gd-ex-line'>・<span class='gd-jp'>天気さえよければ、明日は富士山が見える。</span>（只要天氣好，明天就看得到富士山）</div><div class='gd-sec'><span class='gd-tag'>動詞＋さえすれば</span>強調「只要做這個動作」。動詞先變成ます形，把ます拿掉，再加さえすれば。<br><span class='gd-pair'><span class='gd-jp'>飲みます</span> → 把ます拿掉 → <span class='gd-jp'>飲みさえすれば</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>この薬を飲みさえすれば、すぐ治りますよ。</span>（只要吃這個藥，很快就會好喔）</div><div class='gd-ex-line'>・<span class='gd-jp'>ボタンを押しさえすれば、あとは機械がやってくれる。</span>（只要按下按鈕，剩下的機器會幫你弄）</div><div class='gd-sec'><span class='gd-tag'>て形＋さえいれば</span>強調「只要一直保持這個狀態」。<br><span class='gd-pair'><span class='gd-jp'>待って</span> → <span class='gd-jp'>待ってさえいれば</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>ここで待ってさえいれば、大丈夫です。</span>（只要在這裡等著就沒問題）</div><div class='gd-sec'><span class='gd-tag'>形容詞＋さえあれば</span>い形容詞把い換成く，な形容詞加で，再接さえあれば。<br><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安くさえあれば</span></span><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かでさえあれば</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>静かでさえあれば、狭い部屋でもかまわない。</span>（只要安靜，房間小一點也沒關係）</div><div class='gd-h'>口語也常換成たら、なら</div><div class='gd-sec'>ば換成「たら」或「なら」，意思一樣是「只要～就～」，講話時很常聽到。</div><div class='gd-ex-line'>・<span class='gd-jp'>時間さえあったら、手伝うよ。</span>（只要有時間，我就來幫忙）</div><div class='gd-ex-line'>・<span class='gd-jp'>あなたさえいいなら、私はそれでいい。</span>（只要你覺得好，我就沒問題）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・動詞要用<b>ます形把ます拿掉</b>再接：是<span class='gd-jp'>飲みさえすれば</span>，不能說「飲むさえすれば」。<br>・名詞後面的「が」「を」會被さえ取代：是<span class='gd-jp'>お金さえあれば</span>，不是「お金がさえあれば」。<br>・它是「只要」，不是「只有～才」。<span class='gd-jp'>練習さえすれば</span>是「只要練習就行」，重點是條件很簡單，不是在限制「其他都不行」。<br>・さえ後面一定要有條件形（ば、たら、なら），才是「只要」的意思；沒有的話，さえ就變成「連～都」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一個「さえ」，後面接什麼決定意思：<br><b>さえ〜ば／たら／なら</b>＝只要～就：<span class='gd-jp'>ひらがなさえ読めれば、このゲームはできる。</span>（只要看得懂平假名，就能玩這個遊戲）<br><b>單獨的さえ</b>＝連～都：<span class='gd-jp'>ひらがなさえ読めない。</span>（連平假名都看不懂）</div><div class='gd-warn'>判斷小訣竅：看さえ後面有沒有接條件形（〜ば、〜たら、〜なら）。有就是「只要」，沒有就是「連～都」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>單獨用的〜さえ（連～都），可以跟意思相近的<span class='gd-jp'>〜すら</span>、<span class='gd-jp'>〜まで</span>一起比較著學。</div>",
  "n3-24": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜代わりに」就是<b>「拿 B 來換掉 A」</b>。可以是換東西、換人、換做法，也可以是「你幫我，我請你」這種交換，或是「薪水高，但相對地很累」這種一得一失。核心都一樣：<b>一邊換一邊，剛好扯平</b>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>換東西・換做法</span>原本該用 A、該做 A，改成 B。</div><div class='gd-ex-line'>・<span class='gd-jp'>砂糖の代わりに、はちみつを使った。</span>（用蜂蜜代替了砂糖）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は外食する代わりに、家で作ろう。</span>（今天不要出去吃，在家煮吧）</div><div class='gd-sec'><span class='gd-tag'>換人</span>本來是 A 要做，由 B 來代替。</div><div class='gd-ex-line'>・<span class='gd-jp'>社長の代わりに、部長が会議に出た。</span>（部長代替社長出席了會議）</div><div class='gd-ex-line'>・<span class='gd-jp'>私の代わりに電話に出てくれる？</span>（可以幫我接一下電話嗎？）</div><div class='gd-sec'><span class='gd-tag'>交換條件</span>我做 A，換你做 B。</div><div class='gd-ex-line'>・<span class='gd-jp'>英語を教える代わりに、日本語を教えてもらっている。</span>（我教對方英文，換他教我日文）</div><div class='gd-ex-line'>・<span class='gd-jp'>宿題を手伝ってもらった代わりに、昼ご飯をおごった。</span>（對方幫我寫作業，我請他吃午餐當回報）</div><div class='gd-sec'><span class='gd-tag'>有好有壞</span>有一個好處，相對地就有一個壞處，反過來也行。</div><div class='gd-ex-line'>・<span class='gd-jp'>給料が高い代わりに、仕事がきつい。</span>（薪水高，但相對地工作很累）</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋は駅から遠い代わりに、家賃が安い。</span>（這間房子離車站遠，但相對地房租便宜）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>名詞</b>：中間要加「の」。<span class='gd-pair'><span class='gd-jp'>砂糖</span> → <span class='gd-jp'>砂糖の代わりに</span></span><br><b>動詞・い形容詞</b>：普通形直接接，肯定、否定、過去都可以。<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行く代わりに</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かない代わりに</span></span><span class='gd-pair'><span class='gd-jp'>手伝ってもらった</span> → <span class='gd-jp'>手伝ってもらった代わりに</span></span><br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高い代わりに</span></span><span class='gd-pair'><span class='gd-jp'>効かない</span> → <span class='gd-jp'>効かない代わりに</span></span><br><b>な形容詞</b>：要留著「な」。<span class='gd-pair'><span class='gd-jp'>便利</span> → <span class='gd-jp'>便利な代わりに</span></span><br>講「不做 A，改做 B」的時候，動詞通常用辭書形，例如<span class='gd-jp'>行く代わりに</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>この薬はあまり効かない代わりに、副作用もない。</span>（這個藥不太有效，但相對地也沒有副作用）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>その代わり</span>單獨放在句子開頭，意思是「不過相對地～」，跟朋友談條件時超常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>車、貸してあげる。その代わり、ガソリン入れてきてね。</span>（車借你，不過你要幫我加油喔）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>順序跟中文相反</b>：中文說「用蜂蜜代替砂糖」，日文是<span class='gd-jp'>砂糖の代わりにはちみつ</span>，被換掉的東西放在「代わりに」前面。照中文順序寫成<span class='gd-jp'>はちみつの代わりに砂糖</span>，意思就整個反過來了。<br>・名詞後面的「の」、な形容詞後面的「な」不要漏掉。<br>・「有好有壞」的用法，前後要能互相抵銷。單純的「但是」就用「けど」：<span class='gd-jp'>日本語は難しいけど、毎日勉強している。</span>這句不能換成代わりに。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>代わりに</b>＝一好一壞，<b>剛好扯平</b>：<br><span class='gd-jp'>この店は高い代わりに、すごくおいしい。</span>（這家店貴，但相對地非常好吃）<br><b>わりに</b>＝以 A 來說，結果<b>跟預期不一樣</b>：<br><span class='gd-jp'>この店は高いわりに、あまりおいしくない。</span>（這家店那麼貴，卻不怎麼好吃）<br>另外，<b>反面</b>也能講一好一壞（<span class='gd-jp'>給料が高い反面、仕事がきつい。</span>），意思跟代わりに很接近，只是比較書面，偏向在講同一件事的兩面。</div><div class='gd-warn'>判斷小訣竅：覺得「一個換一個、扯平了」用代わりに；覺得「以～來說，怎麼會這樣」用わりに。</div>",
  "n3-33": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜っぽい」很像中文說的<b>「有點～的感覺」「很～」</b>，例如說一個人「很孩子氣」、說一件衣服「看起來很廉價」。接在某幾個動詞後面時，意思會變成<b>「動不動就～」</b>，例如「很健忘」「很容易生氣」。這是很口語的說法，聊天時非常常聽到。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>看起來像～</span>名詞＋っぽい：其實不是那樣，但給人那種感覺。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼はもう30歳なのに、子供っぽい。</span>（他都 30 歲了，還很孩子氣）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日はちょっと風邪っぽい。</span>（今天好像有點感冒）</div><div class='gd-sec'><span class='gd-tag'>偏～色、帶點～味</span>い形容詞＋っぽい：常用來講顏色或質感。</div><div class='gd-ex-line'>・<span class='gd-jp'>白っぽいシャツを買った。</span>（買了一件偏白色的襯衫）</div><div class='gd-sec'><span class='gd-tag'>動不動就～</span>動詞＋っぽい：講一個人的個性。</div><div class='gd-ex-line'>・<span class='gd-jp'>父は年を取って、怒りっぽくなった。</span>（爸爸年紀大了，變得很容易生氣）</div><div class='gd-ex-line'>・<span class='gd-jp'>私は飽きっぽいから、何をしても続かない。</span>（我很容易膩，做什麼都撐不久）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>名詞</b>：直接加っぽい。<br><span class='gd-pair'><span class='gd-jp'>子供</span> → <span class='gd-jp'>子供っぽい</span></span><br><span class='gd-pair'><span class='gd-jp'>風邪</span> → <span class='gd-jp'>風邪っぽい</span>（好像有點感冒）</span></div><div class='gd-sec'><b>い形容詞</b>：把最後的い拿掉，再加っぽい。<br><span class='gd-pair'><span class='gd-jp'>安い</span> → い拿掉 → <span class='gd-jp'>安っぽい</span></span><br><span class='gd-pair'><span class='gd-jp'>白い</span> → <span class='gd-jp'>白っぽい</span></span></div><div class='gd-sec'><b>動詞</b>：先變成ます形，把ます拿掉，再加っぽい。<br><span class='gd-pair'><span class='gd-jp'>忘れます</span> → ます拿掉 → <span class='gd-jp'>忘れっぽい</span></span><br><span class='gd-pair'><span class='gd-jp'>怒ります</span> → <span class='gd-jp'>怒りっぽい</span></span></div><div class='gd-sec'>接好之後，「〜っぽい」整個就變成一個い形容詞，變化方式跟<span class='gd-jp'>高い</span>一樣：<br><span class='gd-pair'><span class='gd-jp'>忘れっぽい</span> → <span class='gd-jp'>忘れっぽくなった</span>（變得健忘了）</span><br><span class='gd-pair'><span class='gd-jp'>子供っぽい</span> → <span class='gd-jp'>子供っぽくない</span>（不孩子氣）</span></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・動詞這一種不能隨便亂接，常用的就那幾個：<span class='gd-jp'>忘れっぽい</span>、<span class='gd-jp'>怒りっぽい</span>、<span class='gd-jp'>飽きっぽい</span>。不要自己造出<span class='gd-jp'>食べっぽい</span>這種詞。<br>・<span class='gd-jp'>安っぽい</span>不是「便宜」，是「看起來很廉價、很俗氣」，帶有負面意思：<span class='gd-jp'>このバッグは安っぽい。</span>（這個包包看起來很廉價）。想說價錢便宜，要用<span class='gd-jp'>安い</span>。<br>・常帶一點吐槽的口氣。說大人<span class='gd-jp'>子供っぽい</span>不是在稱讚他；反過來，說小孩或年輕人<span class='gd-jp'>大人っぽい</span>（很成熟），通常是稱讚。<br>・很口語，寫報告、正式文章時少用。<br>・年輕人還會把っぽい接在一整句話後面，意思是「好像～」：<span class='gd-jp'>あの店、もう閉まったっぽい。</span>（那家店好像已經關了）。這種說法很隨便，跟朋友講可以，對長輩不要用。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>らしい</b>：<span class='gd-jp'>子供らしい</span>是小孩<b>本來就該有的樣子</b>，通常用來誇真正的小孩；<span class='gd-jp'>子供っぽい</span>是<b>明明不是小孩，卻像小孩</b>，通常在說大人。<br>・<span class='gd-jp'>元気で子供らしい子だ。</span>（是個活潑、很有小孩樣的孩子）<br>・<span class='gd-jp'>彼は考え方が子供っぽい。</span>（他的想法很幼稚）</div><div class='gd-sec'><b>がち</b>：<span class='gd-jp'>忘れっぽい</span>是在講<b>這個人的個性</b>；<span class='gd-jp'>忘れがち</span>是在講<b>某件事常常發生</b>，前面可以說清楚是忘了什麼。<br>・<span class='gd-jp'>彼は忘れっぽい。</span>（他很健忘）<br>・<span class='gd-jp'>私はメールの返事を忘れがちだ。</span>（我常常忘記回信）</div><div class='gd-sec'><b>気味</b>：<span class='gd-jp'>風邪っぽい</span>和<span class='gd-jp'>風邪気味</span>都是「有點感冒」。っぽい比較隨便，跟朋友講就好；跟公司請假、對醫生說明的時候，用<span class='gd-jp'>風邪気味</span>比較穩當。</div><div class='gd-warn'>判斷小訣竅：「真的是那樣、該有的樣子」用らしい；「不是卻很像」或「個性上動不動就～」用っぽい；「某件事常常發生」用がち。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同樣在講傾向的還有<span class='gd-jp'>〜がち</span>和<span class='gd-jp'>〜気味</span>，三個放在一起學，比較容易分清楚。</div>",
  "n3-34": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜がち」就是中文的<b>「動不動就～」「很容易～」「常常會～」</b>。講的是一種<b>常常發生、而且通常不太好</b>的傾向，例如容易感冒、容易遲到、容易忘記。</div><div class='gd-ex-line'>・<span class='gd-jp'>冬は風邪を引きがちだ。</span>（冬天很容易感冒）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>動詞</span>先變成ます形，把ます拿掉，再接がち。<br><span class='gd-pair'><span class='gd-jp'>休みます</span> → <span class='gd-jp'>休みがち</span></span>（常常請假）<br><span class='gd-pair'><span class='gd-jp'>遅れます</span> → <span class='gd-jp'>遅れがち</span></span>（常常遲到、常常慢）<br><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>しがち</span></span>（常常會做）</div><div class='gd-sec'><span class='gd-tag'>名詞</span>直接接，但只有固定幾個常見的，不是每個名詞都能接。<br><span class='gd-jp'>病気がち</span>（常常生病）、<span class='gd-jp'>留守がち</span>（常常不在家）、<span class='gd-jp'>曇りがち</span>（常常陰天）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>〜がちだ</span>放在句尾，說某人或某事常常這樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しいと、食事を抜きがちだ。</span>（一忙起來就常常少吃一餐）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は最近、学校を休みがちだ。</span>（他最近常常沒去學校）</div><div class='gd-sec'><span class='gd-tag'>〜がちな＋名詞</span>後面接名詞，用法跟「静かな部屋」一樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>これは初心者にありがちなミスです。</span>（這是新手很常犯的錯）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・不能接辭書形：是<span class='gd-jp'>休みがち</span>，不是「休むがち」。<br>・它帶有「不太好」的味道，好事一般不用。想說「我常常讀書」，講<span class='gd-jp'>よく勉強する</span>就好，講成「勉強しがち」會很奇怪，好像讀書是個壞習慣。<br>・只發生一次的事不能用。がち講的是「常常、容易」，不是「這次」。<br>・名詞不能隨便接，先記<span class='gd-jp'>病気がち</span>、<span class='gd-jp'>留守がち</span>這幾個常見的就好。<br>・年輕人講的<span class='gd-jp'>ガチ</span>（「認真的、超級」）是流行語，跟這裡的「〜がち」是兩回事。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>がち</b>＝<b>常常發生</b>的傾向：<span class='gd-jp'>子どものころは病気がちだった。</span>（小時候常常生病）<br><b>気味</b>＝<b>現在有一點</b>那種感覺：<span class='gd-jp'>今日はちょっと風邪気味だ。</span>（今天有點感冒的感覺）</div><div class='gd-sec'><b>がち</b>＝某件事<b>容易發生</b>：<span class='gd-jp'>人の名前は忘れがちだ。</span>（別人的名字常常會忘記）<br><b>っぽい</b>＝整個人<b>帶有</b>那種性質：<span class='gd-jp'>祖父は最近忘れっぽい。</span>（爺爺最近變得很健忘）</div><div class='gd-warn'>判斷小訣竅：「常常會～」用がち，「現在有點～」用気味，「整個人有～的感覺」用っぽい。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>接著看<span class='gd-jp'>〜気味</span>和<span class='gd-jp'>〜っぽい</span>，這三個放在一起記最不會混。</div>",
  "n3-47": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ものだ」就是中文的<b>「本來就是這樣嘛」「本來就該～」</b>，講的是大家都認同的道理或常識，不是你個人的想法。反過來，「〜ものではない」就是長輩常講的<b>「不可以～」「哪有人這樣的」</b>，帶一點說教的味道。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>本來就這樣</span>講人或事物天生的樣子、世間的道理。常帶一點「唉，就是這樣啊」的感慨。</div><div class='gd-ex-line'>・<span class='gd-jp'>人は誰でも間違えるものだ。</span>（人本來就都會犯錯）</div><div class='gd-ex-line'>・<span class='gd-jp'>時間が経つのは早いものだ。</span>（時間過得真快啊）</div><div class='gd-sec'><span class='gd-tag'>本來就該</span>講社會常識上「應該這樣做」。</div><div class='gd-ex-line'>・<span class='gd-jp'>お年寄りには親切にするものだ。</span>（對老人家本來就該親切）</div><div class='gd-ex-line'>・<span class='gd-jp'>人の話は最後まで聞くものだ。</span>（別人說話本來就該聽到最後）</div><div class='gd-sec'><span class='gd-tag'>不應該</span>用「〜ものではない」勸人、念人。</div><div class='gd-ex-line'>・<span class='gd-jp'>食べ物を粗末にするものではない。</span>（不可以糟蹋食物）</div><div class='gd-sec'><span class='gd-tag'>懷念過去</span>用「た形＋ものだ」，講以前<b>常常</b>做的事，有「那時候啊～」的懷念感，常跟「よく」一起出現。</div><div class='gd-ex-line'>・<span class='gd-jp'>子供の頃は、よくこの川で遊んだものだ。</span>（小時候常在這條河邊玩呢）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞辭書形：<span class='gd-pair'><span class='gd-jp'>間違える</span> → <span class='gd-jp'>間違えるものだ</span></span><br>動詞ない形：<span class='gd-pair'><span class='gd-jp'>変わらない</span> → <span class='gd-jp'>変わらないものだ</span></span><br>い形容詞直接接：<span class='gd-pair'><span class='gd-jp'>早い</span> → <span class='gd-jp'>早いものだ</span></span><br>な形容詞要加な：<span class='gd-pair'><span class='gd-jp'>元気</span> → <span class='gd-jp'>元気なものだ</span></span><br>懷念過去用た形：<span class='gd-pair'><span class='gd-jp'>遊んだ</span> → <span class='gd-jp'>遊んだものだ</span></span><br>不應該用辭書形：<span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言うものではない</span></span></div><div class='gd-sec'>口語常縮成<b>もんだ</b>、<b>もんじゃない</b>：<span class='gd-jp'>そんなこと言うもんじゃないよ。</span>（不可以講那種話喔）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・ものだ講的是<b>大家公認的道理</b>，不能拿來講自己某一次的打算。「明天我要去學校」就說<span class='gd-jp'>明日学校へ行きます</span>，不能加ものだ。<br>・「ないものだ」跟「ものではない」意思不同：<span class='gd-jp'>人は簡単には変わらないものだ</span>是「人本來就不容易改變」（講本性）；<span class='gd-jp'>人の悪口を言うものではない</span>是「不應該說別人壞話」（勸人）。<br>・懷念過去的用法講的是<b>以前常常做</b>的事，只做過一次的不能用：昨天吃了拉麵就說<span class='gd-jp'>昨日ラーメンを食べた</span>，不會加ものだ。<br>・ものではない是在念人，對主管、老師講會很失禮，通常是長輩對晚輩、父母對小孩說。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「應該」，看話是誰的立場：<br><b>ものだ</b>＝<b>社會常識</b>本來就該這樣，講的是一般道理：<span class='gd-jp'>約束は守るものだ。</span>（約定本來就該遵守）<br><b>べきだ</b>＝<b>說話的人自己判斷</b>應該這樣，語氣比較直接、比較強：<span class='gd-jp'>あなたはこの約束を守るべきだ。</span>（你應該遵守這個約定）<br><b>ことだ</b>＝針對眼前這個人<b>給建議</b>「最好～」：<span class='gd-jp'>約束を守りたいなら、メモしておくことだ。</span>（想守約的話，最好先記下來）</div><div class='gd-warn'>判斷小訣竅：講「人本來就該怎樣」用ものだ，講「我覺得你應該」用べきだ，給對方建議「你最好～」用ことだ。另外<span class='gd-jp'>ものだから</span>是講理由（因為～嘛），跟這裡的ものだ不是同一個東西。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同樣用來講道理、勸人的還有「〜べきだ・〜べきではない」和「〜ことだ」，可以接著看，三個放在一起比，會更清楚什麼時候用哪個。</div>",
  "n3-1": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜において」就是日文的<b>「於～」</b>。中文平常說「在台北開會」，寫成公文就變成「會議<b>於</b>台北舉行」。日文也一樣：平常講「<span class='gd-jp'>台北で</span>」，正式的文章、新聞、致詞就換成「<span class='gd-jp'>台北において</span>」。意思都是「在～」，只是<b>正式很多</b>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>在哪裡</span>活動、典禮在什麼地方舉行，新聞最常見。</div><div class='gd-ex-line'>・<span class='gd-jp'>開会式は台北において行われた。</span>（開幕典禮於台北舉行。）</div><div class='gd-sec'><span class='gd-tag'>在什麼場合</span>會議、面試、比賽這種「場面」。</div><div class='gd-ex-line'>・<span class='gd-jp'>面接において、一番大切なのは第一印象だ。</span>（面試時最重要的是第一印象。）</div><div class='gd-sec'><span class='gd-tag'>在哪個領域</span>某個分野、某個方面。</div><div class='gd-ex-line'>・<span class='gd-jp'>医療の分野において、AIの活用が進んでいる。</span>（在醫療領域，AI 的應用越來越普遍。）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面一律接<b>名詞</b>，重點是<b>後面接什麼</b>：<br><b>後面接動作、句子</b> → 用<b>において</b><br><span class='gd-pair'><span class='gd-jp'>京都で開催された</span> → <span class='gd-jp'>京都において開催された</span></span>（於京都舉辦）<br><b>後面直接接名詞</b> → 用<b>における</b>，作用就像中文的「～的」、日文的「<span class='gd-jp'>での</span>」<br><span class='gd-pair'><span class='gd-jp'>日本での問題</span> → <span class='gd-jp'>日本における問題</span></span>（在日本的問題）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本における外国人労働者の数は年々増えている。</span>（在日本的外國勞工人數逐年增加。）</div><div class='gd-sec'>後面也很常加「は」「も」來強調：</div><div class='gd-ex-line'>・<span class='gd-jp'>この点においては、私も同じ意見です。</span>（在這一點上，我也有同樣的看法。）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>日常小事不要用</b>：<span class='gd-jp'>コンビニにおいてパンを買った</span>聽起來像在寫公文，很怪。講自己的生活用<span class='gd-jp'>コンビニでパンを買った</span>就好。<br>・<b>後面接名詞時，別忘了換成における</b>：不能說「日本において経済」，要說<span class='gd-jp'>日本における経済</span>。<br>・它只取代「<b>在哪裡、在什麼場合</b>」的で。表示工具的で不能換：<span class='gd-jp'>はしで食べる</span>（用筷子吃）不能說成「はしにおいて」。<br>・「哪裡<b>有</b>什麼」用的是に，不是で，所以也不能換成において：要說<span class='gd-jp'>公園に子どもがいる</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>で</b>＝口語、日常都能用：<span class='gd-jp'>会議で決まりました。</span>（在會議上決定了。）<br><b>において</b>＝同一件事的正式說法：<span class='gd-jp'>会議において決定されました。</span>（於會議中決定。）</div><div class='gd-sec'><b>について</b>長得很像，但意思完全不同，是「<b>關於～</b>」，講的是內容、主題。看這句，兩個一起出現：</div><div class='gd-ex-line'>・<span class='gd-jp'>会議において、環境問題について話し合った。</span>（在會議上，討論了關於環境問題的事。）</div><div class='gd-sec'>「会議」是<b>在哪裡</b>討論，「環境問題」是<b>討論什麼</b>。</div><div class='gd-warn'>判斷小訣竅：中文能說「於～」「在～」就是において；中文是「關於～」就是について。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>「〜て」接動作、「〜る」接名詞，這個模式很多文法都有，像<span class='gd-jp'>〜に関して／〜に関する</span>、<span class='gd-jp'>〜によって／〜による</span>，學會這個，後面那些就簡單了。</div>",
  "n3-4": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「によって」很像中文的<b>「靠～」「看～」</b>。前面放一個名詞，表示事情是靠它做到的、是它造成的，或是要看它而定。所以中文會依情況翻成「透過」「因為」「因～而異」「由」。新聞、說明文、正式場合特別常見。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面一律直接接<b>名詞</b>，不用加「の」。後面接什麼，決定你用哪一個：<br>後面是動作、整個句子 → <b>によって</b>：<span class='gd-jp'>台風によって電車が止まった。</span>（因為颱風，電車停駛了）<br>後面直接接名詞 → <b>による</b>：<span class='gd-jp'>台風による停電</span>（颱風造成的停電）<br>書面上也常看到「<span class='gd-jp'>により</span>」，意思跟によって一樣，只是更正式。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>因～而異</span>「要看～而定、每個～都不一樣」。後面幾乎都接<span class='gd-jp'>違う</span>、<span class='gd-jp'>異なる</span>、<span class='gd-jp'>変わる</span>這類「不一樣」的詞。</div><div class='gd-ex-line'>・<span class='gd-jp'>地域によって食文化が異なる。</span>（飲食文化因地區而異）</div><div class='gd-ex-line'>・<span class='gd-jp'>人によって考え方が違う。</span>（每個人的想法都不一樣）</div><div class='gd-sec'><span class='gd-tag'>原因</span>「因為～、～造成的」，口氣客觀，像新聞在報導。</div><div class='gd-ex-line'>・<span class='gd-jp'>台風による停電が続いている。</span>（颱風造成的停電仍在持續）</div><div class='gd-ex-line'>・<span class='gd-jp'>事故によって電車が遅れています。</span>（因為事故，電車誤點了）</div><div class='gd-sec'><span class='gd-tag'>手段・方法</span>「透過～」，比較正式的說法。</div><div class='gd-ex-line'>・<span class='gd-jp'>この問題は話し合いによって解決した。</span>（這個問題透過協商解決了）</div><div class='gd-sec'><span class='gd-tag'>被動句的「由誰」</span>說作品、發明、建築是誰做出來的。</div><div class='gd-ex-line'>・<span class='gd-jp'>この小説は有名な作家によって書かれた。</span>（這本小說是由知名作家寫的）</div><div class='gd-ex-line'>・<span class='gd-jp'>電話はベルによって発明された。</span>（電話是貝爾發明的）</div><div class='gd-sec'><span class='gd-tag'>によっては</span>多一個「は」，意思變成<b>「有些～會…」</b>，只挑其中一部分來講。</div><div class='gd-ex-line'>・<span class='gd-jp'>店によって値段が違う。</span>（價錢每家店都不一樣）</div><div class='gd-ex-line'>・<span class='gd-jp'>店によっては、カードが使えない。</span>（有些店不能刷卡）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>被動句不是都用によって</b>。日常的「被誰罵、被誰說」用「に」：<span class='gd-jp'>母に叱られた。</span>（被媽媽罵了），講成「母によって叱られた」很怪。によって是留給「誰做出某個東西」這種場合。<br>・<b>日常的手段用「で」就好</b>：<span class='gd-jp'>バスで行く</span>，不說「バスによって行く」。によって的「透過」偏正式，用在方法、制度這類比較大的事。<br>・<b>による後面一定要接名詞</b>。後面是句子就換回によって，不要寫成「台風による電車が止まった」。<br>・「因～而異」跟「有些～會…」差一個「は」，意思就不一樣，要看清楚有沒有那個「は」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「因為颱風」，口氣差很多：<br><b>によって</b>＝客觀講原因，不帶情緒：<span class='gd-jp'>台風によって電車が止まった。</span>（因為颱風，電車停駛了）<br><b>せいで</b>＝怪它害的，帶抱怨：<span class='gd-jp'>台風のせいで旅行に行けなかった。</span>（都是颱風害我沒辦法去旅行）<br><b>おかげで</b>＝多虧它，帶慶幸或感謝：<span class='gd-jp'>台風のおかげで学校が休みになった。</span>（託颱風的福，學校放假了）<br>接名詞時，せいで、おかげで前面要加「の」（<span class='gd-jp'>雨のせいで</span>），によって直接接名詞，不用加「の」（<span class='gd-jp'>雨によって</span>）。</div><div class='gd-warn'>判斷小訣竅：像新聞那樣平平地講原因用によって，想抱怨用せいで，覺得慶幸用おかげで。</div>",
  "n3-6": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜おかげで」就是中文的<b>「多虧了～」「託～的福」「還好有～」</b>。前面放帶來好結果的原因，後面講那個好結果，語氣裡帶著一點感謝。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>謝謝某個人</span>因為有某人幫忙，事情才順利。</div><div class='gd-ex-line'>・<span class='gd-jp'>先生のおかげで、合格できました。</span>（多虧老師，我考上了）</div><div class='gd-ex-line'>・<span class='gd-jp'>友達が手伝ってくれたおかげで、早く終わった。</span>（多虧朋友幫忙，很快就做完了）</div><div class='gd-sec'><span class='gd-tag'>好的原因</span>不一定是人，天氣、環境、東西都可以，只要它帶來好結果。</div><div class='gd-ex-line'>・<span class='gd-jp'>この薬を飲んだおかげで、熱が下がった。</span>（多虧吃了這個藥，燒退了）</div><div class='gd-ex-line'>・<span class='gd-jp'>駅が近いおかげで、通勤が楽です。</span>（還好離車站近，通勤很輕鬆）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>名詞</b>：中間加「の」。<br><span class='gd-pair'><span class='gd-jp'>先輩</span> → <span class='gd-jp'>先輩のおかげで</span></span></div><div class='gd-sec'><b>動詞</b>：直接接普通形（就是字典上的形、た形這些不加ます的樣子）。好結果通常已經發生了，所以最常用た形。<br><span class='gd-pair'><span class='gd-jp'>頑張った</span> → <span class='gd-jp'>頑張ったおかげで</span></span></div><div class='gd-sec'><b>い形容詞</b>：直接接。<br><span class='gd-pair'><span class='gd-jp'>近い</span> → <span class='gd-jp'>近いおかげで</span></span><br><span class='gd-pair'><span class='gd-jp'>よかった</span> → <span class='gd-jp'>よかったおかげで</span></span></div><div class='gd-sec'><b>な形容詞</b>：現在式要加「な」，過去式用「だった」。<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなおかげで</span></span><br><span class='gd-pair'><span class='gd-jp'>元気だった</span> → <span class='gd-jp'>元気だったおかげで</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>おかげさまで</span>別人問候你的時候，客氣回一句「託您的福」，就算對方其實沒幫上什麼忙也可以這樣講。</div><div class='gd-ex-line'>・<span class='gd-jp'>お元気ですか。</span>——<span class='gd-jp'>おかげさまで、元気です。</span>（你好嗎？——託您的福，我很好）</div><div class='gd-sec'><span class='gd-tag'>〜のおかげです</span>放在句尾，把功勞歸給某人。</div><div class='gd-ex-line'>・<span class='gd-jp'>合格できたのは、先生のおかげです。</span>（我能考上，都是多虧老師）</div><div class='gd-sec'><span class='gd-tag'>反話</span>跟中文「託你的福喔」一樣，也可以故意拿來酸人，結果其實是壞事。</div><div class='gd-ex-line'>・<span class='gd-jp'>君のおかげで、全部やり直しだよ。</span>（託你的福，全部要重做啦）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞後面一定要有「の」：是<span class='gd-jp'>先生のおかげで</span>，不能說先生おかげで。<br>・な形容詞現在式不能接「だ」：是<span class='gd-jp'>静かなおかげで</span>，不是静かだおかげで。<br>・後面要接<b>已經發生、或確定會發生的結果</b>，不能接「～吧」「請～」這種邀約、拜託的句子。<br>・中文講「因為」很隨便，但不是每個「因為」都能換成おかげで。只是單純說明原因（例如因為下雨所以比賽取消）要用<span class='gd-jp'>から</span>、<span class='gd-jp'>ので</span>；用おかげで會聽起來像你很高興比賽取消。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>おかげで</b>＝多虧～，結果是<b>好事</b>，帶感謝：<br><span class='gd-jp'>雨が降ったおかげで、涼しくなった。</span>（多虧下了雨，變涼快了）<br><b>せいで</b>＝都是～害的，結果是<b>壞事</b>，帶抱怨、怪罪：<br><span class='gd-jp'>雨が降ったせいで、試合が中止になった。</span>（都是下雨害的，比賽取消了）<br>兩個接法完全一樣，差別只在你對結果是感謝還是抱怨。</div><div class='gd-warn'>判斷小訣竅：想說「多虧、還好有」用おかげで；想說「都是～害的」用せいで；只是單純講原因、沒有好壞情緒，用から・ので。</div>",
  "n3-7": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜せいで」就是中文的<b>「都怪～」「都是～害的」</b>。事情的結果不好，你要說是什麼害的，就用它。<br>後面換成「〜せいか」，語氣就退一步，變成<b>「可能是因為～吧」</b>，代表你自己也不太確定原因。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>せいで</span>結果不好，而且你很確定是誰、是什麼造成的，帶一點怪罪、抱怨的感覺。</div><div class='gd-ex-line'>・<span class='gd-jp'>雨のせいで、試合が中止になった。</span>（都是下雨害的，比賽取消了）</div><div class='gd-ex-line'>・<span class='gd-jp'>私が寝坊したせいで、みんなを待たせてしまった。</span>（都怪我睡過頭，害大家等我）</div><div class='gd-sec'><span class='gd-tag'>せいか</span>只是在猜原因，不一定真的是這樣。中文常翻成「可能是～的關係吧」。</div><div class='gd-ex-line'>・<span class='gd-jp'>年のせいか、最近疲れやすい。</span>（可能是年紀的關係吧，最近很容易累）</div><div class='gd-ex-line'>・<span class='gd-jp'>寝不足のせいか、頭がぼんやりする。</span>（可能是睡不夠，頭昏昏的）</div><div class='gd-sec'><span class='gd-tag'>放句尾</span>把原因放到最後講，變成「～是～害的」。</div><div class='gd-ex-line'>・<span class='gd-jp'>失敗したのは準備不足のせいだ。</span>（會失敗是準備不夠害的）</div><div class='gd-ex-line'>・<span class='gd-jp'>私のせいです。すみません。</span>（是我的錯，對不起）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>「せい」本身是名詞，所以前面接法跟接名詞一樣。<br><b>名詞</b>：加「の」<span class='gd-pair'><span class='gd-jp'>風邪</span> → <span class='gd-jp'>風邪のせいで</span></span><br><b>な形容詞</b>：加「な」<span class='gd-pair'><span class='gd-jp'>下手</span> → <span class='gd-jp'>下手なせいで</span></span><br><b>い形容詞</b>：直接接<span class='gd-pair'><span class='gd-jp'>狭い</span> → <span class='gd-jp'>狭いせいで</span></span><br><b>動詞</b>：用普通形（就是不加ます的說法），過去式也可以<span class='gd-pair'><span class='gd-jp'>食べすぎた</span> → <span class='gd-jp'>食べすぎたせいで</span></span><br>せいか的接法完全一樣，把で換成か就好。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞一定要加「の」：是<span class='gd-jp'>雪のせいで</span>，不是「雪せいで」。<br>・な形容詞要用「な」，不能接「だ」：是<span class='gd-jp'>暇なせいか</span>，不是「暇だせいか」。<br>・<b>好的結果不要用せいで</b>。「多虧老師，我考上了」要用おかげで，用せいで會變成你在怪老師害你考上，很奇怪。<br>・當面說<span class='gd-jp'>あなたのせいで</span>是在直接指責對方，口氣很重，要小心用。<br>・很常聽到的<span class='gd-jp'>気のせいだよ</span>是固定說法，意思是「是你想太多了啦」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「因為下雨」，結果不一樣，用的字就不一樣：<br><b>せいで</b>＝結果不好，怪它：<span class='gd-jp'>雨のせいで、花火大会が中止になった。</span>（都怪下雨，煙火大會取消了）<br><b>おかげで</b>＝結果是好的，感謝它：<span class='gd-jp'>雨のおかげで、涼しくなった。</span>（多虧下了雨，變涼快了）<br>反過來，<span class='gd-jp'>おかげで</span>用在壞結果上，就是在講反話酸人：<span class='gd-jp'>君のおかげで、また怒られたよ。</span>（託你的福，我又被罵了）</div><div class='gd-warn'>判斷小訣竅：想說「都怪～」用せいで，想說「多虧～」用おかげで；原因不確定、只是猜的，就用せいか。</div>",
  "n3-9": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「とともに」寫成漢字就是「と共に」，意思跟中文的<b>「與～一同」「隨著～」</b>很像。它是比較<b>正式、書面</b>的說法，新聞、演講、作文、致詞裡很常見。感覺就像中文說「與家人一同」「隨著時代變遷」，平常聊天比較少這樣講。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>一起</span>跟某人一起做某件事，等於「と一緒に」的正式版。</div><div class='gd-ex-line'>・<span class='gd-jp'>家族とともに新居で新年を迎えた。</span>（和家人一起在新家迎接新年）</div><div class='gd-ex-line'>・<span class='gd-jp'>チームの仲間とともに優勝を喜んだ。</span>（和隊友們一起為奪冠開心）</div><div class='gd-sec'><span class='gd-tag'>隨著</span>前面的事一變化，後面的事也跟著變化。這是 N3 最常考的用法。</div><div class='gd-ex-line'>・<span class='gd-jp'>年齢とともに体力が落ちてきた。</span>（隨著年紀增長，體力變差了）</div><div class='gd-ex-line'>・<span class='gd-jp'>人口が減るとともに、町の店も少なくなった。</span>（隨著人口減少，鎮上的店也變少了）</div><div class='gd-sec'><span class='gd-tag'>同時</span>A 發生的那一刻，B 也跟著發生。</div><div class='gd-ex-line'>・<span class='gd-jp'>ベルが鳴るとともに、子どもたちは教室を飛び出した。</span>（鐘聲一響，孩子們就衝出教室）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>名詞＋とともに</b><br><span class='gd-pair'><span class='gd-jp'>家族</span> → <span class='gd-jp'>家族とともに</span></span><span class='gd-pair'><span class='gd-jp'>技術の発展</span> → <span class='gd-jp'>技術の発展とともに</span></span><br><b>動詞辭書形（字典上查得到的原形）＋とともに</b><br><span class='gd-pair'><span class='gd-jp'>増える</span> → <span class='gd-jp'>増えるとともに</span></span><span class='gd-pair'><span class='gd-jp'>鳴る</span> → <span class='gd-jp'>鳴るとともに</span></span><br>進階一點：<b>名詞＋であるとともに</b>＝「是～，同時也是～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は医者であるとともに、作家でもある。</span>（他是醫生，同時也是作家）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・它很正式。跟朋友說<span class='gd-jp'>友達とともにラーメンを食べた</span>，聽起來像在念公文，口語就用<span class='gd-jp'>友達と一緒に</span>。<br>・「隨著」用法的後半句要寫<b>「變成怎樣」</b>，不能只寫一個固定的習慣：×<span class='gd-jp'>年をとるとともに、毎日運動している</span>　○<span class='gd-jp'>年をとるとともに、運動する時間が増えた</span>。<br>・動詞一律用辭書形，就算是過去的事也一樣，過去式放在句尾：×<span class='gd-jp'>増えたとともに</span>　○<span class='gd-jp'>人口が増えるとともに、町がにぎやかになった</span>。<br>・前面是「と」不是「に」：<span class='gd-jp'>家族とともに</span>，不是家族にともに。<br>・書上常寫成漢字<span class='gd-jp'>と共に</span>，兩種寫法都對。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>と一緒に</b>＝日常口語的「一起」：<span class='gd-jp'>家族と一緒に旅行した。</span>（我跟家人一起去旅行）<br><b>とともに</b>＝正式版的「一起」：<span class='gd-jp'>家族とともに旅行した。</span>（意思一樣，但像作文或新聞的寫法）<br>另外，<span class='gd-jp'>と一緒に</span>沒有「隨著」的意思，不能說×<span class='gd-jp'>年齢と一緒に体力が落ちた</span>。</div><div class='gd-sec'><b>につれて</b>＝只有「隨著」的意思：<span class='gd-jp'>年をとるにつれて、体力が落ちてきた。</span>（隨著年紀增長，體力變差了）<br><b>とともに</b>＝也能講「隨著」，語氣比較正式：<span class='gd-jp'>年をとるとともに、体力が落ちてきた。</span><br>差別在<span class='gd-jp'>につれて</span>不能拿來講「一起」或「同時」，<span class='gd-jp'>とともに</span>三種都能講。</div><div class='gd-warn'>判斷小訣竅：平常講「一起」就用と一緒に；講「隨著」，につれて和とともに都可以，越正式越偏向とともに；要講「一起」或「同時」又要正式，就選とともに。</div>",
  "n3-10": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'><span class='gd-jp'>ところ</span>本來是「地方」，在這裡是<b>「時間上的那個點」</b>。一件事分成三個階段：<b>還沒開始、做到一半、剛做完</b>。<span class='gd-jp'>ところだ</span>就是告訴對方你現在站在哪一格，很像中文的「正要～」「正在～」「剛～完」。</div><div class='gd-h'>怎麼接：前面的形決定是哪一格</div><div class='gd-sec'><span class='gd-tag'>正要做</span>辭書形（字典上的原形）＋ところだ。事情<b>還沒開始</b>，馬上就要做。</div><div class='gd-ex-line'>・<span class='gd-jp'>今から出かけるところです。</span>（我正要出門）</div><div class='gd-ex-line'>・<span class='gd-jp'>A：もうご飯食べた？　B：ううん、これから食べるところ。</span>（A：吃飯了嗎？B：還沒，正要吃）</div><div class='gd-sec'><span class='gd-tag'>正在做</span>て形＋いる＋ところだ。事情<b>做到一半</b>，還沒結束。</div><div class='gd-ex-line'>・<span class='gd-jp'>今シャワーを浴びているところだから、あとでかけ直すね。</span>（我正在洗澡，等一下回撥給你）</div><div class='gd-ex-line'>・<span class='gd-jp'>今調べているところなので、少々お待ちください。</span>（現在正在查，請稍等）</div><div class='gd-sec'><span class='gd-tag'>剛做完</span>た形（過去式）＋ところだ。事情<b>就在剛剛</b>結束。</div><div class='gd-ex-line'>・<span class='gd-jp'>たった今、家に帰ってきたところです。</span>（我才剛到家）</div><div class='gd-ex-line'>・<span class='gd-jp'>会議がちょうど終わったところです。</span>（會議剛好結束）</div><div class='gd-sec'>同一個動詞放在一起看最清楚：<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べるところ</span></span>（正要吃）<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べているところ</span></span>（正在吃）<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べたところ</span></span>（剛吃完）<br>對長輩、客人就說<span class='gd-jp'>ところです</span>；跟朋友可以直接說<span class='gd-jp'>ところ</span>，<span class='gd-jp'>ているところ</span>口語常縮成<span class='gd-jp'>てるところ</span>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'>最常出現在別人問「你現在在幹嘛」、講電話、回訊息的時候，用來交代自己<b>此刻的狀況</b>。常跟<span class='gd-jp'>これから</span>、<span class='gd-jp'>今から</span>（正要）、<span class='gd-jp'>今</span>（正在）、<span class='gd-jp'>たった今</span>、<span class='gd-jp'>ちょうど</span>（剛）一起出現，看到這些詞就知道是哪一格。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・辭書形＋ところ是<b>還沒開始</b>。<span class='gd-jp'>今食べるところ</span>是「正要吃」，不是「正在吃」，正在吃要說<span class='gd-jp'>食べているところ</span>。<br>・ているところ只能用在<b>真的正在動的動作</b>。像<span class='gd-jp'>住んでいる</span>、<span class='gd-jp'>知っている</span>這種表示狀態的，不能說「住んでいるところだ」。<br>・たところ是<b>真的就在剛剛</b>。不能說「先月日本に来たところだ」，上個月不算剛剛，這時要用たばかり（看下面）。<br>・<span class='gd-jp'>ところだ</span>放在句尾才是這個意思。「〜たところ、…」中間加逗號繼續講下去，是另一個文法（～了一下，結果…），不要搞混。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>たところだ</b>和<b>たばかりだ</b>都翻成「剛～」，差在「剛」有多剛。<br><b>たところだ</b>：時間點就在剛剛，幾分鐘前那種。<br><span class='gd-jp'>今、駅に着いたところです。</span>（我剛到車站）<br><b>たばかりだ</b>：說話的人<b>覺得</b>沒過多久，幾天、幾個月都可以。<br><span class='gd-jp'>先月日本に来たばかりです。</span>（我上個月才剛來日本）<br>另外，たばかり很常帶出「才剛～，所以／卻…」的感覺：<span class='gd-jp'>買ったばかりなのに、もう壊れた。</span>（才剛買就壞了）</div><div class='gd-warn'>判斷小訣竅：能換成「就在剛剛這一刻」的用たところ；想說「沒多久以前，感覺還很新」的用たばかり。拿不準時，時間超過今天就用たばかり。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>辭書形＋<span class='gd-jp'>ところだった</span>＝差一點就～（還好沒發生）：<span class='gd-jp'>もう少しで電車に乗り遅れるところだった。</span>（差一點就沒趕上電車）</div>",
  "n3-11": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜たばかり」就是中文的<b>「才剛～」「剛～沒多久」</b>。重點是你<b>覺得</b>時間還很短，所以常帶著「還沒習慣」「怎麼又～」這種心情。</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に来たばかりで、まだ慣れない。</span>（剛來日本，還不習慣）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>一定接動詞的<b>た形</b>（過去式，像<span class='gd-jp'>食べた</span>、<span class='gd-jp'>行った</span>這種），再加ばかり。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べた</span> → <span class='gd-jp'>食べたばかり</span></span><br><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買った</span> → <span class='gd-jp'>買ったばかり</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来た</span> → <span class='gd-jp'>来たばかり</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>放句尾</span>〜たばかりだ／〜たばかりです</div><div class='gd-ex-line'>・<span class='gd-jp'>先月結婚したばかりです。</span>（我上個月才剛結婚）</div><div class='gd-sec'><span class='gd-tag'>後面還有話</span>〜たばかりで，說明「因為才剛～，所以…」</div><div class='gd-ex-line'>・<span class='gd-jp'>起きたばかりで、頭がぼんやりしている。</span>（才剛起床，頭還昏昏的）</div><div class='gd-sec'><span class='gd-tag'>修飾名詞</span>〜たばかりの＋名詞</div><div class='gd-ex-line'>・<span class='gd-jp'>これは買ったばかりの靴です。</span>（這是剛買的鞋子）</div><div class='gd-sec'><span class='gd-tag'>抱怨、意外</span>〜たばかりなのに，「才剛～，怎麼就…」</div><div class='gd-ex-line'>・<span class='gd-jp'>さっき食べたばかりなのに、もうお腹がすいた。</span>（才剛吃過，肚子又餓了）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面一定是た形。寫成<span class='gd-jp'>来るばかり</span>、<span class='gd-jp'>食べるばかり</span>就變成別的意思了（下面會講）。<br>・修飾名詞要用<b>の</b>：是<span class='gd-jp'>買ったばかりの靴</span>，不是買ったばかり靴。<br>・「剛」的長短看你的感覺：<span class='gd-jp'>去年入社したばかりです</span>（我去年才進公司）這樣講一年前也完全沒問題。<br>・朋友之間常講成<span class='gd-jp'>たばっか</span>：<span class='gd-jp'>今起きたばっか。</span>（我才剛起床）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>〜たところだ</b>（n3-10 ところだ）也翻成「剛～」，但它講的是<b>動作剛結束的那個時間點</b>，真的就是幾秒、幾分鐘前。<br>・<span class='gd-jp'>今、駅に着いたところです。</span>（我現在剛到車站）<br>・<span class='gd-jp'>今、駅に着いたばかりです。</span>（我才剛到車站）<br>這種「剛剛」的情境兩個都能用。但時間一拉長就只能用たばかり：<br>・<span class='gd-jp'>先月引っ越したばかりです。</span>（我上個月才剛搬家）○<br>・<span class='gd-jp'>先月引っ越したところです。</span> ×</div><div class='gd-sec'><b>ばかり前面換了形，意思就變了</b>：<br><b>辭書形＋ばかり</b>，多半表示「一直往同一個方向變化（越來越～）」，例如<span class='gd-jp'>物価は上がるばかりだ。</span>（物價一直漲）；也可以表示「只是一直～、光～」，例如<span class='gd-jp'>彼女は泣くばかりで何も言わない。</span>（她只是一直哭，什麼都不說）<br><b>て形＋ばかりいる</b>＝老是只做某件事：<span class='gd-jp'>弟はゲームをしてばかりいる。</span>（弟弟老是在打電動）</div><div class='gd-warn'>判斷小訣竅：先看ばかり前面——た形是「才剛～」，辭書形是「一直～（越來越～／光是～）」，て形是「老是～」。如果前面講了「上個月、去年」這種比較久的時間，要說「剛～」就用たばかり，不用たところ。</div>",
  "n3-12": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜最中に」就是中文的<b>「正在～的時候，突然……」</b>。事情做到一半、正忙的時候，被別的事打斷或碰上意外。像「正在簡報，結果停電」「正在面試，手機響了」，後面通常接<b>突然發生、讓人措手不及</b>的事。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>做到一半被打斷</span>最典型的用法。</div><div class='gd-ex-line'>・<span class='gd-jp'>会議の最中に、電話が鳴った。</span>（正在開會的時候，電話響了）</div><div class='gd-ex-line'>・<span class='gd-jp'>シャワーを浴びている最中に、お湯が出なくなった。</span>（正在洗澡的時候，熱水突然沒了）</div><div class='gd-sec'><span class='gd-tag'>最中だ</span>放句尾，表示「現在正忙著～」，接電話、婉拒別人很常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>今、食事の最中なので、あとでかけ直します。</span>（我現在正在吃飯，等一下再打給你）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：先變成「〜ている」，再加最中に。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べている</span> → <span class='gd-jp'>食べている最中に</span></span><br><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話している最中に</span></span></div><div class='gd-sec'><b>名詞</b>：名詞＋の＋最中に。名詞要是<b>一段正在進行的活動</b>，像<span class='gd-jp'>会議</span>、<span class='gd-jp'>試合</span>、<span class='gd-jp'>授業</span>、<span class='gd-jp'>面接</span>。<br><span class='gd-pair'><span class='gd-jp'>試合</span> → <span class='gd-jp'>試合の最中に</span></span></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・動詞一定要用「ている」形：說<span class='gd-jp'>食べている最中に</span>，不是食べる最中に。<br>・名詞後面的「の」不能省：<span class='gd-jp'>授業の最中に</span>，不是授業最中に。<br>・「最中」在這裡念<b>さいちゅう</b>。<br>・要接「一段時間內正在進行」的動作。像<span class='gd-jp'>着く</span>、<span class='gd-jp'>始まる</span>這種一下子就結束的動作，不能用最中に；<span class='gd-jp'>いる</span>、<span class='gd-jp'>ある</span>這種只是在描述狀態的動詞也不行。<br>・後面通常是<b>突然發生、打斷的事</b>。如果只是想說「在那段期間我做了某事」，用最中に會怪怪的。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>最中に</b>＝正在做的時候，<b>突然被打斷、碰上意外</b>：<span class='gd-jp'>寝ている最中に、地震が起きた。</span>（正在睡覺的時候，發生了地震）<br><b>間に</b>＝趁那段期間，<b>做了某件事</b>（可以是刻意安排的）：<span class='gd-jp'>子どもが寝ている間に、部屋を片付けた。</span>（趁小孩在睡覺的時候，把房間整理好了）<br>第二句如果換成「寝ている最中に、部屋を片付けた」，聽起來就不對勁，因為整理房間不是「突然冒出來的事」。</div><div class='gd-sec'><b>〜中</b>（例如<span class='gd-jp'>会議中</span>）只是很平淡地說「正在～」，常寫在門牌或告示上；<b>〜の最中</b>語氣更強，強調「正在進行到一半、最忙的時候」。</div><div class='gd-warn'>判斷小訣竅：想講「正在～的時候，突然……」用最中に；想講「趁～的時候，去做了……」用間に。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>想再加強語氣，可以說「真っ最中」：<span class='gd-jp'>今、テストの真っ最中だ。</span>（現在正在考試，而且考到一半）</div>",
  "n3-14": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「～間に」就是中文的<b>「在～的時候（發生了某件事）」「趁～的時候（做了某件事）」</b>。把一段時間想成一條線，「間に」就是在這條線上<b>插一根旗子</b>：這段時間裡的某一刻，有件事發生了，或你把某件事做完了。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>沒注意時發生</span>你不在場、沒注意的時候，事情就發生了。</div><div class='gd-ex-line'>・<span class='gd-jp'>留守の間に宅配便が届いた。</span>（我不在家的時候，包裹送到了）</div><div class='gd-ex-line'>・<span class='gd-jp'>知らない間に、もう夜の12時になっていた。</span>（不知不覺已經半夜 12 點了）</div><div class='gd-sec'><span class='gd-tag'>趁這段時間做</span>利用某段時間，把一件事做完。</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもが寝ている間に、部屋を掃除した。</span>（趁小孩在睡覺，把房間打掃好了）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本にいる間に、富士山に登りたい。</span>（我想在日本的這段期間爬一次富士山）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面要放的是<b>一段時間</b>或<b>一個持續的狀態</b>。<br><b>動詞</b>：「睡、吃、看」這種動作，通常用ている形（～ている），讓它變成「正在～」的一段時間。<span class='gd-jp'>いる</span>、<span class='gd-jp'>ある</span>本身就是一種狀態，直接用原本的樣子就好。也可以接ない形（～ない）。<br><span class='gd-pair'><span class='gd-jp'>寝る</span> → <span class='gd-jp'>寝ている間に</span></span><span class='gd-pair'><span class='gd-jp'>日本にいる</span> → <span class='gd-jp'>日本にいる間に</span></span><span class='gd-pair'><span class='gd-jp'>知らない</span> → <span class='gd-jp'>知らない間に</span></span><br><b>名詞</b>：中間加「の」。<br><span class='gd-pair'><span class='gd-jp'>留守</span> → <span class='gd-jp'>留守の間に</span></span><span class='gd-pair'><span class='gd-jp'>夏休み</span> → <span class='gd-jp'>夏休みの間に</span></span></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞後面一定要加「の」：要說<span class='gd-jp'>留守の間に</span>，不能說「留守間に」。<br>・這裡的「間」念<b>あいだ</b>。<span class='gd-jp'>一週間</span>的「かん」是另一種用法，不要念錯。<br>・中文都說「～的時候」，可是日文要看後面那件事：如果是<b>一直持續</b>，就不加に。所以「間に」後面不要接「ずっと～」，<span class='gd-jp'>寝ている間に、ずっと雨が降っていた</span>是錯的，要拿掉に。<br>・就算整句在講過去的事，前面通常還是用「ている間に」，過去的「た」放在句尾就好：<span class='gd-jp'>寝ている間に地震があった。</span>（睡覺的時候發生了地震）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣都在講暑假：</div><div class='gd-ex-line'>・<span class='gd-jp'>夏休みの間、ずっとアルバイトをしていた。</span>（暑假整段時間都在打工）</div><div class='gd-ex-line'>・<span class='gd-jp'>夏休みの間に、運転免許を取った。</span>（暑假期間的某個時候，考到了駕照）</div><div class='gd-ex-line'>・<span class='gd-jp'>夏休みのうちに、宿題を終わらせたい。</span>（想趁暑假還沒結束，把作業寫完）</div><div class='gd-sec'><b>間</b>（沒有に）＝這整段時間<b>一直</b>在做，後面常跟著「ずっと」。<br><b>間に</b>＝這段時間裡的<b>某一刻</b>，發生了或做完了一件事。<br><b>うちに</b>＝多了<b>「趁還來得及」</b>的感覺，暗示這段時間一過就不方便了。<br>另外還有<b>最中に</b>＝事情正做到一半，<b>偏偏</b>被打斷：<span class='gd-jp'>シャワーを浴びている最中に、電話が鳴った。</span>（正在洗澡，偏偏電話響了）</div><div class='gd-warn'>判斷小訣竅：後面是「一直～」，用<b>間</b>；後面是「發生了／做完了一件事」，用<b>間に</b>；想說「趁現在趕快」，用<b>うちに</b>。</div>",
  "n3-15": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ついでに」就是中文的<b>「順便」</b>。A 是你本來就要做的事，既然都要做了，就趁這個機會把 B 也一起做掉。像是「下樓倒垃圾，順便拿信」：倒垃圾是 A，拿信是 B。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>三種接法，前面放的都是那件「本來就要做的事」：<br>名詞＋の＋ついでに　<span class='gd-pair'><span class='gd-jp'>買い物</span> → <span class='gd-jp'>買い物のついでに</span></span><br>動詞辭書形＋ついでに　<span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くついでに</span></span><br>動詞た形＋ついでに　<span class='gd-pair'><span class='gd-jp'>来た</span> → <span class='gd-jp'>来たついでに</span></span><br>名詞要是「一件事」，例如<span class='gd-jp'>買い物</span>、<span class='gd-jp'>散歩</span>、<span class='gd-jp'>出張</span>、<span class='gd-jp'>旅行</span>這類詞。</div><div class='gd-h'>辭書形還是た形？</div><div class='gd-sec'><span class='gd-tag'>辭書形</span>A 還沒做、正要出門去做的時候，順便做 B。很常拿來拜託別人。</div><div class='gd-ex-line'>・<span class='gd-jp'>コンビニに行くついでに、お茶を買ってきてくれる？</span>（你去便利商店的時候，可以順便幫我買個茶嗎？）</div><div class='gd-ex-line'>・<span class='gd-jp'>出かけるついでに、ゴミを出してくるね。</span>（我出門順便把垃圾拿出去喔）</div><div class='gd-sec'><span class='gd-tag'>た形</span>人已經到了那裡、A 已經發生了，就趁這個機會做 B。</div><div class='gd-ex-line'>・<span class='gd-jp'>京都に来たついでに、奈良にも行ってみた。</span>（都來京都了，就順便去了一趟奈良）</div><div class='gd-ex-line'>・<span class='gd-jp'>本屋に寄ったついでに、ノートも買った。</span>（去書店的時候，順便買了筆記本）</div><div class='gd-sec'><span class='gd-tag'>名詞の</span>最簡潔，日常很好用。</div><div class='gd-ex-line'>・<span class='gd-jp'>買い物のついでに、銀行に寄った。</span>（出門買東西，順便去了一趟銀行）</div><div class='gd-ex-line'>・<span class='gd-jp'>出張のついでに、大阪の友達に会った。</span>（出差時順便跟大阪的朋友見了面）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-jp'>ついでに</span>也可以單獨放在句子前面，直接當「順便」用。前面的 A 從上下文就知道，不用再講一次。</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、ついでに牛乳も買ってきて。</span>（啊，順便也買個牛奶回來）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>主要的事放前面，順便的事放後面</b>。前後對調，意思就變成另一件事才是主要目的。<br>・前面要放「一件事」，不能直接放地點：不能說「駅のついでに」，要說<span class='gd-jp'>駅に行くついでに</span>。<br>・A 跟 B 都要是人<b>自己決定去做</b>的事。下雨這種自然發生的事不能放進來，不能說「雨が降ったついでに」。<br>・中文「順便說一下」是在補充資訊，日文比較常用<span class='gd-jp'>ちなみに</span>，不太用ついでに。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>中文「順便」跟「一邊…一邊…」有時候會混在一起，日文分得很清楚。同樣是去車站的情境：<br><b>ついでに</b>＝趁做 A 的機會，<b>多做一件事</b>，兩件事不一定同時：<span class='gd-jp'>駅に行くついでに、手紙を出した。</span>（去車站時順便寄了信）<br><b>ながら</b>＝兩件事<b>同時進行</b>：<span class='gd-jp'>音楽を聞きながら、駅まで歩いた。</span>（一邊聽音樂一邊走到車站）</div><div class='gd-warn'>判斷小訣竅：「順便多做一件事」用ついでに；「一邊…一邊…」同時在做，用ながら。</div>",
  "n3-16": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜てからでないと」就是中文的<b>「要先～才能～」「沒先～的話，就不能～」</b>。像「先買票才能進場」「先洗手才能吃」，重點在<b>順序不能顛倒，前面那件事一定要先做完</b>。</div><div class='gd-h'>拆開來看就懂</div><div class='gd-sec'>它其實是三塊拼起來的：<br><span class='gd-jp'>て</span>形（做了～）＋<span class='gd-jp'>から</span>（之後）＋<span class='gd-jp'>でないと</span>（如果不是的話）<br>合起來就是「如果不是在做完～之後」，也就是「沒先做～」的意思。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞先變成て形，後面直接加「からでないと」。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べてからでないと</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>して</span> → <span class='gd-jp'>してからでないと</span></span><br><span class='gd-pair'><span class='gd-jp'>聞く</span> → <span class='gd-jp'>聞いて</span> → <span class='gd-jp'>聞いてからでないと</span></span></div><div class='gd-h'>後面要接什麼</div><div class='gd-sec'>後半句幾乎都是<b>「不行、做不到、沒辦法」</b>這類否定的話：<span class='gd-jp'>できない</span>、<span class='gd-jp'>わからない</span>、<span class='gd-jp'>だめだ</span>、<span class='gd-jp'>無理だ</span>、動詞的可能形否定等等。</div><div class='gd-ex-line'>・<span class='gd-jp'>手を洗ってからでないと、おやつはだめだよ。</span>（沒先洗手不能吃點心喔）</div><div class='gd-ex-line'>・<span class='gd-jp'>実際に見てからでないと、買うかどうか決められない。</span>（沒親眼看過，我沒辦法決定要不要買）</div><div class='gd-ex-line'>・<span class='gd-jp'>お金を払ってからでないと、商品はお渡しできません。</span>（要先付款才能把商品交給您）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>からでないと</span>一般說法，口頭書面都可以。<br><span class='gd-tag'>からでなければ</span>比較正式、比較硬，公告、說明文件常看到。<br><span class='gd-tag'>からじゃないと</span>朋友之間的口語版。</div><div class='gd-ex-line'>・<span class='gd-jp'>宿題やってからじゃないと、ゲームはできないよ。</span>（要先寫完功課才能打電動喔）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・後半句<b>不能接「可以」的肯定句</b>。<span class='gd-jp'>予約してからでないと、入れます</span>是錯的；想講「先預約再進去」，用一般的<span class='gd-jp'>予約してから入ります</span>就好。<br>・中間的「<b>で</b>」不能漏掉，寫成「てからないと」是錯的。<br>・て形要變對：<span class='gd-jp'>行く</span>是<span class='gd-jp'>行って</span>，<span class='gd-jp'>書く</span>是<span class='gd-jp'>書いて</span>，這裡錯了整句就錯。<br>・語氣上帶有「規定」「條件」的味道，對客人講時後面要配敬語，例如<span class='gd-jp'>できません</span>、<span class='gd-jp'>お渡しできません</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一個情境：簽約前要看合約。<br><b>てから</b>＝單純講<b>順序</b>，先A再B：<span class='gd-jp'>内容を確認してから、サインします。</span>（我先確認內容再簽）<br><b>てからでないと</b>＝強調<b>一定要先A，不然B做不到</b>：<span class='gd-jp'>内容を確認してからでないと、サインできません。</span>（沒先確認內容，我不能簽）<br><b>た上で</b>＝做完A、<b>以此為基礎</b>再做B，比較正式慎重：<span class='gd-jp'>内容を確認した上で、サインします。</span>（確認過內容之後再簽）</div><div class='gd-warn'>判斷小訣竅：後面是「可以做、會去做」用<b>てから</b>或<b>た上で</b>；後面是「不行、做不到」，而且想強調「得先～」，就用<b>てからでないと</b>。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>可以接著看「<span class='gd-jp'>〜上で</span>」（n3-23），正式場合講「先～再～」很常用：<span class='gd-jp'>よく考えた上で、決めてください。</span>（請好好考慮過之後再決定）</div>",
  "n3-18": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜としたら」就是中文的<b>「假如真的～的話」</b>。先把一個還不確定、甚至不太可能的情況<b>假設成真</b>，再接著講「那會怎樣」「那我想怎樣」。很像朋友聊天時說「假設啦，假設你中了樂透……」。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>純假設</span>講不太可能、還沒發生的事，常跟<span class='gd-jp'>もし</span>、<span class='gd-jp'>仮に</span>（假如）一起出現。</div><div class='gd-ex-line'>・<span class='gd-jp'>もし宝くじが当たったとしたら、何に使う？</span>（假如中了樂透，你要拿來做什麼？）</div><div class='gd-ex-line'>・<span class='gd-jp'>一週間休めるとしたら、どこに行きたい？</span>（如果能休一個禮拜，你想去哪裡？）</div><div class='gd-sec'><span class='gd-tag'>拿聽到的事來推論</span>把別人說的話、聽來的消息先當成真的，再推出結論。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の話が本当だとすれば、大変なことだ。</span>（如果他說的是真的，那事情就嚴重了）</div><div class='gd-sec'><span class='gd-tag'>放在句子開頭</span>前面加<span class='gd-jp'>だ</span>，變成<span class='gd-jp'>だとしたら</span>、<span class='gd-jp'>だとすると</span>，意思是「那這樣的話」，接著對方剛剛講的話往下說。</div><div class='gd-ex-line'>・<span class='gd-jp'>A：明日は台風が来るらしいよ。</span>（聽說明天颱風會來）</div><div class='gd-ex-line'>・<span class='gd-jp'>B：だとすると、旅行は無理だね。</span>（那這樣的話，旅行應該去不成了）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞、い形容詞直接接：<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くとしたら</span></span><span class='gd-pair'><span class='gd-jp'>当たった</span> → <span class='gd-jp'>当たったとしたら</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いとしたら</span></span><br>名詞、な形容詞要先加<b>だ</b>：<br><span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だとしたら</span></span><span class='gd-pair'><span class='gd-jp'>暇</span> → <span class='gd-jp'>暇だとしたら</span></span><br>三種說法<span class='gd-jp'>としたら</span>、<span class='gd-jp'>とすれば</span>、<span class='gd-jp'>とすると</span>接法都一樣。</div><div class='gd-h'>三個說法怎麼選</div><div class='gd-sec'><b>としたら</b>：最口語、最好用。後面要接「想～」「要～」這種自己的願望、打算，選它最自然。<br><b>とすれば・とすると</b>：比較有「推論」的味道，後面常接<span class='gd-jp'>〜だろう</span>、<span class='gd-jp'>〜はずだ</span>、<span class='gd-jp'>〜必要がある</span>這種判斷。</div><div class='gd-ex-line'>・<span class='gd-jp'>明日雨だとすれば、運動会は延期だろう。</span>（假如明天下雨，運動會大概會延期）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞、な形容詞別忘了<b>だ</b>：要說<span class='gd-jp'>雨だとしたら</span>，不是「雨としたら」。<br>・名詞後面<b>不加だ</b>、直接接<span class='gd-jp'>としたら</span>，會變成另一個意思「站在～的立場」：<span class='gd-jp'>親としたら、心配だろう。</span>（站在父母的立場，應該會擔心吧）<br>・<b>一定會發生的事不能用</b>：「到家之後打給我」是<span class='gd-jp'>家に着いたら電話して</span>，說成「着いたとしたら」聽起來像在懷疑你到不了家。<br>・<span class='gd-jp'>とすると</span>後面不太接「想～」「請～」，這種時候換成<span class='gd-jp'>としたら</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>たら</b>＝一般的「～的話／～之後」，事情可能真的會發生：<br><span class='gd-jp'>宝くじが当たったら、車を買う。</span>（中了就買車）<br><b>としたら</b>＝特別強調「這只是假設」：<br><span class='gd-jp'>宝くじが当たったとしたら、車を買う。</span>（假設真的中了，我會買車）<br>確定會發生的事只能用たら：<span class='gd-jp'>家に着いたら連絡するね。</span>（到家我再跟你聯絡）</div><div class='gd-warn'>判斷小訣竅：中文能說成「假如真的～」「萬一真的～」，用としたら；只是「～之後就～」，用たら。</div>",
  "n3-19": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜たところ」就是中文的<b>「～了之後，結果發現…」</b>。你先去做一件事（打電話問、查資料、試用看看），然後才知道一個結果。像是：「打去店裡問了一下，結果已經賣完了。」<br>這裡的<span class='gd-jp'>ところ</span>跟「地方」沒有關係，把它當成「結果」的開關就好。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞的た形＋ところ。<br><span class='gd-pair'><span class='gd-jp'>聞く</span> → <span class='gd-jp'>聞いた</span> → <span class='gd-jp'>聞いたところ</span></span><br><span class='gd-pair'><span class='gd-jp'>調べる</span> → <span class='gd-jp'>調べた</span> → <span class='gd-jp'>調べたところ</span></span><br><span class='gd-pair'><span class='gd-jp'>電話する</span> → <span class='gd-jp'>電話した</span> → <span class='gd-jp'>電話したところ</span></span><br>句子分成兩半：前半是<b>你做的事</b>，後半是<b>做了之後才知道或出現的結果</b>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>問了才知道</span>去問人、打電話確認之後得到的消息。</div><div class='gd-ex-line'>・<span class='gd-jp'>店に電話したところ、もう売り切れだった。</span>（打電話去店裡，結果已經賣完了）</div><div class='gd-ex-line'>・<span class='gd-jp'>先生に相談したところ、いいアドバイスをもらえた。</span>（找老師商量之後，得到了很好的建議）</div><div class='gd-sec'><span class='gd-tag'>試了才知道</span>查查看、試試看之後的結果。</div><div class='gd-ex-line'>・<span class='gd-jp'>詳しく調べたところ、原因がわかった。</span>（仔細查了之後，找到了原因）</div><div class='gd-ex-line'>・<span class='gd-jp'>この薬を飲んだところ、熱が下がった。</span>（吃了這個藥之後，燒就退了）</div><div class='gd-sec'>語氣偏正式，報告、商務 email、新聞很常見。跟朋友聊天多半直接用「〜たら」。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・後半句是<b>已經發生、已經知道的事</b>，所以多半用過去式。不能接自己接下來要做的事、請求或命令：<br>×<span class='gd-jp'>調べたところ、先生に聞きます。</span><br>○<span class='gd-jp'>調べてから、先生に聞きます。</span>（查完之後再去問老師）<br>・前半句通常是<b>你自己主動去做的事</b>。下雨這種自然發生的事不太能放前面：<br>×<span class='gd-jp'>雨が降ったところ、涼しくなった。</span><br>○<span class='gd-jp'>雨が降ったら、涼しくなった。</span>（下了雨之後就變涼了）<br>・它的重點是「做了之後才發現的結果」，句型本身不是在說「因為～所以～」。有時前後剛好有因果（吃藥→退燒），有時沒有（打電話問店家，並不是賣完的原因，只是讓你得知的契機），兩種都可以用。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>たところ</b>＝做了之後，<b>後面還有一句結果</b>：<br><span class='gd-jp'>駅員に聞いたところ、電車は遅れているそうだ。</span>（問了站務員，結果說電車誤點了）<br><b>たところだ</b>＝<b>剛剛才</b>做完，句子到這裡就結束：<br><span class='gd-jp'>今、駅員に聞いたところだ。</span>（我剛剛才問過站務員）<br><b>たら</b>＝也能表示「～了之後發現」，但比較口語，用的範圍也比較廣：<br><span class='gd-jp'>駅員に聞いたら、電車が遅れてるって。</span>（問了站務員，他說電車誤點了）</div><div class='gd-warn'>判斷小訣竅：「ところ」後面接逗號、還有一句結果，就是たところ；句子停在「ところだ」，就是「剛做完」。正式場合講結果用たところ，跟朋友聊天用たら。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>可以回頭對照<span class='gd-jp'>〜ところだ</span>的三種時間點（正要做、正在做、剛做完），就不會跟たところ混在一起。</div>",
  "n3-22": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜以上（は）」就是中文的<b>「既然～，就～」</b>。前面先講一件已經確定的事，後面接「那我就一定要～」「那就應該～」。有點像台灣人說的「都已經答應人家了，那就要做到啊」，帶著一種<b>既然如此、就要負起責任</b>的覺悟感。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：直接接在普通形（也就是不加ます的說法）後面。<br><span class='gd-pair'><span class='gd-jp'>約束した</span> → <span class='gd-jp'>約束した以上</span></span>（既然約好了）<br><span class='gd-pair'><span class='gd-jp'>やる</span> → <span class='gd-jp'>やる以上</span></span>（既然要做）<br><span class='gd-pair'><span class='gd-jp'>来ない</span> → <span class='gd-jp'>来ない以上</span></span>（既然不來）</div><div class='gd-sec'><b>名詞、な形容詞</b>：中間要加「である」，不能直接接。<br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生である以上</span></span>（既然是學生）<br><span class='gd-pair'><span class='gd-jp'>プロ</span> → <span class='gd-jp'>プロである以上</span></span>（既然是專業的）</div><div class='gd-sec'>後面的「は」可加可不加，加了語氣更重一點，意思一樣。</div><div class='gd-h'>後面要接什麼</div><div class='gd-sec'>重點在後半句：一定是說話的人的<b>決心、義務、判斷</b>，不是單純描述發生了什麼事。</div><div class='gd-sec'><span class='gd-tag'>我要～（決心）</span></div><div class='gd-ex-line'>・<span class='gd-jp'>引き受けた以上は、最後までやります。</span>（既然接下了這件事，我就會做到最後）</div><div class='gd-ex-line'>・<span class='gd-jp'>やる以上は、一番を目指したい。</span>（既然要做，就想拿第一）</div><div class='gd-sec'><span class='gd-tag'>應該～、必須～（義務）</span></div><div class='gd-ex-line'>・<span class='gd-jp'>日本に住んでいる以上、日本の法律を守らなければならない。</span>（既然住在日本，就必須遵守日本的法律）</div><div class='gd-ex-line'>・<span class='gd-jp'>プロである以上、言い訳はできない。</span>（既然是專業的，就不能找藉口）</div><div class='gd-sec'><span class='gd-tag'>那就只能～（判斷）</span></div><div class='gd-ex-line'>・<span class='gd-jp'>本人が来ない以上、この話は進められない。</span>（既然本人不來，這件事就沒辦法談下去）</div><div class='gd-sec'>前面用<span class='gd-jp'>た</span>形，是「已經發生了，所以～」；用辭書形，是「既然要這樣做、既然是這個身分，所以～」。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞要加である：是<span class='gd-jp'>学生である以上</span>，不是「学生な以上」。直接寫<span class='gd-jp'>学生以上</span>會被看成另一個意思（學生以上的程度）。<br>・後半句不能只是一般事實。不能說「雨が降った以上、試合が中止になった」，因為「比賽取消了」只是發生的事，不是決心或判斷。<br>・<span class='gd-jp'>以上</span>還有別的意思別混在一起：<span class='gd-jp'>三人以上</span>是「三個人以上」，報告結束時說的<span class='gd-jp'>以上です</span>是「以上，報告完畢」。<br>・語氣比較正經、帶覺悟，常用在責任、約定、身分這類話題，拿來講小事會有點誇張。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>最容易混的是單純講原因的<b>から</b>。<br><span class='gd-jp'>約束したから、行きます。</span>（因為約好了，所以我會去）：只是說明理由。<br><span class='gd-jp'>約束した以上、行かなければならない。</span>（既然約好了，就非去不可）：強調「這件事已經成立，我有責任」。<br>另外，<span class='gd-jp'>雨が降ったから、試合が中止になった。</span>（因為下雨，比賽取消了）可以用から，但換成以上就不行，因為後面只是發生的事。</div><div class='gd-warn'>判斷小訣竅：後面是「我一定要、應該、只能」這種覺悟或判斷，用以上；只是在講原因跟結果，用から。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>常跟<span class='gd-jp'>べきだ</span>一起出現：<span class='gd-jp'>約束した以上、守るべきだ。</span>（既然約好了，就應該遵守）。之後還會學到意思幾乎一樣的<span class='gd-jp'>からには</span>和<span class='gd-jp'>上は</span>，其中<span class='gd-jp'>上は</span>更書面、更正式。</div>",
  "n3-23": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜上で」有兩個意思，<b>看前面接什麼形就知道是哪一個</b>：<br>接<b>た形</b>：「先好好做完～，<b>再</b>…」，像中文說「商量過<b>之後</b>再決定」。<br>接<b>辭書形</b>（字典上查到的原本形）：「在做～<b>這件事上</b>」，像中文說「在日本生活，敬語很重要」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>①先做好再…</span>た形＋上で／名詞の＋上で<br><span class='gd-pair'><span class='gd-jp'>相談する</span> → <span class='gd-jp'>相談した上で</span></span><span class='gd-pair'><span class='gd-jp'>確認</span> → <span class='gd-jp'>確認の上で</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>よく考えた上で、返事します。</span>（我好好考慮之後再回覆你）</div><div class='gd-ex-line'>・<span class='gd-jp'>家族とよく相談した上で、転職を決めた。</span>（跟家人好好商量過後，才決定換工作）</div><div class='gd-sec'>重點是前面那件事是<b>必要的準備</b>，做好了才進行後面。後面常接<span class='gd-jp'>決める</span>、<span class='gd-jp'>申し込む</span>、<span class='gd-jp'>返事する</span>這種「做決定、辦手續」的動作。</div><div class='gd-sec'><span class='gd-tag'>②在～這件事上</span>辭書形＋上で／名詞の＋上で<br><span class='gd-pair'><span class='gd-jp'>生活する</span> → <span class='gd-jp'>生活する上で</span></span><span class='gd-pair'><span class='gd-jp'>仕事</span> → <span class='gd-jp'>仕事の上で</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>日本で生活する上で、敬語は大切だ。</span>（在日本生活，敬語很重要）</div><div class='gd-ex-line'>・<span class='gd-jp'>この本は日本語を勉強する上で役に立つ。</span>（學日文的時候，這本書很有用）</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事の上での付き合いは大切です。</span>（工作上的往來很重要）</div><div class='gd-sec'>後面多半是一個評價：<span class='gd-jp'>大切だ</span>、<span class='gd-jp'>必要だ</span>、<span class='gd-jp'>欠かせない</span>、<span class='gd-jp'>役に立つ</span>、<span class='gd-jp'>注意が必要だ</span>。後面接名詞時，把で換成<b>での</b>，像上面的<span class='gd-jp'>仕事の上での付き合い</span>。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'>公告、表格、店家說明很常看到「<b>ご＋名詞＋の上</b>」，で常常省略，是很客氣的書面說法。</div><div class='gd-ex-line'>・<span class='gd-jp'>内容をご確認の上、サインしてください。</span>（請確認內容後再簽名）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・形接錯，意思就跑掉：<span class='gd-jp'>相談した上で</span>是「商量完之後」，<span class='gd-jp'>相談する上で</span>是「在商量這件事上」（例：<span class='gd-jp'>相談する上で大切なこと</span>＝商量時重要的事）。要說「之後再…」一定用た形。<br>・①不是隨便的「然後」。<span class='gd-jp'>ご飯を食べた上で、テレビを見た</span>很怪，日常的先後順序用<span class='gd-jp'>〜てから</span>就好。<br>・這裡的「上」念<b>うえ</b>。另外有一種直接接在名詞後面的<span class='gd-jp'>仕事上</span>，念しごと<b>じょう</b>，意思跟<span class='gd-jp'>仕事の上で</span>差不多，但寫法、念法不一樣，不要混在一起。<br>・不要寫成「上に」。<span class='gd-jp'>〜上に</span>是「不但～而且～」，是另一個文法。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>た上で vs てから</b><br><span class='gd-jp'>家族と相談してから決めます。</span>（先跟家人商量，再決定：單純講順序）<br><span class='gd-jp'>家族と相談した上で決めます。</span>（跟家人好好商量過，以這個為基礎再決定：強調有認真做過這一步）<br>てから什麼場合都能用；た上で比較正式，用在重要的決定。</div><div class='gd-sec'><b>る上で vs ために</b><br><span class='gd-jp'>日本で働くために、日本語を勉強しています。</span>（為了在日本工作，我在學日文）<br><span class='gd-jp'>日本で働く上で、日本語は欠かせません。</span>（在日本工作，日文是不可少的）<br>中文都可能翻成「要～」，但ために後面接<b>你為了目的去做的事</b>，る上で後面接<b>這件事需要什麼、什麼很重要</b>。</div><div class='gd-warn'>判斷小訣竅：想說「好好做完～再…」用<b>た上で</b>；想說「做～時，什麼很重要」用<b>る上で</b>；後面是「我去做某事」就用<b>ために</b>。</div>",
  "n3-25": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'><span class='gd-jp'>に限り</span>、<span class='gd-jp'>に限って</span>的「限」就是限定，意思是<b>把範圍縮到只剩這一個</b>。它有兩種很不一樣的用法。一種是公告上的<b>「僅限～」</b>，另一種是生活裡抱怨的<b>「偏偏～」</b>，就像中文說「每次趕時間，偏偏就遇到紅燈」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面放<b>名詞</b>。<br>名詞直接接：<span class='gd-pair'><span class='gd-jp'>本日</span> → <span class='gd-jp'>本日に限り</span></span><br>想說「～的時候」「～的日子」，就先用動詞把「とき」「日」講完整，再接上去：<br><span class='gd-pair'><span class='gd-jp'>急いでいる</span> → 加上とき → <span class='gd-jp'>急いでいるときに限って</span></span><br><span class='gd-pair'><span class='gd-jp'>傘を持っていない</span> → 加上日 → <span class='gd-jp'>傘を持っていない日に限って</span></span></div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>僅限～</span>店家活動、票券、規定上常常看到，語氣比較正式，大多寫成<span class='gd-jp'>に限り</span>。意思是「只有這個範圍才可以」。</div><div class='gd-ex-line'>・<span class='gd-jp'>先着100名様に限り、特典をプレゼントします。</span>（僅限前 100 名客人贈送特別禮物）</div><div class='gd-ex-line'>・<span class='gd-jp'>このチケットは当日に限り有効です。</span>（這張票僅限當天有效）</div><div class='gd-sec'><span class='gd-tag'>偏偏～</span>平常都沒事，偏偏在最不希望的時候出狀況。這個用法用<span class='gd-jp'>に限って</span>。後面通常接倒楣、不如意的事，語氣帶一點抱怨。</div><div class='gd-ex-line'>・<span class='gd-jp'>傘を持っていない日に限って、急に雨が降る。</span>（偏偏沒帶傘的日子就突然下雨）</div><div class='gd-ex-line'>・<span class='gd-jp'>急いでいるときに限って、信号に引っかかる。</span>（偏偏趕時間的時候就被紅燈擋下來）</div><div class='gd-ex-line'>・<span class='gd-jp'>休みの日に限って、朝早く目が覚める。</span>（偏偏放假的日子就很早醒來）</div><div class='gd-sec'><span class='gd-tag'>唯獨他不會</span>前面放一個你很信任的人，後面接「不可能～」。意思是「別人也許會，但唯獨他絕對不會」。</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの子に限って、うそをつくはずがない。</span>（我家孩子絕對不可能說謊）</div><div class='gd-ex-line'>・<span class='gd-jp'>あの真面目な田中さんに限って、約束を忘れるなんてありえない。</span>（那麼認真的田中先生，不可能忘記約定）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・「僅限」這個意思很正式，是公告、廣告的口氣。跟朋友聊天說「只有今天」，講<span class='gd-jp'>今日だけ</span>就好，講<span class='gd-jp'>今日に限り</span>會像在念告示。<br>・「偏偏」的<span class='gd-jp'>に限って</span>，後面幾乎都是不好的事。不要拿來說好事。<br>・「唯獨他不會」的用法，後面一定要接否定，像<span class='gd-jp'>はずがない</span>、<span class='gd-jp'>ありえない</span>。只寫<span class='gd-jp'>うちの子に限って</span>就停下來，日本人也聽得懂你後面要說「不可能」。<br>・不要跟<b><span class='gd-jp'>に限る</span></b>搞混。它的意思是「～最好、就是要～」：<span class='gd-jp'>暑い日は冷たいビールに限る。</span>（熱天就是要喝冰啤酒）。字只差一點，意思完全不一樣。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講「今天」，用法不同，意思就差很多：<br><span class='gd-jp'>本日に限り、入場無料です。</span>（僅限今天免費入場）→ 公告，「僅限」<br><span class='gd-jp'>今日に限って、財布を忘れた。</span>（偏偏今天忘了帶錢包）→ 抱怨，「偏偏」<br><span class='gd-jp'>あの人に限って、そんなことはしない。</span>（唯獨他不會做那種事）→ 信任，「唯獨他不會」</div><div class='gd-warn'>判斷小訣竅：在公告、規定上看到，就是「僅限」。說自己倒楣的事，就是「偏偏」。前面是人、後面是「不可能」，就是「唯獨他不會」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>把它改成否定的<span class='gd-jp'>に限らず</span>，意思變成「不只～」：<span class='gd-jp'>この店は週末に限らず、いつも混んでいる。</span>（這家店不只週末，平常也都很多人）</div>",
  "n3-26": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「きり」有兩張臉。<br>①接在名詞後面＝<b>「就只有～」</b>，像中文的「就我們兩個」「就這麼一次」。<br>②接在動詞た形後面＝<b>「～之後，就再也沒～了」</b>，像中文說的「一去不回」「從那之後就沒消息」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>只有～</span>名詞＋きり。這裡的名詞多半是人數、次數，或是「これ」。<br><span class='gd-pair'><span class='gd-jp'>二人</span> → <span class='gd-jp'>二人きり</span></span>（就兩個人）<span class='gd-pair'><span class='gd-jp'>一度</span> → <span class='gd-jp'>一度きり</span></span>（就一次）<span class='gd-pair'><span class='gd-jp'>これ</span> → <span class='gd-jp'>これきり</span></span>（就只有這些）<br>注意：<span class='gd-jp'>あれきり</span>、<span class='gd-jp'>それきり</span>通常不是「只有那個」，而是「從那次之後就沒了」，屬於下面第二種用法。</div><div class='gd-ex-line'>・<span class='gd-jp'>二人きりで話したい。</span>（想兩個人單獨聊聊）</div><div class='gd-ex-line'>・<span class='gd-jp'>チャンスは一度きりだ。</span>（機會只有一次）</div><div class='gd-ex-line'>・<span class='gd-jp'>お金はこれきりしかない。</span>（錢就只剩這些了）</div><div class='gd-sec'><span class='gd-tag'>之後就再也沒～</span>動詞た形＋きり。先把動詞變成た形，再加きり。<br><span class='gd-pair'><span class='gd-jp'>出かける</span> → <span class='gd-jp'>出かけた</span> → <span class='gd-jp'>出かけたきり</span></span><br>後面接的是「本來應該會發生的事，一直沒發生」，所以常常是否定句；也可以直接用「〜たきりだ」放在句尾。</div><div class='gd-ex-line'>・<span class='gd-jp'>父は朝出かけたきり、まだ帰ってこない。</span>（爸爸早上出門之後，到現在都還沒回來）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女とは卒業式で会ったきりだ。</span>（我跟她在畢業典禮見過之後，就再也沒見過了）</div><div class='gd-ex-line'>・<span class='gd-jp'>あれきり、彼から連絡はない。</span>（從那次之後，他就沒再聯絡了）</div><div class='gd-sec'>生活中很常見的一個詞：<span class='gd-jp'>寝たきり</span>＝躺下之後就沒再起來＝<b>臥床不起</b>。<br><span class='gd-jp'>祖母は去年から寝たきりだ。</span>（奶奶從去年開始就臥床不起）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・口語常常念成<b>っきり</b>：<span class='gd-jp'>二人っきり</span>、<span class='gd-jp'>これっきり</span>，意思一樣，聽到不要以為是別的字。<br>・「たきり」後面不能接「開始做新的事」。想說「進公司之後每天都很忙」要用てから：<span class='gd-jp'>会社に入ってから、毎日忙しい。</span>，不能說「会社に入ったきり、毎日忙しい」。<br>・きり本身就有「從那之後」的意思，不要再跟<span class='gd-jp'>以来</span>疊在一起用。<br>・「○○きり」用在一個時間點時，那是<b>最後一次</b>，不代表之前沒發生過。<span class='gd-jp'>卒業式で会ったきり</span>是「畢業典禮是最後一次見面」，不是「只見過那一次」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>きり vs だけ</b>：兩個都能翻「只有」，但きり只接人數、次數、これ這類詞，而且常帶「沒有別人、就這樣了」的感覺。<br><span class='gd-jp'>一人だけ来た。</span>／<span class='gd-jp'>一人きりだ。</span>（只來了一個人／就我一個人）兩種說法都可以。<br><span class='gd-jp'>りんごだけ食べた。</span>（只吃了蘋果）這種一般東西不能換成きり。</div><div class='gd-sec'><b>たきり vs っぱなし</b>：兩個都有「之後就沒～」的感覺，重點不一樣。<br><span class='gd-jp'>テレビをつけっぱなしで寝てしまった。</span>（開著電視沒關就睡著了）：該做的收尾（關掉）沒做，狀態一直放著。<br><span class='gd-jp'>兄は東京へ行ったきり、帰ってこない。</span>（哥哥去了東京之後就沒回來）：那件事之後，後續的事就再也沒發生。</div><div class='gd-warn'>判斷小訣竅：「就只有這些人、這幾次」→名詞＋きり；「那次之後就再也沒～」→た形＋きり；「開著、放著沒收」→っぱなし。</div>",
  "n3-27": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜をはじめ」就是中文的<b>「以～為首」「～等等，都…」</b>。先點名一個最有代表性、最有名的，後面再帶出同一群的其他成員。就像介紹台灣小吃時，你會先說「珍珠奶茶」，再接「牛肉麵、雞排這些」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面只能放<b>名詞</b>。<span class='gd-jp'>をはじめ</span>和<span class='gd-jp'>をはじめとして</span>意思一樣，加了として比較正式、完整。<br><span class='gd-pair'><span class='gd-jp'>東京</span> → <span class='gd-jp'>東京をはじめ</span></span><span class='gd-pair'><span class='gd-jp'>社長</span> → <span class='gd-jp'>社長をはじめとして</span></span><br>如果後面要直接接名詞，就用<b>をはじめとする＋名詞</b>：<span class='gd-jp'>寿司をはじめとする日本料理</span>（以壽司為代表的日本料理）。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>舉代表</span>先講最有名的，再說還有很多。</div><div class='gd-ex-line'>・<span class='gd-jp'>日本には、東京をはじめ、大きな都市がたくさんある。</span>（日本有東京等許多大城市）</div><div class='gd-sec'><span class='gd-tag'>地位最高的帶頭</span>從最上面的人講到全部的人，公司、典禮很常聽到。</div><div class='gd-ex-line'>・<span class='gd-jp'>社長をはじめ、社員全員が会議に出た。</span>（從社長到全體員工都出席了會議）</div><div class='gd-sec'><span class='gd-tag'>をはじめとする</span>當成修飾，後面直接接名詞。</div><div class='gd-ex-line'>・<span class='gd-jp'>寿司をはじめとする日本料理は、海外でも人気だ。</span>（以壽司為代表的日本料理，在國外也很受歡迎）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面要放<b>最具代表性、最有名、地位最高</b>的那個。<span class='gd-jp'>社員をはじめ、社長も参加した</span>聽起來就很怪，順序反了，要說<span class='gd-jp'>社長をはじめ、社員も参加した</span>。<br>・後面一定要帶出「還有其他的」，常搭配<span class='gd-jp'>や</span>、<span class='gd-jp'>など</span>、<span class='gd-jp'>多くの</span>、<span class='gd-jp'>全員</span>、<span class='gd-jp'>も</span>。只講一個東西就不能用。<br>・這裡的はじめ不是時間上的「開始」。「從九月開始」要說<span class='gd-jp'>9月から</span>，不能說9月をはじめ。<br>・語氣偏正式，新聞、導覽、致詞常用。跟朋友聊天說<span class='gd-jp'>京都とか奈良とか</span>比較自然。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>を中心に</b>也會把某個東西擺在最前面，但意思不一樣。看同一場雨：<br><span class='gd-jp'>東京をはじめ、関東の各地で雨が降った。</span>（東京等關東各地都下了雨）<br>→ 大家都有份，只是先點名東京。<br><span class='gd-jp'>東京を中心に雨が降った。</span>（以東京為中心下了雨）<br>→ 雨集中在東京一帶，東京是核心，越往外越少。</div><div class='gd-warn'>判斷小訣竅：想說「～等等，這些都…」用をはじめ；想說「重點、核心在～」用を中心に。</div>",
  "n3-31": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ほど」就是中文的<b>「～到…的地步」「～得要死」</b>。不直接說「很」，而是丟出一個畫面，讓對方自己感受有多誇張。像中文說「累得要死」「笑到流眼淚」，日文就是<span class='gd-jp'>死ぬほど疲れた</span>、<span class='gd-jp'>涙が出るほど笑った</span>。</div><div class='gd-h'>先抓住句子的順序</div><div class='gd-sec'>中文是先講「累」，再講「到要死」；日文剛好<b>反過來</b>：先講那個畫面，再講有多怎樣。<br>【畫面】＋ほど＋【怎麼樣】</div><div class='gd-ex-line'>・<span class='gd-jp'>涙が出るほど感動した。</span>（感動到流淚）</div><div class='gd-ex-line'>・<span class='gd-jp'>眠れないほど楽しみにしていた。</span>（期待到睡不著）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：辭書形或ない形，直接加ほど。<br><span class='gd-pair'><span class='gd-jp'>涙が出る</span> → <span class='gd-jp'>涙が出るほど</span></span><span class='gd-pair'><span class='gd-jp'>眠れない</span> → <span class='gd-jp'>眠れないほど</span></span><br><b>い形容詞</b>：直接加ほど。<br><span class='gd-pair'><span class='gd-jp'>痛い</span> → <span class='gd-jp'>痛いほど</span></span><br><b>な形容詞</b>：要先加な，再加ほど。<br><span class='gd-pair'><span class='gd-jp'>不思議</span> → <span class='gd-jp'>不思議なほど</span></span><br><b>名詞</b>：直接加ほど。<br><span class='gd-pair'><span class='gd-jp'>山</span> → <span class='gd-jp'>山ほど</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>死ぬほど</span>口語超常用，就是「～得要死」，不是真的要死。</div><div class='gd-ex-line'>・<span class='gd-jp'>このラーメン、死ぬほどおいしい。</span>（這碗拉麵好吃得要命）</div><div class='gd-sec'><span class='gd-tag'>山ほど</span>多到堆成一座山，就是「超多」。</div><div class='gd-ex-line'>・<span class='gd-jp'>宿題が山ほどある。</span>（作業多到爆）</div><div class='gd-sec'><span class='gd-tag'>痛いほどわかる</span>懂到心都痛了，就是「完全能體會」。</div><div class='gd-ex-line'>・<span class='gd-jp'>その気持ち、痛いほどわかるよ。</span>（你的心情我完全懂）</div><div class='gd-sec'><span class='gd-tag'>ほどだ</span>放在句尾也可以，前面先講原因，最後補一句誇張的程度。</div><div class='gd-ex-line'>・<span class='gd-jp'>寒くて、手が動かないほどだった。</span>（冷到手都動不了）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・順序不要照中文排：要說<span class='gd-jp'>涙が出るほど感動した</span>，不是「感動したほど涙が出る」。<br>・な形容詞別忘了な：是<span class='gd-jp'>不思議なほど</span>，不是不思議ほど。<br>・ほど接在<b>數量後面</b>時意思不一樣：<span class='gd-jp'>3時間ほど待った</span>是「等了大約 3 個小時」，這時候是「大約」，不是誇張。<br>・後面接否定的時候也是另一個用法：<span class='gd-jp'>今年の夏は去年ほど暑くない</span>是「今年夏天沒有去年那麼熱」，是在比較，不是「熱到…的地步」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>ほど 和 くらい</b>：講「誇張的程度」時，大部分可以互換。<br><span class='gd-jp'>涙が出るほど笑った。</span>／<span class='gd-jp'>涙が出るくらい笑った。</span>（都是「笑到流眼淚」）<br>くらい比較口語，ほど稍微正式一點。<br>但「<b>程度很低、沒什麼</b>」的時候只能用くらい：<br><span class='gd-jp'>名前くらい自分で書いて。</span>（至少名字自己寫吧）<br>這裡不能換成ほど，因為ほど是往「很誇張」的方向講。</div><div class='gd-sec'><b>ほど 和 ば〜ほど</b>：<span class='gd-jp'>練習すればするほど上手になる</span>是「越練習越厲害」，講的是兩件事一起變化，跟這裡的「到～地步」不一樣。</div><div class='gd-warn'>判斷小訣竅：想講「誇張到～」，ほど和くらい都行；想講「這點小事、至少～」，只能用くらい；看到「～ば～ほど」，就是「越～越～」。</div>",
  "n3-32": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜くらい」就像中文的<b>「～到～的地步」</b>。中文說「笑到肚子痛」「累到不想動」，是拿一個具體畫面來形容程度有多誇張，日文就用くらい：<span class='gd-jp'>お腹が痛くなるくらい笑った。</span>（笑到肚子痛）。<span class='gd-jp'>くらい</span>和<span class='gd-jp'>ぐらい</span>意思完全一樣，兩個都可以用。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>誇張形容</span>くらい前面放一個畫面，後面才是真正要講的狀態。</div><div class='gd-ex-line'>・<span class='gd-jp'>手が震えるくらい緊張した。</span>（緊張到手都在發抖）</div><div class='gd-ex-line'>・<span class='gd-jp'>泣きたいくらい悔しかった。</span>（不甘心到想哭）</div><div class='gd-ex-line'>・<span class='gd-jp'>朝の電車は動けないくらい混んでいる。</span>（早上的電車擠到動都動不了）</div><div class='gd-sec'><span class='gd-tag'>這點小事</span>反過來把程度講得很小，帶有「沒什麼大不了」的感覺。</div><div class='gd-ex-line'>・<span class='gd-jp'>これくらい、自分でできるよ。</span>（這點小事我自己來就好）</div><div class='gd-sec'><span class='gd-tag'>至少～嘛</span>講「最起碼該做到的事」，常帶一點抱怨。</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しくても、電話くらいしてよ。</span>（再忙也至少打個電話嘛）</div><div class='gd-sec'><span class='gd-tag'>沒有比～更～</span>「名詞＋くらい～はない」，用來大力稱讚或強調。</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんくらい優しい人はいない。</span>（沒有人比田中先生更溫柔）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：辭書形或ない形直接接，想做的事用「たい」也可以。<br><span class='gd-pair'><span class='gd-jp'>震える</span> → <span class='gd-jp'>震えるくらい</span></span><span class='gd-pair'><span class='gd-jp'>動けない</span> → <span class='gd-jp'>動けないくらい</span></span><span class='gd-pair'><span class='gd-jp'>泣きたい</span> → <span class='gd-jp'>泣きたいくらい</span></span><br><b>い形容詞</b>：直接接。<span class='gd-pair'><span class='gd-jp'>痛い</span> → <span class='gd-jp'>痛いくらい</span></span><br><b>な形容詞</b>：要先補一個「な」。<span class='gd-pair'><span class='gd-jp'>不思議</span> → <span class='gd-jp'>不思議なくらい</span></span><br><b>名詞</b>：直接接，中間不加「の」。<span class='gd-pair'><span class='gd-jp'>これ</span> → <span class='gd-jp'>これくらい</span></span><span class='gd-pair'><span class='gd-jp'>田中さん</span> → <span class='gd-jp'>田中さんくらい</span></span></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・數字（數量）＋くらい是「大約」，像<span class='gd-jp'>三時間くらい</span>（大約三小時）。動詞、形容詞，或<span class='gd-jp'>これ</span>、<span class='gd-jp'>田中さん</span>這類不是數量的名詞＋くらい，才是「到～的程度」。<br>・前後別放反。くらい前面是用來比喻的畫面，後面是真正的狀態：<span class='gd-jp'>手が震えるくらい緊張した</span>，不是「緊張したくらい手が震えた」。<br>・前面的動詞通常用辭書形或ない形就好，過去的事只要把句尾改成過去式：<span class='gd-jp'>声が出ないくらい驚いた。</span>（嚇到說不出話）<br>・な形容詞別忘了「な」，名詞後面別多加「の」：說<span class='gd-jp'>これくらい</span>，不說「これのくらい」。<br>・「這點小事」的用法帶有看輕的語氣，對長輩說<span class='gd-jp'>これくらいできるでしょう</span>（這點事你總會吧），聽起來很沒禮貌。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>ほど</b>也有「到～的程度」的意思。誇張形容的時候兩個都能用，<b>くらい比較口語，ほど比較正式、書面</b>：<br><span class='gd-jp'>手が震えるくらい緊張した。</span>（跟朋友聊天）<br><span class='gd-jp'>手が震えるほど緊張した。</span>（寫文章、演講）</div><div class='gd-sec'>不過遇到<b>「這點小事」「至少」</b>的意思，只能用くらい。<span class='gd-jp'>これほど</span>反而是「這麼～」，是覺得程度很大：<br><span class='gd-jp'>これくらい簡単だよ。</span>（這點程度很簡單啦）<br><span class='gd-jp'>これほど難しいとは思わなかった。</span>（沒想到會這麼難）</div><div class='gd-sec'>另外，「沒有～那麼～」這種比較要用ほど：<span class='gd-jp'>今年は去年ほど寒くない。</span>（今年沒有去年那麼冷）</div><div class='gd-warn'>判斷小訣竅：想說「這點小事、至少～」用くらい；想說「沒有～那麼～」或寫正式文章用ほど；單純誇張形容程度，兩個都行，講話時くらい比較常聽到。</div>",
  "n3-35": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜気味」就是中文的<b>「有點～」「有點～的感覺」</b>。像你喉嚨怪怪的，跟人說「我好像有點感冒」，日文就是<span class='gd-jp'>風邪気味です</span>。多半用來講身體或狀態出現一點<b>不太好的小徵兆</b>，還不嚴重。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>身體狀況</span>最常用。有點感冒、有點累、有點胖、有點睡不夠。</div><div class='gd-ex-line'>・<span class='gd-jp'>風邪気味なので、今日は早く寝ます。</span>（有點感冒，今天早點睡）</div><div class='gd-ex-line'>・<span class='gd-jp'>最近、ちょっと太り気味なんだ。</span>（最近有點胖了）</div><div class='gd-ex-line'>・<span class='gd-jp'>寝不足気味で、授業中に眠くなった。</span>（有點睡眠不足，上課時想睡了）</div><div class='gd-sec'><span class='gd-tag'>心情、事情的進度</span>有點緊張、事情有點落後，也可以用。</div><div class='gd-ex-line'>・<span class='gd-jp'>初めての発表なので、少し緊張気味です。</span>（第一次上台報告，有點緊張）</div><div class='gd-ex-line'>・<span class='gd-jp'>工事が予定より遅れ気味だ。</span>（工程比預定有點落後）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：用ます形，把ます拿掉，直接接気味。<br><span class='gd-pair'><span class='gd-jp'>疲れます</span> → <span class='gd-jp'>疲れ気味</span></span><span class='gd-pair'><span class='gd-jp'>太ります</span> → <span class='gd-jp'>太り気味</span></span><span class='gd-pair'><span class='gd-jp'>遅れます</span> → <span class='gd-jp'>遅れ気味</span></span></div><div class='gd-sec'><b>名詞</b>：直接接。<br><span class='gd-pair'><span class='gd-jp'>風邪</span> → <span class='gd-jp'>風邪気味</span></span><span class='gd-pair'><span class='gd-jp'>緊張</span> → <span class='gd-jp'>緊張気味</span></span><span class='gd-pair'><span class='gd-jp'>運動不足</span> → <span class='gd-jp'>運動不足気味</span></span></div><div class='gd-sec'>「〜気味」本身用起來像名詞：句尾加<span class='gd-jp'>だ／です</span>；後面要接名詞時用<span class='gd-jp'>の</span>；要接下一句就用<span class='gd-jp'>で</span>或<span class='gd-jp'>なので</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>風邪気味の人は、マスクをしてください。</span>（有點感冒的人請戴口罩）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・接在別的字後面時念<b>ぎみ</b>，不是きみ：<span class='gd-jp'>風邪気味</span>念かぜぎみ。<br>・動詞要用ます形把ます拿掉的樣子，不能用辭書形：說<span class='gd-jp'>太り気味</span>，不能說太る気味。<br>・形容詞不直接接気味，「有點熱」不會說暑い気味，要說<span class='gd-jp'>ちょっと暑い</span>。<br>・幾乎只講不太好的狀況。「有點開心」「有點有精神」不會用気味。<br>・接名詞時用<span class='gd-jp'>の</span>：<span class='gd-jp'>風邪気味の人</span>，不是風邪気味な人。<br>・雖然気味已經有「有點」的意思，日本人還是很常前面再加<span class='gd-jp'>少し</span>、<span class='gd-jp'>ちょっと</span>，這樣講很自然，不算重複。<br>・<span class='gd-jp'>気味が悪い</span>（念きみがわるい）是「毛毛的、噁心」，跟這個文法無關，不要搞混。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>〜がち</b>＝<b>常常會</b>那樣、容易那樣（講次數、習慣）。<br><b>〜気味</b>＝<b>現在</b>有點那樣的徵兆（講此刻的狀態）。</div><div class='gd-ex-line'>・<span class='gd-jp'>今日はちょっと風邪気味です。</span>（今天有點感冒）</div><div class='gd-ex-line'>・<span class='gd-jp'>冬は風邪をひきがちです。</span>（冬天常常感冒）</div><div class='gd-sec'><b>〜っぽい</b>也能講<span class='gd-jp'>風邪っぽい</span>（好像感冒了），意思跟<span class='gd-jp'>風邪気味</span>很接近，但比較口語，跟朋友聊天用；跟主管、醫生講，用<span class='gd-jp'>風邪気味です</span>比較得體。っぽい的範圍也廣很多，<span class='gd-jp'>子どもっぽい</span>（孩子氣）、<span class='gd-jp'>白っぽい</span>（偏白）都是っぽい，這些不能換成気味。</div><div class='gd-warn'>判斷小訣竅：想說「最近常常～」用がち；想說「現在有點～」用気味；跟朋友隨口說「好像～」可以用っぽい。</div>",
  "n3-36": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜っぱなし」就是中文的<b>「～了就丟著不管」「開著都不關」</b>。像媽媽唸你：「燈開著都不關！」「衣服脫了就亂丟！」日文就說<span class='gd-jp'>つけっぱなし</span>、<span class='gd-jp'>出しっぱなし</span>、<span class='gd-jp'>脱ぎっぱなし</span>，多半帶著<b>抱怨、不滿</b>的口氣。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>用ます形，把ます拿掉，直接加「っぱなし」。三類動詞都一樣，不用另外分。<br><span class='gd-pair'><span class='gd-jp'>つけます</span> → 把ます拿掉 → <span class='gd-jp'>つけっぱなし</span></span>（開著不關）<br><span class='gd-pair'><span class='gd-jp'>出します</span> → <span class='gd-jp'>出しっぱなし</span></span>（拿出來不收）<br><span class='gd-pair'><span class='gd-jp'>脱ぎます</span> → <span class='gd-jp'>脱ぎっぱなし</span></span>（脫了就丟著）<br><span class='gd-pair'><span class='gd-jp'>開けます</span> → <span class='gd-jp'>開けっぱなし</span></span>（打開不關）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>該收沒收</span>做了一個動作，之後本來該關、該收、該整理，結果放著不管。最常用的就是這個。</div><div class='gd-ex-line'>・<span class='gd-jp'>テレビをつけっぱなしで寝てしまった。</span>（開著電視就睡著了）</div><div class='gd-ex-line'>・<span class='gd-jp'>水が出しっぱなしだよ。</span>（水一直開著沒關耶）</div><div class='gd-ex-line'>・<span class='gd-jp'>服を脱ぎっぱなしにしないで。</span>（衣服不要脫了就丟著）</div><div class='gd-sec'><span class='gd-tag'>一直保持同一個狀態</span>同一件事一直持續、停不下來，通常有「太久了、好累」的感覺。</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は一日中立ちっぱなしで、足が痛い。</span>（今天整天一直站著，腳好痛）</div><div class='gd-ex-line'>・<span class='gd-jp'>朝から働きっぱなしで疲れた。</span>（從早上一直工作到現在，好累）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'>・<b>〜っぱなしだ</b>：<span class='gd-jp'>窓が開けっぱなしだ。</span>（窗戶一直開著沒關）<br>・<b>〜っぱなしで、〜</b>：後面接「就怎樣了」，像上面的「開著電視就睡著了」。<br>・<b>〜っぱなしにする</b>：讓它放著不管。叫人別這樣就說<span class='gd-jp'>〜っぱなしにしないで</span>。<br>・<b>〜っぱなしの＋名詞</b>：<span class='gd-jp'>出しっぱなしの本</span>（拿出來沒收的書）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・接的是<b>ます形把ます拿掉</b>，不是辭書形：要說<span class='gd-jp'>つけっぱなし</span>，不是つけるっぱなし。<br>・中間有個<b>小っ</b>，要停一拍念「つけ・っ・ぱなし」，不要念成つけぱなし。<br>・它常帶有「該處理卻沒處理」的不滿（尤其是「該收沒收」的用法）。如果只是單純交代「在某狀態下做了某事」、沒有要抱怨，用「〜たまま」比較自然。不過「一直站著、一直工作」這種持續太久的用法不能換成たまま：<span class='gd-jp'>立ったまま</span>只是「站著（做某事）」，沒有「站了很久」的意思。<br>・っぱなし的重點是「一直放著那個狀態不管」，不一定是不小心。故意讓它一直保持也可以說，像<span class='gd-jp'>換気のために窓を開けっぱなしにしている。</span>（為了通風，窗戶一直開著）。如果想強調「為了某個目的先弄好」，就用〜ておく。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「窗戶開著出門」：<br><b>〜たまま</b>＝單純交代狀態，沒有特別的情緒：<span class='gd-jp'>窓を開けたまま出かけた。</span>（開著窗就出門了）<br><b>〜っぱなし</b>＝帶著「該關沒關」的不滿：<span class='gd-jp'>窓を開けっぱなしで出かけた。</span>（窗戶開著都沒關就出門了）<br><b>〜ておく</b>＝<b>故意</b>讓它保持那樣，有目的：<span class='gd-jp'>暑いから、窓を開けておいた。</span>（因為很熱，我先把窗戶開著）<br>接法也不一樣：たまま接た形，ておく接て形，っぱなし接ます形把ます拿掉。</div><div class='gd-warn'>判斷小訣竅：想抱怨「怎麼都不收」用っぱなし；只是說「保持那樣」用たまま；「故意先弄好」用ておく。</div>",
  "n3-37": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>兩個都在講「跟某種人很搭」，差在東西<b>是不是專門為他做的</b>。<br><b>向き（むき）</b>＝「很適合～」，看東西本身的性質，不管原本是做給誰的。<br><b>向け（むけ）</b>＝「專為～設計的」，一開始就鎖定這群人來做，像中文的「兒童版」「新手專用」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>兩個都直接接在<b>名詞</b>後面，表示「給誰」或「什麼情況」。<br>放句尾：<span class='gd-pair'><span class='gd-jp'>子供</span> → <span class='gd-jp'>子供向きだ</span></span><span class='gd-pair'><span class='gd-jp'>子供</span> → <span class='gd-jp'>子供向けだ</span></span><br>後面接名詞：可以加「の」（<span class='gd-jp'>初心者向けの講座</span>），也常直接連成一個詞（<span class='gd-jp'>初心者向け講座</span>、<span class='gd-jp'>子供向け番組</span>），兩種都對。直接連在一起的寫法在標題、廣告、商品說明特別常見。你自己造句時，先用加「の」的寫法最保險。<br>後面接動詞：<span class='gd-jp'>向けに</span>＋<span class='gd-jp'>作る</span>、<span class='gd-jp'>書く</span>這類動詞，表示「為了～而做」。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>向き</span>東西本身的條件剛好合適，常用來評論房子、工作、個性、衣服。</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋は一人暮らし向きだ。</span>（這間房間很適合一個人住）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は営業向きの性格だ。</span>（他的個性很適合跑業務）</div><div class='gd-sec'>不適合就說<b>不向き</b>：</div><div class='gd-ex-line'>・<span class='gd-jp'>この靴は長く歩くのには不向きだ。</span>（這雙鞋不適合走長路）</div><div class='gd-sec'><span class='gd-tag'>向け</span>商品、節目、服務在設計的時候就鎖定某群人。</div><div class='gd-ex-line'>・<span class='gd-jp'>外国人向けのパンフレットをください。</span>（請給我外國人用的簡介）</div><div class='gd-ex-line'>・<span class='gd-jp'>このアプリは高齢者向けに作られている。</span>（這個 App 是為長輩設計的）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・念法：向き是<b>むき</b>，向け是<b>むけ</b>，只差最後一個音，聽的時候要注意。<br>・「為了～而做」要用<span class='gd-jp'>向けに作る</span>，不會說向きに作る，因為向き不是在講製作的目的。<br>・「不適合」只有<span class='gd-jp'>不向き</span>，沒有「不向け」這個說法。<br>・<span class='gd-jp'>南向きの部屋</span>是「朝南的房間」，這裡的向き是<b>方向</b>，跟「適合」是不同的意思，不要搞混。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講一本書跟小孩的關係：<br><span class='gd-jp'>これは子供向けの本だ。</span>（這是童書，本來就是寫給小孩看的）<br><span class='gd-jp'>大人向けに書かれた本だが、やさしいので子供向きでもある。</span>（這本書本來是寫給大人的，但內容簡單，所以也適合小孩）<br>第二句剛好看得出差別：做給誰看是<b>向け</b>，結果適合誰是<b>向き</b>，同一本書可以兩個都用。</div><div class='gd-warn'>判斷小訣竅：能換成「專為～做的」就用向け；只是覺得「很適合～」就用向き。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>向き是從動詞<span class='gd-jp'>向く</span>（適合）來的，所以也可以直接說<span class='gd-jp'>この仕事は私に向いている。</span>（這份工作很適合我）、<span class='gd-jp'>私は細かい作業に向いていない。</span>（我不適合做細活）。</div>",
  "n3-38": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜一方だ」就是中文的<b>「只會越來越～」「有增無減」「每況愈下」</b>。事情一直往同一個方向變，沒有停下來、也沒有要回頭的樣子，而且<b>多半是往不好的方向</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>物価は上がる一方だ。</span>（物價只漲不跌）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞辭書形（字典上查到的原形）＋一方だ</b>。<br><span class='gd-pair'><span class='gd-jp'>増える</span> → <span class='gd-jp'>増える一方だ</span></span>（一直增加）<br><span class='gd-pair'><span class='gd-jp'>悪化する</span> → <span class='gd-jp'>悪化する一方だ</span></span>（持續惡化）<br>前面的動詞要是<b>「會變化」的動詞</b>，像<span class='gd-jp'>増える</span>、<span class='gd-jp'>減る</span>、<span class='gd-jp'>上がる</span>、<span class='gd-jp'>下がる</span>、<span class='gd-jp'>広がる</span>、<span class='gd-jp'>進む</span>。</div><div class='gd-sec'><span class='gd-tag'>形容詞</span>形容詞不能直接接，要先變成「〜くなる」「〜になる」（變得～），再接一方だ。<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → い換成く，加なる → <span class='gd-jp'>寒くなる一方だ</span></span><br><span class='gd-pair'><span class='gd-jp'>不便</span> → 加になる → <span class='gd-jp'>不便になる一方だ</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>抱怨情況變糟</span>新聞、跟人聊近況時很常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>最近、仕事が増える一方だ。</span>（最近工作只增不減）</div><div class='gd-ex-line'>・<span class='gd-jp'>父の病気は悪くなる一方だ。</span>（爸爸的病一直在惡化）</div><div class='gd-ex-line'>・<span class='gd-jp'>この町は人が減って、寂しくなる一方だ。</span>（這個小鎮人越來越少，越來越冷清）</div><div class='gd-sec'><span class='gd-tag'>中性的趨勢</span>不一定是壞事，單純講「一直在往上衝」也可以。</div><div class='gd-ex-line'>・<span class='gd-jp'>このアプリの利用者は増える一方だ。</span>（這個 App 的使用者一直在增加）</div><div class='gd-sec'>講過去的事就用<b>一方だった</b>：<span class='gd-jp'>その後、二人の関係は悪くなる一方だった。</span>（後來兩個人的關係越來越差）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・中文「一直在～」很容易讓你拿來講「一直在做某個動作」，這是錯的。<b>一方だ只能講變化</b>：<br>　×<span class='gd-jp'>弟は毎日ゲームをする一方だ。</span><br>　○<span class='gd-jp'>弟は毎日ゲームばかりしている。</span>（弟弟每天都在打電動）<br>・前面一定是<b>辭書形</b>，不要接ている或ます：×<span class='gd-jp'>増えている一方だ</span>、×<span class='gd-jp'>増えます一方だ</span>。要講禮貌一點，改後面就好：<span class='gd-jp'>増える一方です</span>。<br>・形容詞別直接接：×<span class='gd-jp'>寒い一方だ</span>，要說<span class='gd-jp'>寒くなる一方だ</span>。<br>・語氣帶有「看不到好轉」的無奈感，拿來講好消息的情況比較少。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>〜一方だ</b>（放在句尾）＝一直往某方向變：<span class='gd-jp'>家賃は高くなる一方だ。</span>（房租只會越來越貴）<br><b>〜ばかりだ</b>（接辭書形）＝意思幾乎一樣，比較口語，而且幾乎只用在壞事：<span class='gd-jp'>家賃は高くなるばかりだ。</span>（房租只會越來越貴）<br><b>〜一方で</b>（放在句子中間）＝「另一方面」，拿來對比兩件事，跟變化無關：<span class='gd-jp'>この町は便利な一方で、家賃が高い。</span>（這個城市很方便，但另一方面房租很貴）</div><div class='gd-warn'>判斷小訣竅：<b>句尾的一方だ</b>是「只會越來越～」；<b>句子中間的一方で</b>是「另一方面」。看到一方，先看它在哪裡。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>想講「慢慢變成～」的過程，可以接著學「〜てくる・〜ていく」：<span class='gd-jp'>だんだん寒くなってきた。</span>（漸漸變冷了）</div>",
  "n3-39": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ようにする」就是<b>「我盡量～」「我有在注意～」</b>。就像中文說「我最近有在注意少喝飲料」，重點是你有在刻意努力，不保證每次都做到。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>要做的事：辭書形（字典裡查到的原本樣子）＋ようにする<br><span class='gd-pair'><span class='gd-jp'>早く寝る</span> → <span class='gd-jp'>早く寝るようにする</span>（盡量早睡）</span><br>不要做的事：ない形＋ようにする<br><span class='gd-pair'><span class='gd-jp'>忘れない</span> → <span class='gd-jp'>忘れないようにする</span>（盡量不要忘記）</span><br>要講得禮貌，只要改最後面：<span class='gd-pair'><span class='gd-jp'>ようにする</span> → <span class='gd-jp'>ようにします</span></span></div><div class='gd-h'>最常聽到的三種樣子</div><div class='gd-sec'><span class='gd-tag'>ようにしている</span>最近一直在保持的習慣，日常最常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>毎晩10時までに寝るようにしている。</span>（我都盡量 10 點前睡）</div><div class='gd-ex-line'>・<span class='gd-jp'>エレベーターより階段を使うようにしている。</span>（我都盡量走樓梯，不搭電梯）</div><div class='gd-sec'><span class='gd-tag'>ようにする</span>從現在開始要注意。</div><div class='gd-ex-line'>・<span class='gd-jp'>これからは遅刻しないようにします。</span>（以後我會注意不遲到）</div><div class='gd-sec'><span class='gd-tag'>ようにしてください</span>請對方盡量做到，醫生、老師很常講。</div><div class='gd-ex-line'>・<span class='gd-jp'>水をたくさん飲むようにしてください。</span>（請盡量多喝水）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面只能接辭書形或ない形，不能接ます形或た形。不能說寝ますようにする、寝たようにする，要禮貌就改尾巴：<span class='gd-jp'>寝るようにします</span>。<br>・「我平常都有在～」要用<b>ようにしている</b>；用<b>ようにする／ようにします</b>，聽起來是「從現在起我會注意」，還沒開始做。<br>・只能用在<b>自己控制得了的事</b>。像「希望不要下雨」就不能用ようにする，因為下不下雨不是你決定的。<br>・<span class='gd-jp'>ようにしてください</span>帶有提醒、指示的口氣，醫生對病人、老師對學生講很自然；對主管、客人講，會像在教對方做事，要小心。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣跟「講日文」有關，換一個尾巴，意思就不一樣：<br><b>ようになる</b>＝慢慢<b>變成</b>那樣（結果）：<span class='gd-jp'>日本語が話せるようになった。</span>（我變得會講日文了）<br><b>ようにする</b>＝自己<b>刻意去做</b>（努力）：<span class='gd-jp'>毎日日本語を話すようにしている。</span>（我每天都盡量講日文）<br><b>ことにする</b>＝<b>下了一個決定</b>：<span class='gd-jp'>毎日日本語を話すことにした。</span>（我決定每天都講日文）</div><div class='gd-warn'>判斷小訣竅：「變成～了」是ようになる，「盡量～」是ようにする，「決定～」是ことにする。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>「〜ようになる」（變得～）會跟這課一起出現，可以接著學。另外還有一個「〜ように」，意思是「為了（讓）～」，例如：<span class='gd-jp'>忘れないように、メモしておく。</span>（為了不要忘記，先記下來）它跟ようにする長得很像，之後學到再對照。</div>",
  "n3-40": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ようになる」就是中文的<b>「現在會～了」「開始會～了」</b>。重點是<b>以前不是這樣，現在變成這樣</b>，就像「我現在敢一個人去日本玩了」「小孩最近會自己穿鞋了」。講已經發生的變化，通常用過去式「<span class='gd-jp'>ようになった</span>」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>能力變了</span>以前不會，現在會了：前面放<b>可能形</b>（就是表示「能～、會～」的那個形）。<br><span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読める</span> → <span class='gd-jp'>読めるようになった</span></span><br><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きられる</span> → <span class='gd-jp'>起きられるようになった</span></span><br><b>例外</b>：<span class='gd-jp'>わかる</span>、<span class='gd-jp'>見える</span>、<span class='gd-jp'>聞こえる</span>、<span class='gd-jp'>できる</span>這類動詞本身就有「能夠」的意思，直接用原形：<span class='gd-jp'>わかるようになった</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>息子がひらがなを読めるようになった。</span>（兒子會讀平假名了）</div><div class='gd-ex-line'>・<span class='gd-jp'>練習して、泳げるようになった。</span>（練習之後，我學會游泳了）</div><div class='gd-sec'><span class='gd-tag'>習慣變了</span>以前沒在做，現在開始會做：辭書形＋ようになる。</div><div class='gd-ex-line'>・<span class='gd-jp'>結婚してから、毎日料理するようになった。</span>（結婚之後，我開始每天煮飯了）</div><div class='gd-ex-line'>・<span class='gd-jp'>何度も通ううちに、店員と雑談するようになった。</span>（常去之後，慢慢會跟店員閒聊了）</div><div class='gd-h'>可能形快速複習</div><div class='gd-sec'><b>第一類（五段動詞）</b>：最後一個音換成同一行的「え」段音，再加る。<br><span class='gd-pair'><span class='gd-jp'>読む</span> → む換成め → <span class='gd-jp'>読める</span></span><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話せる</span></span><br><b>第二類（一段動詞）</b>：把る拿掉，加られる。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べられる</span></span><br><b>第三類（直接背）</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>できる</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来られる</span>（こられる）</span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>ようになりたい</span>希望自己變得會。</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語がペラペラ話せるようになりたい。</span>（我想變得能講一口流利的日文）</div><div class='gd-sec'><span class='gd-tag'>ようになる</span>用現在式講「之後會變得～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日練習すれば、すぐ泳げるようになりますよ。</span>（每天練習的話，很快就會游了喔）</div><div class='gd-sec'><span class='gd-tag'>ようになってきた</span>正在一點一點變。</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語が少しわかるようになってきた。</span>（日文慢慢聽得懂一點了）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・講「學會」要用可能形：<span class='gd-jp'>泳げるようになった</span>是「學會游泳了」；<span class='gd-jp'>泳ぐようになった</span>是「開始有在游泳」（變成習慣），意思不一樣。但<span class='gd-jp'>わかる</span>、<span class='gd-jp'>見える</span>、<span class='gd-jp'>聞こえる</span>、<span class='gd-jp'>できる</span>這類直接用原形，不能說わかれる、見えられる。<br>・講「變得不～了」，日常更常用「なくなる」：<span class='gd-jp'>辛いものが食べられなくなった</span>（變得不能吃辣了）、<span class='gd-jp'>タバコを吸わなくなった</span>（不抽菸了）。<br>・中文都說「變得」，但要講「變成某種狀態」時，<b>形容詞、名詞不能直接接ようになる</b>：「變得很忙」是<span class='gd-jp'>忙しくなった</span>，「變漂亮」是<span class='gd-jp'>きれいになった</span>，「當上老師」是<span class='gd-jp'>先生になった</span>。補充：名詞＋<span class='gd-jp'>のようになる</span>是「變得像～一樣」，例如<span class='gd-jp'>先生のようになりたい</span>（想變得像老師那樣），不是「當上老師」，意思不一樣喔。<br>・努力練出來的結果也可以用，不是只有「自然而然」才能用。它的重點是<b>結果變了</b>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講「早起」：<br><b>ようにする</b>＝刻意在努力：<span class='gd-jp'>毎朝6時に起きるようにしている。</span>（我都盡量 6 點起床）<br><b>ようになる</b>＝結果變了：<span class='gd-jp'>朝6時に起きられるようになった。</span>（我現在 6 點起得來了）<br><b>ことになる</b>＝被決定、被安排：<span class='gd-jp'>来月から、6時に出勤することになった。</span>（下個月開始要 6 點上班了）</div><div class='gd-warn'>判斷小訣竅：「盡量～」是ようにする，「現在會～了」是ようになる，「被決定要～」是ことになる。</div>",
  "n3-45": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜はずだ」就是中文的<b>「照理說應該～」</b>。你手上有根據（看到的、知道的、事先安排好的），從這些根據推出一個很有把握的結論。像看到朋友家燈亮著，你會想「他應該在家」，日文就是<span class='gd-jp'>家にいるはずだ</span>。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞、い形容詞</b>：用普通形（不加ます、です的說法）直接接。<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来るはずだ</span></span><span class='gd-pair'><span class='gd-jp'>来た</span> → <span class='gd-jp'>来たはずだ</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いはずだ</span></span></div><div class='gd-sec'><b>な形容詞</b>：把だ換成な。<br><span class='gd-pair'><span class='gd-jp'>便利だ</span> → <span class='gd-jp'>便利なはずだ</span></span></div><div class='gd-sec'><b>名詞</b>：把だ換成の。<br><span class='gd-pair'><span class='gd-jp'>休みだ</span> → <span class='gd-jp'>休みのはずだ</span></span></div><div class='gd-sec'>要講得禮貌一點，就把だ換成です：<span class='gd-jp'>来るはずです</span>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>有根據的推斷</span>從已知的事實推出結論。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は医者だから、詳しいはずだ。</span>（他是醫生，應該很懂）</div><div class='gd-ex-line'>・<span class='gd-jp'>電気がついているから、家にいるはずだ。</span>（燈亮著，他應該在家）</div><div class='gd-sec'><span class='gd-tag'>照安排、照預定</span>時間表、約好的事，照理會怎樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは3時に来るはずです。</span>（田中先生應該三點會到）</div><div class='gd-ex-line'>・<span class='gd-jp'>荷物は明日届くはずです。</span>（包裹應該明天會到）</div><div class='gd-sec'><span class='gd-tag'>明明～卻…</span>用「はずなのに」，心裡很確定，結果卻不是那樣，有「奇怪了」的感覺。</div><div class='gd-ex-line'>・<span class='gd-jp'>ここに置いたはずなのに、ない。</span>（我明明放在這裡，卻不見了）</div><div class='gd-sec'><span class='gd-tag'>難怪</span>先感覺到結果，後來才發現原因，恍然大悟。</div><div class='gd-ex-line'>・<span class='gd-jp'>寒いはずだ。雪が降っている。</span>（難怪這麼冷，原來在下雪）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・中文的「應該」有兩種意思：「照理說會～」和「必須～才對」。<b>はず只有第一種</b>。「你應該早點睡」是在勸人，不能用はず。<br>・名詞後面要加の：是<span class='gd-jp'>医者のはずだ</span>，不是「医者だはずだ」；な形容詞要說<span class='gd-jp'>便利なはずだ</span>。<br>・沒有根據、隨便亂猜的時候不要用はず。はず聽起來很有把握，猜錯了會顯得很武斷。<br>・自己想做的事不要用はず。「我明天打算去」要說<span class='gd-jp'>明日行くつもりだ</span>。はず講的是照道理、照安排會發生的事，不是你的意願。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>はずだ</b>＝照理說會這樣（推斷）：<span class='gd-jp'>会議は3時に始まるはずだ。</span>（照安排，會議應該三點開始）<br><b>べきだ</b>＝應該要這樣做（義務、主張）：<span class='gd-jp'>会議は時間どおりに始めるべきだ。</span>（會議就應該準時開始）</div><div class='gd-sec'><b>ないはずだ</b>＝照理說不會（平靜的推斷）：<span class='gd-jp'>彼は今日来ないはずだ。</span>（照理說他今天不會來）<br><b>はずがない</b>＝不可能（強烈否定）：<span class='gd-jp'>彼が来るはずがない。</span>（他不可能來）</div><div class='gd-warn'>判斷小訣竅：「照理說會～」用はず，「該去做～」用べき；「應該不會」用ないはず，「不可能」用はずがない。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>改成過去的「はずだった」＝本來應該～，結果沒有：<span class='gd-jp'>3時に着くはずだったのに、電車が遅れた。</span>（本來應該三點到，結果電車誤點了）<br>接著可以學表示「不可能」的<span class='gd-jp'>〜はずがない</span>。</div>",
  "n3-46": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜はずがない」就是中文的<b>「不可能～」「怎麼可能～」</b>。你心裡有一個理由，例如她很細心、門有鎖、他練了那麼久，照這個理由推下去，結論是「這件事絕對不會是真的」。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>照道理推</span>手上有根據，很有把握地說「不可能」。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女があんなミスをするはずがない。</span>（她不可能犯那種錯）</div><div class='gd-ex-line'>・<span class='gd-jp'>あんなに練習したんだから、負けるはずがない。</span>（練了那麼多，不可能輸）</div><div class='gd-sec'><span class='gd-tag'>不相信眼前的事</span>碰到意外狀況，脫口說「不可能吧」。</div><div class='gd-ex-line'>・<span class='gd-jp'>え、財布がない？そんなはずない。さっきまであったのに。</span>（咦，錢包不見了？不可能啊，剛剛明明還在）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞、い形容詞</b>：直接接。<br><span class='gd-pair'><span class='gd-jp'>負ける</span> → <span class='gd-jp'>負けるはずがない</span></span><span class='gd-pair'><span class='gd-jp'>暑い</span> → <span class='gd-jp'>暑いはずがない</span></span><br><b>な形容詞</b>：中間要加「な」。<br><span class='gd-pair'><span class='gd-jp'>下手</span> → <span class='gd-jp'>下手なはずがない</span></span><br><b>名詞</b>：中間要加「の」。<br><span class='gd-pair'><span class='gd-jp'>犯人</span> → <span class='gd-jp'>犯人のはずがない</span></span><br>要講「不可能做過」或「不可能不～」，就把過去、否定放在はず前面：<br><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったはずがない</span></span>（不可能去過）<br><span class='gd-pair'><span class='gd-jp'>知らない</span> → <span class='gd-jp'>知らないはずがない</span></span>（不可能不知道）</div><div class='gd-ex-line'>・<span class='gd-jp'>まだ4月だから、そんなに暑いはずがない。</span>（才4月，不可能那麼熱）</div><div class='gd-ex-line'>・<span class='gd-jp'>10年も日本に住んでいるんだから、日本語が下手なはずがない。</span>（都在日本住10年了，日文不可能差）</div><div class='gd-ex-line'>・<span class='gd-jp'>あんなに優しい人が犯人のはずがない。</span>（那麼溫柔的人不可能是犯人）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'>「が」常換成「は」，口氣更強調；口語裡也常把「が」拿掉。最常聽到的就是<span class='gd-jp'>そんなはずはない</span>、<span class='gd-jp'>そんなはずない</span>（不可能吧、怎麼會），整句直接背起來。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞、な形容詞不能直接接：要說<span class='gd-jp'>犯人のはずがない</span>，不是「犯人だはずがない」。<br>・中文「不能」可以表示好幾種意思，日文要分開講。はずがない只管「不可能」，「不可以」和「不會（能力）」都不能用它。「這裡不能抽菸」是<span class='gd-jp'>ここでたばこを吸ってはいけません</span>，「我不會游泳」是<span class='gd-jp'>泳げません</span>。<br>・<span class='gd-jp'>知らないはずがない</span>是「不可能不知道」，意思等於「他一定知道」，不要翻成「不可能知道」。<br>・語氣很強。當面跟人說<span class='gd-jp'>あなたにできるはずがない</span>（你不可能做得到）很傷人，要小心。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一件事「他會不會來」，口氣不一樣：<br><b>はずだ</b>＝應該會（有把握）：<span class='gd-jp'>彼は来るはずだ。</span>（他應該會來）<br><b>ないはずだ</b>＝應該不會（偏向否定，但沒有說死）：<span class='gd-jp'>彼は来ないはずだ。</span>（他應該不會來）<br><b>はずがない</b>＝絕不可能（說死了）：<span class='gd-jp'>彼が来るはずがない。</span>（他不可能來）<br><b>わけがない</b>＝意思跟はずがない幾乎一樣，大部分情況可以互換。日常聊天更常聽到，口氣比較衝、比較帶情緒：<span class='gd-jp'>彼が来るわけがない。</span>（他怎麼可能會來）</div><div class='gd-warn'>判斷小訣竅：「應該不會」用ないはずだ，「絕不可能」用はずがない；跟朋友講話、情緒比較激動時，常會換成わけがない。</div>",
  "n3-48": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ことだ」就是長輩、前輩給你建議時那句<b>「聽我的，你就～吧」「～就對了」</b>。比如學長跟你說「想考過 N3？每天背單字就對了」，日文就是<span class='gd-jp'>毎日単語を覚えることだ。</span></div><div class='gd-h'>怎麼接</div><div class='gd-sec'>叫對方去做：辭書形＋ことだ<br><span class='gd-pair'><span class='gd-jp'>休む</span> → <span class='gd-jp'>休むことだ</span></span>（就好好休息吧）<br>叫對方不要做：ない形＋ことだ<br><span class='gd-pair'><span class='gd-jp'>無理をしない</span> → <span class='gd-jp'>無理をしないことだ</span></span>（就別太勉強了）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>給建議</span>前面常先講「如果你想～」「為了～」，後面再用ことだ給答案。</div><div class='gd-ex-line'>・<span class='gd-jp'>風邪のときは、ゆっくり休むことだ。</span>（感冒的時候就好好休息）</div><div class='gd-ex-line'>・<span class='gd-jp'>やせたいなら、甘いものを減らすことだ。</span>（想瘦的話，就少吃甜的）</div><div class='gd-sec'><span class='gd-tag'>勸對方別做</span>用ない形，口氣像「你就別～了」。</div><div class='gd-ex-line'>・<span class='gd-jp'>試験の前の日は、夜遅くまで勉強しないことだ。</span>（考試前一天就別熬夜唸書了）</div><div class='gd-sec'>除了當面講，勵志書、專欄、前輩經驗談也很常看到這種寫法。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・這是<b>上對下</b>的口氣，有一點「我比你懂」的感覺。對老師、主管、客人不要用，就算改成<span class='gd-jp'>〜ことです</span>還是一樣不禮貌。對長輩可以改說<span class='gd-jp'>〜たほうがいいと思います</span>。<br>・前面只接辭書形或ない形，不能接た形：<span class='gd-jp'>休んだことだ</span>不是「你就休息吧」的意思。<br>・前面如果是形容詞，像<span class='gd-jp'>うらやましいことだ</span>、<span class='gd-jp'>残念なことだ</span>，那是在抒發感受（真令人羨慕、真遺憾），<b>不是給建議</b>，別搞混。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是朋友感冒還硬要去上班：<br><b>ことだ</b>＝針對你給建議：<span class='gd-jp'>今日は休むことだ。</span>（你今天就請假休息吧）<br><b>べきだ</b>＝講道理、該不該：<span class='gd-jp'>病気のときは休むべきだ。</span>（生病的時候本來就應該休息）。べきだ還可以回頭檢討：<span class='gd-jp'>昨日休むべきだった。</span>（昨天就該請假的），ことだ沒有這種用法。<br><b>ものだ</b>＝講社會常識：<span class='gd-jp'>体調が悪いときは無理をしないものだ。</span>（身體不舒服時本來就不該勉強）<br><b>ことはない</b>＝「沒必要～」，是在安撫人：<span class='gd-jp'>そんなに心配することはない。</span>（不用那麼擔心）。跟<span class='gd-jp'>心配しないことだ。</span>（你就別擔心了）不一樣，前者是說「沒必要」，後者是勸你「不要」。</div><div class='gd-warn'>判斷小訣竅：對眼前的人說「你就～吧」用ことだ；講道理、該不該用べきだ；講大家都知道的常識用ものだ；說「不用～」用ことはない。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>接著看<span class='gd-jp'>〜ことはない</span>（沒必要～）和<span class='gd-jp'>〜べきだ</span>（應該～），三個放在一起記，最不容易混。</div>",
  "n3-49": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ことはない」就是中文的<b>「不用～啦」「何必～」</b>。看到對方在擔心、在道歉、在趕，你跟他說「沒那個必要」，通常帶一點安慰、勸人放輕鬆的味道。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞的辭書形（字典上那個原本的樣子）直接加ことはない。<br><span class='gd-pair'><span class='gd-jp'>心配する</span> → <span class='gd-jp'>心配することはない</span></span>（不用擔心）<br><span class='gd-pair'><span class='gd-jp'>謝る</span> → <span class='gd-jp'>謝ることはない</span></span>（不用道歉）<br><span class='gd-pair'><span class='gd-jp'>急ぐ</span> → <span class='gd-jp'>急ぐことはない</span></span>（不用急）<br>講客氣一點：<span class='gd-jp'>ことはありません</span>。跟朋友講常把「は」拿掉，變成<span class='gd-jp'>ことない</span>，後面再加個<span class='gd-jp'>よ</span>。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>安慰</span>對方在煩惱、自責的時候。</div><div class='gd-ex-line'>・<span class='gd-jp'>大したことじゃないから、気にすることないよ。</span>（沒什麼大不了的，別在意啦）</div><div class='gd-sec'><span class='gd-tag'>叫對方別多費工</span>常跟「わざわざ（特地）」一起出現。</div><div class='gd-ex-line'>・<span class='gd-jp'>わざわざ来ることはないよ。電話でいいから。</span>（不用特地跑一趟啦，打電話就好）</div><div class='gd-sec'><span class='gd-tag'>何必～</span>前面加「何も」，就變成有點受不了的「何必～呢」。</div><div class='gd-ex-line'>・<span class='gd-jp'>何もそんなに怒ることはないでしょう。</span>（何必氣成那樣呢）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面一定是<b>辭書形</b>。換成た形就變成完全不同的意思「沒～過」（下面會對照）。<br>・它是「<b>沒必要</b>」，不是「<b>不可以</b>」。<span class='gd-jp'>行くことはない</span>是「不用去」，你想去還是可以去；「不准去」要說<span class='gd-jp'>行ってはいけない</span>。<br>・這句話有「我幫你判斷了：不需要」的口氣，對朋友、晚輩講很自然。對主管、客人直接說「〜ことはありません」可能有點像在指導對方，改說<span class='gd-jp'>大丈夫です</span>或<span class='gd-jp'>ご心配なく</span>比較穩。<br>・有時候它的意思是「<b>不會發生</b>」：<span class='gd-jp'>もう二度と会うことはないだろう。</span>（應該再也不會見面了吧）。在安慰、勸人的場合是「不用」，在講可能性的時候是「不會」，看前後文判斷。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講「去日本」，前面動詞的形一換，意思就差很多：<br><b>辭書形＋ことはない</b>＝沒必要：<span class='gd-jp'>日本へ行くことはない。</span>（沒必要去日本）<br><b>た形＋ことはない</b>＝沒做過：<span class='gd-jp'>日本へ行ったことはない。</span>（我沒去過日本）<br><b>ない形＋ことはない</b>＝也不是不會：<span class='gd-jp'>日本へ行かないことはない。</span>（我也不是不去日本，偶爾還是會去）</div><div class='gd-warn'>判斷小訣竅：看「こと」前面那個字。原形是「不用」，た是「沒做過」，ない是「也不是不」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>它的反面是「〜ことだ」＝最好去做：<span class='gd-jp'>心配なら、医者に相談することだ。</span>（擔心的話，最好去找醫生談談）。一個勸你做，一個勸你不用做。<br>意思很接近的還有<span class='gd-jp'>心配する必要はない</span>（沒有擔心的必要），語氣比較客觀、比較硬，文章裡常看到。</div>",
  "n3-50": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>兩個都在講「決定」，差在<b>是誰拍板的</b>。<br><b>ことにする</b>＝我自己決定：「我決定戒菸」。<br><b>ことになる</b>＝不是我自己拍板的，是公司安排、大家討論出來，或事情自然發展成這樣：「公司派我調職了」。<br>中文的「我決定～」對應ことにする，「結果變成要～」「被安排～」就是ことになる。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>要做的事：辭書形＋ことにする／ことになる　<span class='gd-pair'><span class='gd-jp'>やめる</span> → <span class='gd-jp'>やめることにした</span></span><br>不做的事：ない形＋ことにする／ことになる　<span class='gd-pair'><span class='gd-jp'>帰らない</span> → <span class='gd-jp'>帰らないことにした</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>ことにした</span>我自己下了決定。</div><div class='gd-ex-line'>・<span class='gd-jp'>タバコをやめることにした。</span>（我決定戒菸了）</div><div class='gd-ex-line'>・<span class='gd-jp'>今年の夏は実家に帰らないことにした。</span>（今年夏天我決定不回老家）</div><div class='gd-sec'><span class='gd-tag'>ことになった</span>公司、學校或別人決定好的，我只是接受結果。</div><div class='gd-ex-line'>・<span class='gd-jp'>来月から大阪に転勤することになった。</span>（我下個月起要調到大阪了）</div><div class='gd-sec'><span class='gd-tag'>報告自己的事</span>就算是自己決定的，日本人報告結婚、離職這類消息時也常用<span class='gd-jp'>ことになりました</span>，聽起來比較謙虛，像是「事情走到這一步」，不會像在強調「是我自己要的」。</div><div class='gd-ex-line'>・<span class='gd-jp'>実は、結婚することになりました。</span>（其實，我要結婚了）</div><div class='gd-sec'><span class='gd-tag'>ことにしている</span>自己給自己定的規矩，一直有在遵守。</div><div class='gd-ex-line'>・<span class='gd-jp'>寝る前はスマホを見ないことにしている。</span>（我規定自己睡前不看手機）</div><div class='gd-sec'><span class='gd-tag'>ことになっている</span>規定、慣例，或已經排好的預定。</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋では靴を脱ぐことになっています。</span>（這個房間規定要脫鞋）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、田中さんと会うことになっている。</span>（明天已經約好要跟田中先生見面）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・中文說「我決定了」，日文通常用過去式<span class='gd-jp'>ことにした</span>，表示決定已經下好了。<br>・旅行、勉強這類可以加する的名詞，要變成動詞再接：<span class='gd-jp'>旅行することにした</span>，不是旅行ことにした。（一般名詞直接接にする，例如<span class='gd-jp'>コーヒーにする</span>，意思是「選～」，跟這裡的用法不同）<br>・<span class='gd-jp'>ことになる</span>不一定有人在做決定，也可以是「照這樣下去，結果會變成～」：<span class='gd-jp'>今やめたら、後で後悔することになるよ。</span>（現在放棄的話，之後會後悔喔）<br>・<span class='gd-jp'>ことにしている</span>是<b>自己</b>定的規矩，<span class='gd-jp'>ことになっている</span>是<b>外面</b>定的規定，不要混在一起。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講「早起」：<br><b>ことにする</b>＝自己下決定：<span class='gd-jp'>明日から6時に起きることにした。</span>（我決定明天開始六點起床）<br><b>ことになる</b>＝被安排、情況變成這樣：<span class='gd-jp'>仕事の関係で、毎朝6時に起きることになった。</span>（因為工作的關係，變成每天要六點起床）<br><b>ようにする</b>＝盡量做到：<span class='gd-jp'>毎朝6時に起きるようにしている。</span>（我每天都盡量六點起床）<br><b>ようになる</b>＝慢慢變成做得到：<span class='gd-jp'>6時に起きられるようになった。</span>（我變得起得來六點了）</div><div class='gd-warn'>判斷小訣竅：有「決定」的感覺用こと，「盡量、變得」用よう。接著看是誰決定的：自己拍板用する，別人安排或自然變成這樣用なる。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'><span class='gd-jp'>ことにする</span>前面接過去式，還可以表示「就當作～」：<span class='gd-jp'>今の話は聞かなかったことにする。</span>（剛剛的話我就當作沒聽到）</div>",
  "n3-51": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ようだ」「〜みたいだ」就是中文的<b>「好像～」「看起來應該是～」</b>。你看到、聽到、感覺到一些線索，自己推出一個判斷，但沒有百分之百確定，就用它。兩個意思一樣：<b>みたい是講話用的輕鬆版</b>，ようだ比較正式，寫文章也能用。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>看到線索推測</span>線索是你<b>自己</b>看到、聽到、感覺到的。</div><div class='gd-ex-line'>・<span class='gd-jp'>隣の部屋、電気が消えている。留守のようだ。</span>（隔壁燈關著，好像沒人在家）</div><div class='gd-ex-line'>・<span class='gd-jp'>あれ、鍵がない。どこかで落としたみたい。</span>（咦，鑰匙不見了，好像掉在哪裡了）</div><div class='gd-sec'>講自己的身體狀況也很常用，意思是「我感覺是這樣，但說不準」。</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょっと熱があるみたい。</span>（我好像有點發燒）</div><div class='gd-sec'><span class='gd-tag'>像～一樣</span>明明不是，但很像。常跟<span class='gd-jp'>まるで</span>（簡直）一起出現。</div><div class='gd-ex-line'>・<span class='gd-jp'>まるで夢みたい。</span>（簡直像做夢一樣）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は春のように暖かい。</span>（今天像春天一樣暖和）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞、い形容詞</b>：用普通形（就是不加ます、です的說法）直接接，兩個都一樣。<br><span class='gd-pair'><span class='gd-jp'>降っている</span> → <span class='gd-jp'>降っているようだ</span></span>／<span class='gd-jp'>降っているみたいだ</span><br><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いようだ</span></span>／<span class='gd-jp'>寒いみたいだ</span></div><div class='gd-sec'><b>名詞、な形容詞</b>：這裡兩個不一樣，要特別記。<br>名詞＋ようだ要先加「の」：<span class='gd-pair'><span class='gd-jp'>留守</span> → <span class='gd-jp'>留守のようだ</span></span><br>名詞＋みたいだ直接接：<span class='gd-pair'><span class='gd-jp'>留守</span> → <span class='gd-jp'>留守みたいだ</span></span><br>な形容詞＋ようだ要先加「な」：<span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなようだ</span></span><br>な形容詞＋みたいだ直接接：<span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かみたいだ</span></span></div><div class='gd-sec'>講過去的事，名詞、な形容詞先變成「だった」再接，這時兩個就一樣了：<span class='gd-pair'><span class='gd-jp'>留守だった</span> → <span class='gd-jp'>留守だったようだ</span></span>／<span class='gd-jp'>留守だったみたいだ</span><br>要講得有禮貌，把だ換成です：<span class='gd-jp'>ようです</span>、<span class='gd-jp'>みたいです</span>。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'>後面接名詞時變成<b>ような／みたいな</b>，後面接動作或形容詞時變成<b>ように／みたいに</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>お寿司みたいな日本料理が好きです。</span>（我喜歡像壽司這類的日本料理）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本人みたいに日本語を話したい。</span>（我想像日本人一樣講日文）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞後面：ようだ要「の」，みたいだ不要。<span class='gd-jp'>学生のようだ</span>、<span class='gd-jp'>学生みたいだ</span>都對，「学生のみたい」「学生ようだ」都錯。<br>・很多人以為普通形要帶「だ」，寫成「留守だみたい」，這是錯的。現在式的名詞直接接：<span class='gd-jp'>留守みたい</span>。<br>・みたい跟「見たい」（想看）念法一樣，要看前後文：<span class='gd-jp'>子供みたい</span>是「像小孩」，<span class='gd-jp'>映画が見たい</span>是「想看電影」。<br>・みたい是口語。寫報告、作文、正式信件用ようです；跟長輩聊天講みたいです可以，但正式場合ようです比較得體。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「下雨」，看你的消息從哪裡來：<br><b>ようだ／みたいだ</b>＝自己看到線索推的：<span class='gd-jp'>みんな傘をさしている。雨が降っているみたいだ。</span>（大家都撐傘，好像在下雨）<br><b>らしい</b>＝聽別人說的，自己沒確認：<span class='gd-jp'>田中さんの話では、外は雨が降っているらしい。</span>（聽田中說，外面好像在下雨）<br><b>そうだ</b>（樣子）＝眼前看起來快要那樣，事情還沒發生：<span class='gd-jp'>空が暗い。雨が降りそうだ。</span>（天好暗，看起來快下雨了）。這個接法不一樣，是把ます形的ます拿掉再加そうだ：<span class='gd-pair'><span class='gd-jp'>降ります</span> → <span class='gd-jp'>降りそうだ</span></span></div><div class='gd-warn'>判斷小訣竅：自己看到、感覺到而推測，用ようだ／みたい；聽人家說的，用らしい；看起來「快要～」，用そうだ。</div>",
  "n3-52": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「らしい」有兩個意思，就像中文的兩句話：<br>①<b>「聽說～」「好像～」</b>：根據聽到、讀到的消息，或看到的客觀線索來推測，不是你自己能確定的。<br>②<b>「很有～的樣子」「很像～」</b>：就像中文說「很有春天的感覺」「這很像他會做的事」。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>①聽說・好像</span>轉述聽到、看到的消息，順便表示「我只是聽說，不保證」。</div><div class='gd-ex-line'>・<span class='gd-jp'>来週から気温が下がるらしい。</span>（聽說下週開始氣溫會下降）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さん、会社を辞めるらしいよ。</span>（聽說田中要辭職喔）</div><div class='gd-ex-line'>・<span class='gd-jp'>あの店のラーメン、すごくおいしいらしい。</span>（聽說那家店的拉麵超好吃）</div><div class='gd-ex-line'>・<span class='gd-jp'>地面が濡れている。雨が降ったらしい。</span>（地上是濕的，好像下過雨了）</div><div class='gd-sec'><span class='gd-tag'>②很有～的樣子</span>前面放名詞，表示「完全符合那個東西該有的感覺」，通常是稱讚。</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は春らしい天気ですね。</span>（今天天氣很有春天的感覺呢）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の発言はいかにも彼らしい。</span>（他的發言很有他的風格）</div><div class='gd-ex-line'>・<span class='gd-jp'>遅刻するなんて、彼らしくない。</span>（居然遲到，真不像他）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>意思①</b><br>動詞、い形容詞：直接接，過去、否定都可以。<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くらしい</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないらしい</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いらしい</span></span><br>な形容詞、名詞：<b>把だ拿掉</b>再接。<br><span class='gd-pair'><span class='gd-jp'>静かだ</span> → だ拿掉 → <span class='gd-jp'>静からしい</span></span><span class='gd-pair'><span class='gd-jp'>雨だ</span> → <span class='gd-jp'>雨らしい</span></span><br>過去的話保留だった：<span class='gd-pair'><span class='gd-jp'>雨だった</span> → <span class='gd-jp'>雨だったらしい</span></span></div><div class='gd-sec'><b>意思②</b><br>名詞＋らしい：<span class='gd-jp'>春らしい</span>、<span class='gd-jp'>学生らしい</span>、<span class='gd-jp'>彼らしい</span><br>常加<span class='gd-jp'>いかにも</span>、<span class='gd-jp'>本当に</span>來加強，例如<span class='gd-jp'>いかにも先生らしい話し方</span>（很有老師架勢的講話方式）。</div><div class='gd-sec'>「らしい」本身變化跟い形容詞一樣：<span class='gd-jp'>らしくない</span>、<span class='gd-jp'>らしかった</span>、<span class='gd-jp'>らしいです</span>。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・な形容詞、名詞不要多加だ：是<span class='gd-jp'>静からしい</span>，不是静かだらしい。<br>・<b>直接接名詞時兩種意思都有可能</b>，要看前後文。例如<span class='gd-jp'>先生らしい人が来た</span>通常是①「來了一個看起來像是老師的人」，不是「很有老師樣子的人」。<br>・否定要放對位置：「聽說他不來」是<span class='gd-jp'>来ないらしい</span>（①，否定前面的動詞）；<span class='gd-jp'>彼らしくない</span>是②「不像他」。<br>・①是「我聽來的」，自己親身經歷的事不能用。自己明天要去，就說<span class='gd-jp'>明日行きます</span>，說「明日行くらしい」聽起來像在講別人的事。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>らしい（①）</b>＝聽說的：<span class='gd-jp'>午後から雨が降るらしい。</span>（聽說下午開始會下雨）<br><b>そうだ（傳聞）</b>＝清楚轉述某個消息來源：<span class='gd-jp'>天気予報によると、午後から雨が降るそうだ。</span>（根據氣象預報，下午開始會下雨）<br><b>ようだ・みたいだ</b>＝自己看到、感覺到：<span class='gd-jp'>傘を持った人が入ってきた。雨が降っているみたい。</span>（有人拿著傘進來，外面好像在下雨）<br>另外，看到眼前的徵兆、覺得馬上要發生，用<span class='gd-jp'>雨が降りそうだ</span>（看起來快下雨了）。</div><div class='gd-warn'>判斷小訣竅：單純原封不動轉述聽到的消息用そうだ；根據聽來的消息或客觀線索，帶點「大概是這樣」的推測感用らしい；以自己的感覺、體驗做判斷用ようだ・みたいだ。</div><div class='gd-sec'><b>らしい（②）跟っぽい</b>也常混：<br><span class='gd-jp'>子どもらしい笑顔</span>（很有小孩樣的天真笑容）：本來就是小孩，符合小孩該有的樣子，偏稱讚。<br><span class='gd-jp'>大人なのに子どもっぽい。</span>（都大人了還很幼稚）：不是小孩卻像小孩，常帶負面意思。</div><div class='gd-warn'>判斷小訣竅：「本來就是，而且很有那個味道」用らしい；「其實不是，卻有點像」用っぽい。</div>",
  "n3-53": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「ために」有兩個意思：最常用的是<b>「為了～」</b>，講目的；另一個是比較正式的<b>「因為～」</b>，講原因。中文的「為了」跟「因為」都有個「為」字，日文則是用同一個ために，要看前後文來分。</div><div class='gd-h'>用法一：為了～（目的）</div><div class='gd-sec'><span class='gd-tag'>為了做到某事</span>動詞用<b>辭書形</b>（字典上查到的原形）＋ために；名詞要先加「の」，變成名詞＋のために。</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に留学するために、アルバイトでお金をためている。</span>（為了去日本留學，我在打工存錢）</div><div class='gd-ex-line'>・<span class='gd-jp'>健康のために、毎朝歩いている。</span>（為了健康，我每天早上走路）</div><div class='gd-sec'><span class='gd-tag'>為了某人好</span>前面放人，就是「為了誰」。</div><div class='gd-ex-line'>・<span class='gd-jp'>家族のために、毎日がんばって働いている。</span>（為了家人，我每天努力工作）</div><div class='gd-h'>用法二：因為～（原因）</div><div class='gd-sec'><span class='gd-tag'>正式的因為</span>前面可以接：動詞的た形或原形、い形容詞、な形容詞＋な、名詞＋の。新聞、車站廣播、公告很常用，而且常把に省掉，只說「ため」。後面多半是已經發生、不太好的結果，但不是一定。</div><div class='gd-ex-line'>・<span class='gd-jp'>大雪のために、電車が止まった。</span>（因為大雪，電車停駛了）</div><div class='gd-ex-line'>・<span class='gd-jp'>事故があったために、道が混んでいる。</span>（因為發生事故，路上在塞車）</div><div class='gd-ex-line'>・<span class='gd-jp'>台風のため、今日の授業は休みです。</span>（因為颱風，今天停課）</div><div class='gd-h'>怎麼分辨是哪一個</div><div class='gd-sec'>前面是<b>想達成、還沒發生的事</b>，後面是為了它做的努力，就是「為了」。<br>前面是<b>已經發生的事或某種狀態</b>，後面是它造成的結果，就是「因為」。<br>看到た形（<span class='gd-jp'>あった</span>、<span class='gd-jp'>降った</span>）一定是原因。名詞＋のために兩種都有可能，要看後面：<span class='gd-jp'>試験のために勉強する</span>（為了考試念書）、<span class='gd-jp'>雪のために遅れた</span>（因為下雪遲到）。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞後面一定要加の：不能說健康ために，要說<span class='gd-jp'>健康のために</span>。<br>・不能接ます形：不能說合格しますために，要說<span class='gd-jp'>合格するために</span>。<br>・「為了」的ために，前後通常是<b>同一個人</b>，而且前面要是<b>自己能決定去做的動作</b>。「會講」「聽得到」「看得懂」這種能力或狀態，要改用ように（下面會比較）。<br>・「因為」的ために很正式，後面不能接拜託、邀約、命令。不能說雨のために傘を持っていこう，要說<span class='gd-jp'>雨だから、傘を持っていこう。</span>（下雨了，帶傘去吧）平常聊天講原因，用から、ので就好。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>「為了」的ために和<b>ように</b>都可以翻成「為了」，但前面放的東西不一樣。<br>同一件事兩種都能講，只是看事情的角度不同：<br>・<span class='gd-jp'>N2に合格するために、毎日勉強している。</span>（為了考過N2，每天念書）：合格する是你要去達成的事。<br>・<span class='gd-jp'>N2に合格できるように、毎日勉強している。</span>（希望能考過N2，每天念書）：合格できる是你希望變成的狀態。<br>下面這種只能用ように：<br>・<span class='gd-jp'>みんなに聞こえるように、大きな声で話した。</span>（為了讓大家都聽得到，我大聲講話）<br>・<span class='gd-jp'>子どもにも読めるように、ひらがなで書いた。</span>（為了讓小孩也能讀，我用平假名寫）<br>聞こえる、読める是能力或狀態，第二句的主角還不是同一個人（寫的是我，讀的是小孩），所以不能用ために。</div><div class='gd-warn'>判斷小訣竅：前面是「自己主動去做的動作」，用ために；前面是「できる、わかる、聞こえる、見える」這種能力、狀態，或前後主角不一樣，用ように。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>目的的部分接著看「〜ように」（n3-54）。原因的部分可以比較「〜おかげで」（多虧～，好結果）和「〜せいで」（都怪～，壞結果），它們會把說話的人的感謝或抱怨也講出來。</div>",
  "n3-54": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ように」就是中文的<b>「好讓～」「以免～」</b>。前半句講你希望出現的結果，後半句講你為了這個結果做了什麼：<span class='gd-jp'>後ろの人にも聞こえるように、マイクを使った。</span>（好讓後面的人也聽得到，用了麥克風）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>希望「能～、會～」：辭書形＋ように<br><span class='gd-pair'><span class='gd-jp'>聞こえる</span> → <span class='gd-jp'>聞こえるように</span></span><br><span class='gd-pair'><span class='gd-jp'>話す</span> → 先變成「能說」<span class='gd-jp'>話せる</span> → <span class='gd-jp'>話せるように</span></span><br>希望「不要～」：ない形＋ように<br><span class='gd-pair'><span class='gd-jp'>忘れる</span> → <span class='gd-jp'>忘れない</span> → <span class='gd-jp'>忘れないように</span></span></div><div class='gd-h'>前面通常放這幾種</div><div class='gd-sec'>重點是：ように前面放的，是<b>你沒辦法直接決定的結果</b>，只能努力讓它發生。常見以下幾種：</div><div class='gd-sec'><span class='gd-tag'>能～</span>前面是「會～、能～」的說法（可能形）。</div><div class='gd-ex-line'>・<span class='gd-jp'>字幕なしでドラマが見られるように、毎日日本語を聞いています。</span>（為了不靠字幕也能看懂日劇，我每天聽日文）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語で話せるように、毎日練習している。</span>（為了能用日文聊天，我每天練習）</div><div class='gd-sec'><span class='gd-tag'>自然會發生的事</span>不是你想做就做得到的動作，像<span class='gd-jp'>聞こえる</span>（聽得到）、<span class='gd-jp'>間に合う</span>（趕得上）、<span class='gd-jp'>治る</span>（病好）。</div><div class='gd-ex-line'>・<span class='gd-jp'>風邪が早く治るように、薬を飲んで寝た。</span>（為了讓感冒快點好，吃了藥就睡）</div><div class='gd-ex-line'>・<span class='gd-jp'>最終便に間に合うように、早めに空港へ向かった。</span>（為了趕上末班飛機，提早出發去機場）</div><div class='gd-sec'><span class='gd-tag'>不要～</span>ない形＋ように＝以免～。這時候就算是自己能控制的動作也可以用。</div><div class='gd-ex-line'>・<span class='gd-jp'>忘れないように、メモしておこう。</span>（免得忘記，先記下來吧）</div><div class='gd-ex-line'>・<span class='gd-jp'>遅れないように、早めに家を出た。</span>（為了不遲到，提早出門）</div><div class='gd-h'>補充：前後的主角可以不一樣</div><div class='gd-sec'>這不是另一種用法，而是ように的一個特色：前半句的人可以跟後半句不同。下面這句，「懂」的是小孩，「說明」的是我。</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもにも分かるように、簡単な言葉で説明した。</span>（好讓小孩也聽得懂，我用簡單的字來說明）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・自己能決定要不要做的動作，<b>肯定形</b>不能直接接ように：<br>× 日本語を勉強するように、日本へ来た。<br>○ <span class='gd-jp'>日本語を勉強するために、日本へ来た。</span>（為了學日文來日本）<br>・名詞後面加「のように」是「像～一樣」，跟這裡的「為了」無關：<span class='gd-jp'>子どものように笑う</span>（像小孩一樣笑）。<br>・<span class='gd-jp'>ように</span>後面接一個新的動作；<span class='gd-jp'>ようにする</span>是「我盡量～」，別混在一起：<span class='gd-jp'>忘れないように、メモする</span>（為了不忘記，記下來）vs <span class='gd-jp'>忘れないようにする</span>（我會盡量不忘記）。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是存錢去留學：<br><span class='gd-jp'>留学するために、お金をためている。</span>（為了去留學，在存錢）<br><span class='gd-jp'>留学できるように、お金をためている。</span>（為了能去留學，在存錢）<br><b>ために</b>前面放<b>自己決定要做的事</b>，「留學」是目標本身；<b>ように</b>前面放<b>能不能、會不會</b>，「能去留學」要看錢夠不夠。<br>另外，ために前後要是同一個人，ように可以不同人；ために可以直接接名詞（<span class='gd-jp'>健康のために</span>），ように不行。</div><div class='gd-warn'>判斷小訣竅：前面的動作你自己說了算，用ために；前面是「能～」「不要～」或要靠運氣、靠別人，用ように。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>「〜ようにと」用來帶出祈求、交代的內容，例如<span class='gd-jp'>合格できるようにと祈った</span>（祈求能考上）。也可以回頭比較「〜ようにする」和「〜ようになる」。</div>",
  "n3-55": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ようにと」用來<b>轉述別人交代的話</b>，就像中文的「老師叫我們要準時」「醫生交代我少吃鹽」。你不是一字不差地重複對方原話，而是把「他要我做什麼」的重點講出來。後面的「と」就像中文的引號，表示前面是交代的內容。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>要對方做的事：辭書形＋ようにと　<span class='gd-pair'><span class='gd-jp'>守る</span> → <span class='gd-jp'>守るようにと</span></span><br>要對方別做的事：ない形＋ようにと　<span class='gd-pair'><span class='gd-jp'>遅れない</span> → <span class='gd-jp'>遅れないようにと</span></span><br>後面接「傳話」類的動詞：<span class='gd-jp'>言う</span>、<span class='gd-jp'>伝える</span>、<span class='gd-jp'>注意する</span>、<span class='gd-jp'>頼む</span>，還有表示祈求的<span class='gd-jp'>祈る</span>、<span class='gd-jp'>願う</span>。</div><div class='gd-sec'>口語裡「と」常常省略，說成「〜ように言われた」，意思一樣。有「と」的話，比較強調「這是對方交代的內容」。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>被交代</span>「〜ようにと言われた」，別人叫我要做某件事，日常最常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>母に早く帰るようにと言われた。</span>（媽媽叫我早點回家）</div><div class='gd-ex-line'>・<span class='gd-jp'>医者にお酒を飲まないようにと言われた。</span>（醫生叫我不要喝酒）</div><div class='gd-sec'><span class='gd-tag'>請人轉告</span>「〜ようにと伝えてください」，請你幫忙傳話給第三個人。</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんに、明日は8時に来るようにと伝えてください。</span>（請轉告田中先生，明天8點來）</div><div class='gd-sec'><span class='gd-tag'>祈求</span>「〜ようにと祈る」，希望某件事能實現。</div><div class='gd-ex-line'>・<span class='gd-jp'>試験に合格できるようにと祈った。</span>（我祈求能考上）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・ように前面的動作，是<b>被交代的那個人</b>要做的，不是下指示的那個人。例如<span class='gd-jp'>母に早く帰るように言われた</span>，要早點回家的是我，不是媽媽。<br>・交代內容要用辭書形或ない形，不要用た形：說<span class='gd-jp'>帰るように言われた</span>，不是「帰ったように言われた」。用「言う」「注意する」這類動詞時，ように前面也不要放ます形。<br>・「ように言う」帶有<b>下指示</b>的味道，適合上對下或對平輩。要拜託老師、主管做事，用「ように言った」聽起來像在命令對方，這時改說「〜てくださいとお願いした」比較得體。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>「」と言った</b>＝照原話直接引用：<span class='gd-jp'>先生は「時間を守りなさい」と言った。</span>（老師說：「要守時！」）<br><b>ようにと言った</b>＝把重點轉述出來：<span class='gd-jp'>先生は時間を守るようにと言った。</span>（老師叫我們要守時）<br>原話的「〜なさい」「〜てください」，轉述時就變成「〜ように」。</div><div class='gd-sec'><b>ように（為了）</b>＝自己為了某個目的去做某件事：<span class='gd-jp'>忘れないようにメモした。</span>（為了不忘記，我寫了筆記）<br><b>ようにと（交代）</b>＝別人叫我做某件事：<span class='gd-jp'>忘れないようにと言われた。</span>（有人叫我不要忘記）</div><div class='gd-warn'>判斷小訣竅：ように後面接「言う、伝える、注意する、頼む」這類傳話的動詞，就是「交代」；後面接自己做的動作，就是「為了」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>把被交代的事變成自己的習慣，就是「〜ようにしている」：<span class='gd-jp'>医者に言われてから、塩分を控えるようにしている。</span>（被醫生提醒之後，我都盡量少吃鹽）</div>",
  "n3-56": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ことから」就是<b>「由於～這一點，所以～」</b>。很像導遊在介紹：「這座山因為長得像鍋子，所以叫鍋山」；也像偵探在推理：「從窗戶破了這點來看，是遭小偷了」。前面放一個<b>看得到的事實</b>，後面講從這個事實得到的<b>名字</b>或<b>結論</b>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>名字的由來</span>說明為什麼叫這個名字、為什麼被這樣稱呼。後面常接「<span class='gd-jp'>〜と呼ばれる</span>」「<span class='gd-jp'>〜という名前がついた</span>」。</div><div class='gd-ex-line'>・<span class='gd-jp'>山の形が鍋に似ていることから、「鍋山」という名前がついた。</span>（因為山的形狀像鍋子，所以取名叫「鍋山」）</div><div class='gd-ex-line'>・<span class='gd-jp'>いつも笑顔でいることから、彼は「太陽」と呼ばれている。</span>（他因為總是笑咪咪的，被大家叫做「太陽」）</div><div class='gd-sec'><span class='gd-tag'>判斷的根據</span>從某個線索推出結論。後面常接「<span class='gd-jp'>〜と分かる</span>」「<span class='gd-jp'>〜と考えられる</span>」。</div><div class='gd-ex-line'>・<span class='gd-jp'>窓が割れていることから、泥棒に入られたと分かった。</span>（從窗戶破了這點，知道是被小偷闖進來了）</div><div class='gd-ex-line'>・<span class='gd-jp'>道がぬれていることから、夜の間に雨が降ったと考えられる。</span>（從路面是濕的來看，應該是晚上下過雨）</div><div class='gd-sec'><span class='gd-tag'>交代背景</span>在介紹、說明的文章裡，講一件事是怎麼來的。</div><div class='gd-ex-line'>・<span class='gd-jp'>この地域は温泉が湧いていることから、観光地として知られている。</span>（由於這個地區有溫泉湧出，所以是有名的觀光地）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞、い形容詞</b>：直接接普通形（就是不加ます、です的說法），現在、過去、否定都可以。<br><span class='gd-pair'><span class='gd-jp'>似ている</span> → <span class='gd-jp'>似ていることから</span></span><span class='gd-pair'><span class='gd-jp'>割れた</span> → <span class='gd-jp'>割れたことから</span></span><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いことから</span></span><br><b>な形容詞</b>：留下「な」，或改成「である」。<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなことから</span></span><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かであることから</span></span><br><b>名詞</b>：後面加「である」。<br><span class='gd-pair'><span class='gd-jp'>港町</span> → <span class='gd-jp'>港町であることから</span></span></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞後面要用<b>である</b>：是<span class='gd-jp'>港町であることから</span>，不是「港町だことから」，也不是「港町のことから」。<br>・這是<b>書面、正式</b>的說法，常出現在新聞、旅遊導覽、說明文。跟朋友聊天說「〜ことから」會很生硬，平常講「から」「ので」就好。<br>・後面只能放<b>事實、名字、判斷</b>，不能接「～吧」「請～」「給我～」這種邀約、請求、命令。<br>・前面的理由要是<b>大家都看得到、可以確認的事實</b>，不適合放自己的心情或藉口。想說「因為我很累，所以先回去了」，用「から」「ので」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「路是濕的」這件事：<br><b>から・ので</b>＝日常的「因為」，後面講什麼都可以，提醒、邀約、請求都行。</div><div class='gd-ex-line'>・<span class='gd-jp'>道がぬれているから、気をつけてね。</span>（路很濕，要小心喔）</div><div class='gd-sec'><b>ことから</b>＝「從這個事實推出結論」，後面只能是判斷或名字。</div><div class='gd-ex-line'>・<span class='gd-jp'>道がぬれていることから、雨が降ったと分かる。</span>（從路是濕的，可以知道下過雨）</div><div class='gd-sec'>如果說成「道がぬれていることから、気をつけてね」就不對，因為後面變成提醒對方了。</div><div class='gd-warn'>判斷小訣竅：中文能換成「從～這一點（可以看出／所以叫做）」，就用ことから；只是單純的「因為」，用から或ので。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>講名字由來時，後面幾乎都會接被動的「<span class='gd-jp'>〜と呼ばれている</span>」（被叫做～），可以順便複習「～（ら）れる（受身）」。</div>",
  "n3-57": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜たびに」就是中文的<b>「每次～就～」</b>。前面那件事只要一發生，後面那件事就跟著發生，幾乎沒有例外。像「每次聽到這首歌就想哭」「每次出差都買伴手禮」，用的就是它。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>每次都有的心情、反應</span>碰到某件事，心裡就會冒出同樣的感覺。</div><div class='gd-ex-line'>・<span class='gd-jp'>この写真を見るたびに、学生時代を思い出す。</span>（每次看到這張照片，就會想起學生時代）</div><div class='gd-ex-line'>・<span class='gd-jp'>この歌を聞くたびに、泣いてしまう。</span>（每次聽到這首歌都會哭）</div><div class='gd-sec'><span class='gd-tag'>每次都會做的事</span>某件事一發生，你就固定做某個動作。</div><div class='gd-ex-line'>・<span class='gd-jp'>出張のたびにお土産を買って帰る。</span>（每次出差都會買伴手禮回來）</div><div class='gd-sec'><span class='gd-tag'>每次都看到變化</span>每碰一次面，就發現有東西不一樣了。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼に会うたびに、背が伸びている。</span>（每次見到他，他都又長高了）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：辭書形（就是字典裡查到的原本樣子）直接加たびに。<br><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会うたびに</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見るたびに</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来るたびに</span></span></div><div class='gd-sec'><b>名詞</b>：中間加「の」。<br><span class='gd-pair'><span class='gd-jp'>旅行</span> → <span class='gd-jp'>旅行のたびに</span></span><span class='gd-pair'><span class='gd-jp'>試験</span> → <span class='gd-jp'>試験のたびに</span></span><br>前面放的名詞要是<b>一件會重複發生的事</b>，像<span class='gd-jp'>出張</span>、<span class='gd-jp'>旅行</span>、<span class='gd-jp'>試験</span>、<span class='gd-jp'>引っ越し</span>。<span class='gd-jp'>雨のたびに</span>和<span class='gd-jp'>雨が降るたびに</span>兩種說法也都可以。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・就算講的是過去，<b>前面還是用辭書形</b>，過去的「た」放在句尾就好：<span class='gd-jp'>子供のころ、祖母の家に行くたびに、お菓子をもらった。</span>（小時候每次去奶奶家，都會拿到點心）不要說成「行ったたびに」。<br>・前面一定要是<b>會發生很多次</b>的事。人生只發生一次的事（出生、大學畢業）就不能用。<br>・名詞前面接的要是「一件事」。<span class='gd-jp'>本</span>、<span class='gd-jp'>先生</span>這種不是事情的名詞就不行，要改成動詞：<span class='gd-jp'>本を読むたびに</span>（每次讀書）。<br>・每天理所當然的例行公事，例如刷牙、吃早餐，日本人通常直接說<span class='gd-jp'>毎朝</span>、<span class='gd-jp'>いつも</span>。用たびに會像在強調一件特別的事，聽起來怪怪的。<br>・たびに也常寫成漢字<span class='gd-jp'>度に</span>，念法一樣，看到別以為是別的文法。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「去日本」這件事：<br><span class='gd-jp'>日本へ行くたびに、ラーメンを食べる。</span>（每次去日本都會吃拉麵）<br>　→ 強調「每一次都這樣，沒漏過」。<br><span class='gd-jp'>日本へ行くときは、いつもラーメンを食べる。</span>（去日本的時候，總是會吃拉麵）<br>　→ 意思幾乎一樣，口氣比較平淡、日常。<br><span class='gd-jp'>二年ごとに日本へ行く。</span>（每隔兩年去一次日本）<br>　→ <b>ごとに</b>前面可以放數字，講「每隔多久、每多少個」。たびに不能這樣用，不能說「二年のたびに」。</div><div class='gd-warn'>判斷小訣竅：前面是<b>數字或時間間隔</b>就用ごとに；前面是<b>一件事</b>，想說「每次～就～」就用たびに，想講得輕鬆一點也可以用「ときはいつも」。</div>",
  "n3-58": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜を中心に」就是中文的<b>「以～為中心」「以～為主」「主要是～」</b>。把某個東西當成核心，事情圍著它展開；或是說某件事的重點、主要範圍在哪裡。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>地點</span>以某個地方為中心，往外擴展、分布。</div><div class='gd-ex-line'>・<span class='gd-jp'>駅を中心に店が並んでいる。</span>（以車站為中心，四周都是店家）</div><div class='gd-ex-line'>・<span class='gd-jp'>九州を中心に大雨が降った。</span>（大雨主要下在九州一帶）</div><div class='gd-sec'><span class='gd-tag'>人</span>以某個人為核心，大家圍著他行動。</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんを中心に、新しいチームができた。</span>（以田中先生為核心，組了一個新團隊）</div><div class='gd-sec'><span class='gd-tag'>主要範圍・重點</span>「主要是～」，但不代表只有它。</div><div class='gd-ex-line'>・<span class='gd-jp'>このアニメは子どもを中心に人気がある。</span>（這部動畫主要在小孩之間很受歡迎）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は文法を中心に復習しよう。</span>（今天主要複習文法吧）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面一定是<b>名詞</b>，後面接動作或狀態：<br><span class='gd-pair'><span class='gd-jp'>駅</span> → <span class='gd-jp'>駅を中心に</span></span>　也可以說<span class='gd-jp'>駅を中心にして</span>、<span class='gd-jp'>駅を中心として</span>，意思一樣。<br>後面要直接接名詞時，改成<b>を中心とした</b>（或<span class='gd-jp'>を中心とする</span>）：</div><div class='gd-ex-line'>・<span class='gd-jp'>野菜を中心とした食事</span>（以蔬菜為主的飲食）</div><div class='gd-ex-line'>・<span class='gd-jp'>東京を中心とした関東地方</span>（以東京為中心的關東地區）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・助詞是<b>を</b>：<span class='gd-jp'>駅を中心に</span>，不是「駅に中心に」「駅が中心に」。<br>・前面不能直接放動詞，要放名詞。想說「以學習為主」，就用<span class='gd-jp'>勉強を中心に</span>。<br>・「を中心に」跟「<b>の</b>中心に」不一樣。<span class='gd-jp'>公園の中心に噴水がある。</span>是「公園正中間有一座噴水池」，只是在講位置，不是「以～為中心展開」。<br>・「以～為主」不等於「只有」：<span class='gd-jp'>若者を中心に人気だ</span>是年輕人最多，但其他年齡層也有人喜歡。<br>・要修飾後面的名詞時，別寫成「野菜を中心にの食事」，要用<span class='gd-jp'>野菜を中心とした食事</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>をはじめ（として）</b>＝「以A為首，還有B、C…」，是<b>舉一個代表</b>，重點在後面還有其他的。<br><b>を中心に</b>＝「主要是A」，重點在<b>A是核心、比重最大</b>。<br>同一個情境比比看：</div><div class='gd-ex-line'>・<span class='gd-jp'>このお菓子は東京を中心に人気がある。</span>（這款點心主要在東京受歡迎）</div><div class='gd-ex-line'>・<span class='gd-jp'>このお菓子は東京をはじめ、大阪や福岡でも人気がある。</span>（這款點心在東京，還有大阪、福岡等地都很受歡迎）</div><div class='gd-warn'>判斷小訣竅：想說「主要在A、圍繞著A」用を中心に；想說「A是代表，B、C也一樣」用をはじめ。</div>",
  "n3-59": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜を通じて」「〜を通して」有兩個意思。第一個是<b>「透過～」</b>：中間經過某個人、某個管道，事情才成立，像「透過朋友認識」「透過網路聯絡」。第二個是<b>「整個～都」</b>：前面放一段時間，表示從頭到尾都是這樣，像中文的「一年到頭」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>很簡單，名詞後面直接接：<br><span class='gd-pair'><span class='gd-jp'>友達</span> → <span class='gd-jp'>友達を通じて</span></span><span class='gd-pair'><span class='gd-jp'>一年</span> → <span class='gd-jp'>一年を通して</span></span><br>要放在名詞前面修飾名詞時，中間加「の」：<span class='gd-jp'>ボランティアを通しての出会い</span>（透過當志工認識的緣分）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>透過人或管道</span>中間有人幫你牽線，或透過網路、電話、媒體這種管道。</div><div class='gd-ex-line'>・<span class='gd-jp'>友達を通じて、今の彼女と知り合った。</span>（透過朋友認識了現在的女朋友）</div><div class='gd-ex-line'>・<span class='gd-jp'>インターネットを通じて、世界中の人と話せる。</span>（透過網路，可以跟世界各地的人聊天）</div><div class='gd-sec'><span class='gd-tag'>透過經驗</span>經過某段經歷，學到或感受到什麼。</div><div class='gd-ex-line'>・<span class='gd-jp'>アルバイトを通して、敬語の使い方を覚えた。</span>（透過打工，學會了敬語的用法）</div><div class='gd-sec'><span class='gd-tag'>整段時間</span>前面放「一年」「一生」這種一段時間，表示整段期間都這樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>この島は一年を通して暖かい。</span>（這座島一年到頭都很溫暖）</div><div class='gd-ex-line'>・<span class='gd-jp'>祖父は一生を通じて、同じ会社で働いた。</span>（爺爺一輩子都在同一家公司工作）</div><div class='gd-h'>を通じて跟を通して差在哪</div><div class='gd-sec'>大部分情況<b>兩個都可以互換</b>，意思差不多，不用太緊張。硬要分的話：<br><b>を通じて</b>比較常用在網路、電話、人脈這種「管道」。<br><b>を通して</b>比較有「自己刻意透過、親身經歷」的感覺，所以講經驗、練習、實驗時很常用它。<br>拿不準的時候，選哪個都不會錯得離譜。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>交通工具、一般工具不要用它</b>：「坐公車去」是<span class='gd-jp'>バスで行く</span>，「用剪刀剪」是<span class='gd-jp'>はさみで切る</span>。不能說バスを通して行く。を通じて是講「中間經過的人或管道」，不是手上拿的工具。<br>・中文的「通過考試」不是這個文法，要說<span class='gd-jp'>試験に合格する</span>。中文的「通過」跟日文的を通して長得像，意思不一樣。<br>・前面的助詞是<b>を</b>，不要寫成に。<br>・「整段時間」的用法，前面要放<b>一段期間</b>，例如一年、一生、四季。意思是「整段期間都」，不是「經過那段時間之後」。<br>・語氣偏正式，新聞、文章、自我介紹很常見。跟朋友聊天講「朋友介紹的」，口語常說<span class='gd-jp'>友達の紹介で</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「傳話給老師」：<br><span class='gd-jp'>メールで先生に伝えた。</span>（用 email 告訴老師）：<b>で</b>＝用什麼工具、方式，日常最普通。<br><span class='gd-jp'>先輩を通じて先生に伝えた。</span>（透過學長轉告老師）：<b>を通じて</b>＝中間有人或管道幫你傳過去。<br><br>另一個容易混的是<b>によって</b>，它講的是「靠什麼方法做到」或「因為什麼造成」：<br><span class='gd-jp'>この研究によって、病気の原因が分かった。</span>（靠這項研究，找出了病因）<br>如果是透過朋友牽線認識人，要說<span class='gd-jp'>友達を通じて知り合った</span>，不說友達によって知り合った。</div><div class='gd-warn'>判斷小訣竅：中間有個「人、管道、經歷」在牽線，用を通じて／を通して；單純用工具、坐交通工具，用で；講方法或原因，用によって。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同樣是「名詞＋を＋〜」的格式，可以接著看<span class='gd-jp'>〜を中心に</span>（以～為中心）和<span class='gd-jp'>〜をはじめ</span>（以～為首），這幾個常常在同一篇文章裡一起出現。</div>",
  "n3-60": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜に基づいて」就是中文的<b>「根據～」「依照～」</b>，表示做一件事時拿什麼當依據。電影片頭常寫「本片根據真實事件改編」，日文就是<span class='gd-jp'>この映画は実話に基づいている。</span><br>前面放的是「憑什麼這樣做」的依據，例如事實、資料、規定、經驗。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>後面接動作</span>名詞＋に基づいて＋動詞</div><div class='gd-ex-line'>・<span class='gd-jp'>規則に基づいて判断します。</span>（依照規定來判斷）</div><div class='gd-ex-line'>・<span class='gd-jp'>データに基づいて計画を立てた。</span>（根據數據訂了計畫）</div><div class='gd-sec'><span class='gd-tag'>後面接名詞</span>名詞＋に基づく／に基づいた＋名詞，兩種都很常見。</div><div class='gd-ex-line'>・<span class='gd-jp'>調査結果に基づく報告書</span>（根據調查結果寫的報告）</div><div class='gd-ex-line'>・<span class='gd-jp'>経験に基づいたアドバイス</span>（根據經驗給的建議）</div><div class='gd-sec'><span class='gd-tag'>放句尾</span>用<span class='gd-jp'>〜に基づいている</span>，表示「是根據～的」。</div><div class='gd-ex-line'>・<span class='gd-jp'>この話は事実に基づいています。</span>（這個故事是根據事實寫的）</div><div class='gd-sec'>新聞、公文裡還會看到<span class='gd-jp'>に基づき</span>，意思跟に基づいて一樣，只是更書面。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面要放<b>依據</b>，不能直接放人。「老師說的」要講<span class='gd-jp'>先生の話に基づいて</span>，不能說「先生に基づいて」。<br>・後面接名詞時要用<b>基づく／基づいた</b>，不要寫成「データに基づいて計画」。<br>・念<b>もとづいて</b>，假名是「づ」不是「ず」，打字要打 motodu。<br>・語氣偏正式，常出現在報告、新聞、工作場合。跟朋友閒聊比較少用。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣拿「資料」當話題，三種說法意思不同：<br><span class='gd-jp'>データについて説明します。</span>（我來說明<b>這份資料本身</b>）<br><span class='gd-jp'>データに基づいて説明します。</span>（我<b>拿資料當根據</b>來說明，例如說明計畫或結論）<br><span class='gd-jp'>データによると、売り上げが増えています。</span>（<b>根據資料顯示</b>，銷售額在增加）<br>「によると」是在交代消息來源，後面接「資料說了什麼」，不能接自己做的動作。</div><div class='gd-warn'>判斷小訣竅：中文是「關於～」用について；「根據～顯示／聽說」用によると；「以～為根據去做、去判斷」用に基づいて。</div>",
  "n3-62": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「<span class='gd-jp'>〜ものだから</span>」「<span class='gd-jp'>〜もので</span>」就像中文的<b>「因為～嘛，所以才…」</b>。遲到時跟主管說「不好意思，因為電車誤點嘛…」，那種<b>帶一點辯解、希望對方諒解</b>的口氣，就是它。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>道歉時解釋</span>做錯事、給人添麻煩時，補上「我不是故意的」的理由。</div><div class='gd-ex-line'>・<span class='gd-jp'>すみません、電車が止まっていたものですから。</span>（對不起，因為電車停駛了…）</div><div class='gd-ex-line'>・<span class='gd-jp'>寝坊したもので、遅れてしまいました。</span>（因為睡過頭，所以遲到了）</div><div class='gd-sec'>第一句「<span class='gd-jp'>電車が止まっていたものですから。</span>」是把句子停在「<span class='gd-jp'>ものですから。</span>」，只補上理由，後半句省略不講。這在道歉的時候很常聽到。</div><div class='gd-sec'><span class='gd-tag'>說明自己的狀況</span>婉轉解釋自己為什麼不能做、為什麼這樣做。</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもがまだ小さいもので、夜はあまり出かけられないんです。</span>（因為小孩還小，晚上不太能出門）</div><div class='gd-sec'><span class='gd-tag'>太～了，所以就…</span>說明自己忍不住做了某件事。</div><div class='gd-ex-line'>・<span class='gd-jp'>あまりにおいしかったものだから、全部食べちゃった。</span>（因為實在太好吃，就全部吃光了）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：普通形直接接　<span class='gd-pair'><span class='gd-jp'>寝坊した</span> → <span class='gd-jp'>寝坊したものだから</span></span><br><b>い形容詞</b>：直接接　<span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>忙しいものだから</span></span><br><b>な形容詞</b>：要加「な」　<span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなものだから</span></span><br><b>名詞</b>：也要加「な」　<span class='gd-pair'><span class='gd-jp'>初めて</span> → <span class='gd-jp'>初めてなもので</span></span><br>講話時常縮成<span class='gd-jp'>もんだから</span>、<span class='gd-jp'>もんで</span>；對長輩、客人說<span class='gd-jp'>ものですから</span>。<span class='gd-jp'>もので</span>本身口氣就比較客氣，正式場合也很常用。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・な形容詞、名詞後面是「な」，不是「だ」：說<span class='gd-jp'>静かなものだから</span>，不說「静かだものだから」。<br>・後半句<b>不能接命令、請求、邀約、自己的打算</b>。<span class='gd-jp'>雨が降っているものだから、傘を持っていってください。</span>是錯的，要改成<span class='gd-jp'>雨が降っているから、傘を持っていってください。</span>（在下雨，帶傘去吧）<br>・它是講<b>自己的情況、私人的理由</b>，新聞、報告這種客觀說明原因的地方不用它，用<span class='gd-jp'>ので</span>、<span class='gd-jp'>ため</span>。<br>・明明是自己的錯還一直用，聽起來會像在找藉口。真的理虧時，先好好道歉比較重要。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>から／ので</b>＝單純說明原因：<span class='gd-jp'>電車が遅れたので、遅刻しました。</span>（因為電車誤點，所以遲到了）<br><b>ものだから</b>＝說明原因，再加上「不是我故意的，請諒解」：<span class='gd-jp'>電車が遅れたものですから、遅刻してしまいました。</span>（因為電車誤點嘛，才遲到的…）<br>後半句是要大家做什麼，就只能用から／ので：<span class='gd-jp'>電車が遅れているから、タクシーで行こう。</span>（電車誤點，搭計程車去吧）</div><div class='gd-sec'><b>ものだ</b>（句尾）＝感嘆「本來就是這樣啊」，不是在講理由：<span class='gd-jp'>時間が経つのは早いものだ。</span>（時間過得真快啊）<br><b>ものだから</b>後面還有「から」或「で」，一定是在講<b>理由</b>。</div><div class='gd-warn'>判斷小訣竅：想要對方諒解、在解釋自己的情況，用ものだから／もので；後半是叫人做事或約人，改用から／ので；句子停在「ものだ。」是感嘆，不是理由。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>日常對話裡還有更短、更撒嬌的說法，句尾直接用<span class='gd-jp'>もん</span>：<span class='gd-jp'>だって、知らなかったんだもん。</span>（人家就不知道嘛）只對很熟的人講。</div>",
  "n3-63": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「<span class='gd-jp'>さえ</span>」就是中文的<b>「連～都…」</b>。它會故意挑一個<b>最基本、最理所當然</b>的例子來講，意思是「連這個都這樣了，其他的就更不用說」。像「忙到連吃飯的時間都沒有」，日文就說：<span class='gd-jp'>忙しくて、ご飯を食べる時間さえない。</span></div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>接名詞</span>名詞後面直接加<span class='gd-jp'>さえ</span>。原本的「<span class='gd-jp'>が</span>」「<span class='gd-jp'>を</span>」要拿掉，由<span class='gd-jp'>さえ</span>取代。<br><span class='gd-pair'><span class='gd-jp'>時間がない</span> → <span class='gd-jp'>時間さえない</span></span>（連時間都沒有）<br><span class='gd-pair'><span class='gd-jp'>自分の名前を書けない</span> → <span class='gd-jp'>自分の名前さえ書けない</span></span>（連自己的名字都不會寫）</div><div class='gd-sec'><span class='gd-tag'>其他助詞留著</span>「<span class='gd-jp'>に</span>」「<span class='gd-jp'>で</span>」「<span class='gd-jp'>と</span>」這些不用拿掉，<span class='gd-jp'>さえ</span>直接放在後面。<br><span class='gd-pair'><span class='gd-jp'>家族に話していない</span> → <span class='gd-jp'>家族にさえ話していない</span></span>（連家人都還沒說）</div><div class='gd-sec'><span class='gd-tag'>講「連某人都」</span>要強調「連這個人都～」的時候，很常說「<span class='gd-jp'>でさえ</span>」：<span class='gd-jp'>子供でさえ知っている。</span>（連小孩都知道）</div><div class='gd-sec'><span class='gd-tag'>接動詞</span>想說「連～都不～」，就把動詞的ます拿掉，加上<span class='gd-jp'>さえしない</span>。<br><span class='gd-pair'><span class='gd-jp'>見ます</span> → 把ます拿掉 → <span class='gd-jp'>見さえしない</span></span>（連看都不看）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は私の顔を見さえしなかった。</span>（他連看都沒看我一眼）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>後面接否定</span>這是最常見的用法：連最基本的事都沒有、都做不到。</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しくて、水を飲む時間さえなかった。</span>（忙到連喝水的時間都沒有）</div><div class='gd-ex-line'>・<span class='gd-jp'>足が痛くて、歩くことさえできない。</span>（腳痛到連走路都沒辦法）</div><div class='gd-sec'><span class='gd-tag'>後面接肯定</span>連最不可能的人都知道、都做得到，言下之意是「其他人更應該會」。</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなことは、子供でさえ知っている。</span>（那種事連小孩都知道）</div><div class='gd-ex-line'>・<span class='gd-jp'>この問題は、先生でさえ間違えた。</span>（這題連老師都答錯了）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・「<span class='gd-jp'>が</span>」「<span class='gd-jp'>を</span>」一定要拿掉：說成「時間がさえない」是錯的，要說<span class='gd-jp'>時間さえない</span>。但「<span class='gd-jp'>に</span>」「<span class='gd-jp'>で</span>」「<span class='gd-jp'>と</span>」要留著，所以是<span class='gd-jp'>家族にさえ</span>，不是家族さえ。<br>・<span class='gd-jp'>さえ</span>的語氣比較強，也比較正式。朋友聊天時，很多人直接用「<span class='gd-jp'>も</span>」：<span class='gd-jp'>時間もない</span>，意思差不多，只是「連這個都」的感覺沒那麼重。<br>・<span class='gd-jp'>さえ</span>單獨出現的時候是「連～都」，<b>不是「只要」</b>。很多人一看到<span class='gd-jp'>さえ</span>就翻成「只要」，但要翻成「只要」，後面一定要接條件的說法（請看下一段）。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講「時間」，後面接的東西不一樣，意思就差很多：<br><b>さえ</b>＝連～都：<span class='gd-jp'>最近は寝る時間さえない。</span>（最近連睡覺的時間都沒有）<br><b>さえ〜ば</b>＝只要～就：<span class='gd-jp'>時間さえあれば、旅行に行きたい。</span>（只要有時間，我就想去旅行）<br><b>さえ〜たら／なら</b>也是「只要～就」：<span class='gd-jp'>時間さえあったら、行けるのに。</span>（只要有時間，我就能去了啊）</div><div class='gd-warn'>判斷小訣竅：<span class='gd-jp'>さえ</span>後面如果接「如果～」的條件說法，就是「只要～就」。這種說法包括「〜ば」，也包括「〜たら」「〜なら」，例如<span class='gd-jp'>あれば</span>、<span class='gd-jp'>あったら</span>、<span class='gd-jp'>あるなら</span>。後面沒有這種條件說法，就是「連～都」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>接著學「<span class='gd-jp'>〜さえ〜ば</span>」（只要～就）：<span class='gd-jp'>この薬さえ飲めば、すぐ治りますよ。</span>（只要吃了這個藥，很快就會好喔）</div>",
  "n3-64": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜こそ」就像拿<b>螢光筆</b>把前面那個詞畫起來，意思是「<b>就是這個</b>」「<b>才是～</b>」「<b>這次一定～</b>」。<span class='gd-jp'>今年頑張る</span>只是「今年要加油」，<span class='gd-jp'>今年こそ頑張る</span>就變成「今年說什麼都要拚」，口氣強很多。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>這次一定</span>之前失敗過，這次下定決心。常跟<span class='gd-jp'>今年</span>、<span class='gd-jp'>明日</span>、<span class='gd-jp'>次</span>一起出現。</div><div class='gd-ex-line'>・<span class='gd-jp'>今年こそ合格するぞ。</span>（今年一定要考上！）</div><div class='gd-ex-line'>・<span class='gd-jp'>次こそ負けないよ。</span>（下次絕對不會輸）</div><div class='gd-sec'><span class='gd-tag'>我才要～</span>對方跟你道謝、道歉或說請多指教，你回「彼此彼此，我才是」。<span class='gd-jp'>こちらこそ</span>可以直接當一句話用，非常好用。</div><div class='gd-ex-line'>・<span class='gd-jp'>A：いつもありがとう。　B：こちらこそ。</span>（A：一直以來謝謝你。B：我才要謝謝你）</div><div class='gd-ex-line'>・<span class='gd-jp'>A：遅れてすみません。　B：いえ、こちらこそすみません。</span>（A：抱歉我遲到了。B：不會，我才不好意思）</div><div class='gd-sec'><span class='gd-tag'>正是這個</span>強調「不是別的，就是它」。</div><div class='gd-ex-line'>・<span class='gd-jp'>今こそ挑戦するときだ。</span>（現在正是挑戰的時候）</div><div class='gd-ex-line'>・<span class='gd-jp'>これこそ私が探していた本だ。</span>（這正是我一直在找的書）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>基本上是<b>名詞＋こそ</b>。原本句子裡如果有<span class='gd-jp'>は</span>或<span class='gd-jp'>が</span>，直接把它換成<span class='gd-jp'>こそ</span>：<br><span class='gd-pair'><span class='gd-jp'>今年は頑張る</span> → <span class='gd-jp'>今年こそ頑張る</span></span><br><span class='gd-pair'><span class='gd-jp'>これが大切だ</span> → <span class='gd-jp'>これこそ大切だ</span></span><br><span class='gd-jp'>を</span>一般也是拿掉，直接接<span class='gd-jp'>こそ</span>。<br>如果是<span class='gd-jp'>に</span>、<span class='gd-jp'>で</span>這類助詞，就留著，<span class='gd-jp'>こそ</span>接在它後面：</div><div class='gd-ex-line'>・<span class='gd-jp'>あなたにこそ見てほしい。</span>（我最希望來看的人就是你）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<span class='gd-jp'>は</span>・<span class='gd-jp'>が</span>不能放在<span class='gd-jp'>こそ</span>前面，像<span class='gd-jp'>今年はこそ</span>、<span class='gd-jp'>私がこそ</span>都是錯的，要先把它們拿掉。<span class='gd-jp'>を</span>也一樣，平常會拿掉。不過放在<span class='gd-jp'>こそ</span>後面可以，例如<span class='gd-jp'>今年こそは</span>、<span class='gd-jp'>これこそが</span>都是常見的說法。<br>・<span class='gd-jp'>こちらこそ</span>很有禮貌，可是換成<span class='gd-jp'>あなたこそ</span>、<span class='gd-jp'>お前こそ</span>，常常是吵架時在反嗆：<span class='gd-jp'>お前こそ何してるんだよ。</span>（你自己才是在幹嘛啦）。對長輩不要亂用。<br>・<span class='gd-jp'>こそ</span>口氣很重，是用來畫重點的。每個詞都加，就跟整頁都畫螢光筆一樣，反而沒有重點。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講今年的考試：<br><span class='gd-jp'>今年は合格したい。</span>（今年想考過）：平平地說，沒有特別的情緒。<br><span class='gd-jp'>今年こそ合格したい。</span>（今年一定要考過）：之前沒考過，這次下定決心。<br><span class='gd-jp'>こそ</span>常跟<span class='gd-jp'>さえ</span>一起學，但兩個方向完全相反：<span class='gd-jp'>さえ</span>是「連～都」，舉出一個極端的例子，表示其他的就更不用說了，肯定、否定都能用，例如<span class='gd-jp'>簡単な問題さえできなかった。</span>（連簡單的題目都不會）、<span class='gd-jp'>子供でさえ知っている。</span>（連小孩都知道）。<span class='gd-jp'>こそ</span>則是把那個詞捧成主角。</div><div class='gd-warn'>判斷小訣竅：想說「就是它」「這次一定」「我才是」用こそ；想說「連～都」用さえ；只是平常講講就用は。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'><span class='gd-jp'>からこそ</span>＝「正因為～才」，強調理由：<span class='gd-jp'>好きだからこそ、厳しく言うんだ。</span>（正因為在乎你，我才講得這麼嚴）。<span class='gd-jp'>だからこそ</span>也很常聽到，意思是「正因為這樣」。</div>",
  "n3-65": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜そうだ」就是中文的<b>「看起來好像～」</b>。蛋糕還沒吃，光看就覺得「看起來好好吃」，日文就說<span class='gd-jp'>おいしそう</span>。重點是<b>看到眼前的樣子，直覺猜出來</b>的，還沒真正確認。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>看外表猜</span>形容詞加そう，表示「看起來～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>このケーキ、おいしそう。</span>（這個蛋糕看起來好好吃）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さん、今日は元気そうですね。</span>（田中先生今天看起來很有精神耶）</div><div class='gd-sec'><span class='gd-tag'>快要發生</span>動詞加そう，多半是「好像快要～了」。</div><div class='gd-ex-line'>・<span class='gd-jp'>空が暗くなってきた。雨が降りそうだ。</span>（天色變暗了，好像快下雨了）</div><div class='gd-ex-line'>・<span class='gd-jp'>シャツのボタンが取れそう。</span>（襯衫的扣子好像快掉了）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>い形容詞</b>：把最後的「い」拿掉，加そう。<br><span class='gd-pair'><span class='gd-jp'>おいしい</span> → い拿掉 → <span class='gd-jp'>おいしそう</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高そう</span></span></div><div class='gd-sec'><b>な形容詞</b>：直接加そう。<br><span class='gd-pair'><span class='gd-jp'>元気</span> → <span class='gd-jp'>元気そう</span></span><span class='gd-pair'><span class='gd-jp'>暇</span> → <span class='gd-jp'>暇そう</span></span></div><div class='gd-sec'><b>動詞</b>：先變ます形，把ます拿掉，加そう。<br><span class='gd-pair'><span class='gd-jp'>降ります</span> → ます拿掉 → <span class='gd-jp'>降りそう</span></span><span class='gd-pair'><span class='gd-jp'>落ちます</span> → <span class='gd-jp'>落ちそう</span></span></div><div class='gd-sec'><b>兩個特例直接背</b>：<span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よさそう</span></span><span class='gd-pair'><span class='gd-jp'>ない</span> → <span class='gd-jp'>なさそう</span></span></div><div class='gd-sec'>後面要接名詞用<b>そうな</b>，接動詞用<b>そうに</b>：</div><div class='gd-ex-line'>・<span class='gd-jp'>高そうな時計ですね。</span>（看起來很貴的手錶耶）</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもたちが楽しそうに遊んでいる。</span>（孩子們玩得很開心的樣子）</div><div class='gd-h'>想說「看起來不～」</div><div class='gd-sec'>形容詞：<span class='gd-jp'>おいしくなさそう</span>（看起來不好吃）、<span class='gd-jp'>暇じゃなさそう</span>（看起來不閒）<br>動詞：用「そうにない」或「そうもない」。</div><div class='gd-ex-line'>・<span class='gd-jp'>この仕事は今日中に終わりそうにない。</span>（這工作看來今天做不完）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<span class='gd-jp'>いい</span>不能說「いそう」，要說<span class='gd-jp'>よさそう</span>：<span class='gd-jp'>天気がよさそうだ</span>（天氣看起來不錯）。<br>・<b>名詞不能直接加這個そう</b>：×学生そうだ。想說「看起來像學生」要用<span class='gd-jp'>学生みたいだ</span>。<br>・一看就知道、不用猜的事不用そう：紅色的花直接說<span class='gd-jp'>赤い</span>，不說「赤そう」。<br>・<span class='gd-jp'>かわいそう</span>是「好可憐」，不是「看起來很可愛」。覺得可愛直接說<span class='gd-jp'>かわいい</span>。<br>・動詞的そう常常是「快要～」：<span class='gd-jp'>泣きそう</span>是「快哭了」，不是「好像在哭」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>「聽說」的そうだ</b>（下一個文法）長得幾乎一樣，但意思完全不同。同一件事比比看：<br><span class='gd-jp'>雨が降りそうだ。</span>（看天空，好像快下雨了）<br><span class='gd-jp'>雨が降るそうだ。</span>（聽氣象說會下雨）<br><span class='gd-jp'>おいしそうだ。</span>（看起來好吃）<br><span class='gd-jp'>おいしいそうだ。</span>（聽說很好吃）<br><span class='gd-jp'>元気そうだ。</span>（看起來很有精神）<br><span class='gd-jp'>元気だそうだ。</span>（聽說很有精神）<br>名詞只有「聽說」版：<span class='gd-jp'>学生だそうだ。</span>（聽說是學生）</div><div class='gd-warn'>判斷小訣竅：<br>・動詞、い形容詞：そう前面被切短了（<span class='gd-jp'>降り</span>、<span class='gd-jp'>おいし</span>）＝看起來；前面是完整的形（<span class='gd-jp'>降る</span>、<span class='gd-jp'>おいしい</span>）＝聽說。<br>・な形容詞、名詞：看有沒有「だ」。<span class='gd-jp'>元気そうだ</span>＝看起來；<span class='gd-jp'>元気だそうだ</span>＝聽說；<span class='gd-jp'>学生だそうだ</span>＝聽說是學生。</div><div class='gd-sec'>另外，<b>ようだ・みたいだ</b>也是「好像」，但比較像綜合線索後下的判斷；そう是<b>看一眼的第一印象</b>。看到蛋糕說<span class='gd-jp'>おいしそう</span>；看大家吃得很開心才說<span class='gd-jp'>おいしいみたい</span>。</div>",
  "n3-66": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜そうだ」就是中文的<b>「聽說～」「據說～」</b>。你從新聞、朋友、氣象預報那裡聽到一件事，要轉告別人時，就在句子最後加上そうだ。重點是：<b>這件事不是你自己看到或猜的，是別人說的</b>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>轉述聽來的消息</span>把別人說的事情原封不動轉告出去。</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは来月結婚するそうです。</span>（聽說田中先生下個月要結婚）</div><div class='gd-ex-line'>・<span class='gd-jp'>部長は今日、会社に来ないそうです。</span>（聽說部長今天不進公司）</div><div class='gd-sec'><span class='gd-tag'>交代消息來源</span>前面常加「<span class='gd-jp'>〜によると</span>」「<span class='gd-jp'>〜の話では</span>」，說清楚是從哪裡聽來的。</div><div class='gd-ex-line'>・<span class='gd-jp'>天気予報によると、明日は雨だそうだ。</span>（根據氣象預報，明天會下雨）</div><div class='gd-ex-line'>・<span class='gd-jp'>先生の話では、来週テストがあるそうです。</span>（聽老師說，下禮拜有考試）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>先把要轉述的內容變成<b>普通形</b>（就是不加ます、です的說法），後面再接そうだ。是現在還是過去、肯定還是否定，都在前面那句裡面變。<br><b>動詞</b>：<span class='gd-pair'><span class='gd-jp'>降る</span> → <span class='gd-jp'>降るそうだ</span></span><span class='gd-pair'><span class='gd-jp'>降った</span> → <span class='gd-jp'>降ったそうだ</span></span><span class='gd-pair'><span class='gd-jp'>降らない</span> → <span class='gd-jp'>降らないそうだ</span></span><br><b>い形容詞</b>：<span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いそうだ</span></span><span class='gd-pair'><span class='gd-jp'>寒かった</span> → <span class='gd-jp'>寒かったそうだ</span></span><br><b>な形容詞</b>：要加だ　<span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かだそうだ</span></span><br><b>名詞</b>：也要加だ　<span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だそうだ</span></span><span class='gd-pair'><span class='gd-jp'>雨だった</span> → <span class='gd-jp'>雨だったそうだ</span></span><br>對老師、客人講，就把最後換成<span class='gd-jp'>そうです</span>。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>朋友之間</span>講話時更常用「<span class='gd-jp'>〜って</span>」「<span class='gd-jp'>〜んだって</span>」，意思一樣是「聽說～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さん、来月結婚するんだって。</span>（聽說田中下個月要結婚耶）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、雨だって。</span>（聽說明天會下雨）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞、な形容詞後面的<b>だ不能省</b>。寫成<span class='gd-jp'>静かそうだ</span>就變成「看起來很安靜」，意思完全不同；「聽說很安靜」要說<span class='gd-jp'>静かだそうだ</span>。<br>・<b>そうだ本身不能改成否定或過去</b>。不能說×<span class='gd-jp'>来るそうではない</span>、×<span class='gd-jp'>来るそうだった</span>。要改就改前面那句：<span class='gd-jp'>来ないそうだ</span>（聽說不來）、<span class='gd-jp'>来たそうだ</span>（聽說來了）。<br>・中文的「聽說」放在句子最前面，日文的そうだ一定放在<b>句子最後</b>。<br>・<span class='gd-jp'>いい</span>接傳聞是<span class='gd-jp'>いいそうだ</span>（聽說不錯）；<span class='gd-jp'>よさそうだ</span>是「看起來不錯」，是另一個そうだ。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>樣態的そうだ（n3-65）</b>：自己看到、感覺到「看起來～／快要～」。動詞用ます形把ます拿掉，形容詞把い拿掉，再接そうだ。<br><b>傳聞的そうだ（這一課）</b>：別人告訴你的「聽說～」，前面接完整的普通形。<br>同樣在講天氣：</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降りそうだ。</span>（看起來快下雨了：你自己看天空覺得的）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降るそうだ。</span>（聽說會下雨：從預報聽來的）</div><div class='gd-sec'>同樣在講蛋糕：</div><div class='gd-ex-line'>・<span class='gd-jp'>このケーキはおいしそうだ。</span>（這個蛋糕看起來很好吃）</div><div class='gd-ex-line'>・<span class='gd-jp'>このケーキはおいしいそうだ。</span>（聽說這個蛋糕很好吃）</div><div class='gd-sec'><b>らしい（n3-52）</b>也可以翻成「聽說」，但そうだ是有人明確講了、你照著轉述；らしい比較像「好像是這樣」，消息來源比較模糊，或是你根據聽到、看到的事情自己推斷出來的。</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは来月結婚するそうだ。</span>（聽說田中先生下個月要結婚：有人這樣跟我說）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは来月結婚するらしい。</span>（田中先生好像下個月要結婚：聽到一些風聲）</div><div class='gd-warn'>判斷小訣竅：前面是完整的「<span class='gd-jp'>降る</span>、<span class='gd-jp'>おいしい</span>、<span class='gd-jp'>雨だ</span>」，就是「聽說」；前面是被切短的「<span class='gd-jp'>降り</span>、<span class='gd-jp'>おいし</span>」，就是「看起來」。</div>",
  "n3-67": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>把「くる」「いく」想成箭頭：<b>くる＝往「我這裡、現在」靠過來</b>，<b>いく＝從「我這裡、現在」往外走</b>。中文的「～過來、～起來」大多對到<span class='gd-jp'>てくる</span>，「～下去」大多對到<span class='gd-jp'>ていく</span>。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞先變成て形，再接くる或いく。<br><span class='gd-pair'><span class='gd-jp'>増える</span> → <span class='gd-jp'>増えて</span> → <span class='gd-jp'>増えてくる</span></span><br><span class='gd-pair'><span class='gd-jp'>なる</span> → <span class='gd-jp'>なって</span> → <span class='gd-jp'>なっていく</span></span><br>後面的くる、いく照平常的方式變：<span class='gd-jp'>てきます</span>、<span class='gd-jp'>てきた</span>、<span class='gd-jp'>ていきます</span>、<span class='gd-jp'>ていった</span>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>空間的方向</span>東西或人往你這邊來，用てくる；從你這邊離開，用ていく。<b>看的是你說話時人在哪裡。</b></div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降りそうだから、傘を持っていこう。</span>（好像要下雨，帶把傘出門吧）</div><div class='gd-ex-line'>・<span class='gd-jp'>友達がケーキを持ってきてくれた。</span>（朋友帶蛋糕來給我）</div><div class='gd-sec'><span class='gd-tag'>去做一下再回來</span>てくる還有「去做某件事，做完回來」的意思。出門時說的<span class='gd-jp'>行ってきます</span>就是「我去去就回」。</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょっとコンビニで飲み物を買ってくる。</span>（我去便利商店買個飲料，馬上回來）</div><div class='gd-sec'><span class='gd-tag'>變化：到現在為止</span><span class='gd-jp'>てきた</span>＝從以前一路變到現在，現在感覺得到。</div><div class='gd-ex-line'>・<span class='gd-jp'>最近、日本語が少し分かってきた。</span>（最近日文漸漸聽得懂一點了）</div><div class='gd-ex-line'>・<span class='gd-jp'>ここ数年、オンライン会議が増えてきた。</span>（這幾年線上會議越來越多）</div><div class='gd-sec'><span class='gd-tag'>變化：從現在往後</span><span class='gd-jp'>ていく</span>＝從現在開始，接下來會繼續變下去、做下去。</div><div class='gd-ex-line'>・<span class='gd-jp'>これからどんどん寒くなっていく。</span>（接下來會越來越冷）</div><div class='gd-ex-line'>・<span class='gd-jp'>これからも日本語の勉強を続けていきたい。</span>（今後也想繼續學日文下去）</div><div class='gd-sec'><span class='gd-tag'>開始出現</span><span class='gd-jp'>てきた</span>也常用來講某個狀態「開始出現了」，就是中文的「～起來了」。</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、雨が降ってきた。</span>（啊，下起雨來了）</div><div class='gd-ex-line'>・<span class='gd-jp'>お腹がすいてきた。</span>（肚子開始餓了）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・方向是看<b>你說話時人在哪裡</b>，不是看聽話的人。在學校當面答應老師，你本身就在東西要送到的地方，說<span class='gd-jp'>はい、明日持ってきます。</span>很自然。<br>・中文說「我去買」，如果買完會回來，日本人常說<span class='gd-jp'>買ってくる</span>。<span class='gd-jp'>買っていく</span>是「買了帶到別的地方去」，例如<span class='gd-jp'>お土産を買っていく</span>（買伴手禮帶過去）。<br>・講時間的時候，「到現在」跟「從現在起」不能混：前面有<span class='gd-jp'>これから</span>就要用ていく，不能說成「これから寒くなってきた」。<br>・這裡的くる、いく通常寫平假名。過去形是<span class='gd-jp'>てきた</span>，不是「てくた」；ていく的過去形是<span class='gd-jp'>ていった</span>。<br>・口語常把ていく說成「てく」：<span class='gd-jp'>寒くなってく</span>，聽到別以為是別的文法。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講「天氣變冷」：<br><span class='gd-jp'>寒くなってきた。</span>（已經越來越冷了，現在就感覺得到）<br><span class='gd-jp'>寒くなっていく。</span>（接下來會越來越冷）<br><span class='gd-jp'>寒くなる一方だ。</span>（一直冷下去，停不下來，常帶點無奈）<br>前兩個差在時間方向，<span class='gd-jp'>一方だ</span>則是強調「只往這個方向一直發展」。</div><div class='gd-warn'>判斷小訣竅：從以前看到現在，用てきた；從現在往後看，用ていく；想說「一直往壞的方向走、停不下來」，用一方だ。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>てきた後面再加ている，變成<span class='gd-jp'>てきている</span>，表示「這個變化現在還在進行」：<span class='gd-jp'>外国人観光客が増えてきている。</span>（外國觀光客越來越多，而且還在增加）</div>",
  "n3-68": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>這三個都是「て形＋一個小尾巴」，差別在你想講什麼：<br><b>ている</b>＝現在的樣子（正在做、或一直維持某個狀態）<br><b>てある</b>＝東西被人弄好、留在那裡（看得出有人特意弄的）<br><b>ておく</b>＝先做好，為了之後（中文的「先～起來」「先～好」）<br>想像你走進會議室，看到窗戶開著：只描述「窗開著」用ている；說「窗已經有人開好了」用てある；開會前你自己說「我先去開窗」用ておく。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>都是動詞て形後面加上去：<br><span class='gd-pair'><span class='gd-jp'>開ける</span> → <span class='gd-jp'>開けて</span></span> → <span class='gd-jp'>開けている</span>／<span class='gd-jp'>開けてある</span>／<span class='gd-jp'>開けておく</span></div><div class='gd-h'>ている：現在的樣子</div><div class='gd-sec'><span class='gd-tag'>正在做</span>動作進行中。</div><div class='gd-ex-line'>・<span class='gd-jp'>今、ご飯を食べている。</span>（我現在在吃飯）</div><div class='gd-sec'><span class='gd-tag'>狀態留著</span>事情發生了，結果一直維持著。</div><div class='gd-ex-line'>・<span class='gd-jp'>エアコンがついている。</span>（冷氣開著）</div><div class='gd-ex-line'>・<span class='gd-jp'>姉は結婚している。</span>（我姊已經結婚了）</div><div class='gd-h'>てある：有人弄好、東西留著</div><div class='gd-sec'><span class='gd-tag'>結果＋有人做的</span>重點在「東西現在是這個樣子，而且是有人特意弄的」，做的人是誰通常不講。前面的東西多半用<b>が</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>ドアに名前が書いてある。</span>（門上寫著名字）</div><div class='gd-ex-line'>・<span class='gd-jp'>ビールが冷やしてある。</span>（啤酒已經冰好了）</div><div class='gd-h'>ておく：先做好</div><div class='gd-sec'><span class='gd-tag'>事先準備</span>為了之後，先把事情做好。</div><div class='gd-ex-line'>・<span class='gd-jp'>旅行の前に、ホテルを予約しておく。</span>（旅行前先把飯店訂好）</div><div class='gd-sec'><span class='gd-tag'>維持原樣</span>刻意讓它保持那樣，先不要動。</div><div class='gd-ex-line'>・<span class='gd-jp'>窓は開けておいてください。</span>（窗戶請開著，不用關）</div><div class='gd-sec'>講話時常縮成<b>とく</b>：<span class='gd-pair'><span class='gd-jp'>買っておく</span> → <span class='gd-jp'>買っとく</span></span><span class='gd-pair'><span class='gd-jp'>読んでおく</span> → <span class='gd-jp'>読んどく</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>ジュース、買っとくね。</span>（果汁我先買起來喔）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・先分清楚兩種動詞：<b>東西自己變成那樣</b>的動詞（<span class='gd-jp'>開く</span>、<span class='gd-jp'>つく</span>、<span class='gd-jp'>閉まる</span>，前面用が），跟<b>有人去弄它</b>的動詞（<span class='gd-jp'>開ける</span>、<span class='gd-jp'>つける</span>、<span class='gd-jp'>閉める</span>，前面用を）。<br>・てある要接「有人去弄它」那種：<span class='gd-jp'>窓が開けてある</span>才對，不說<span class='gd-jp'>窓が開いてある</span>。<br>・<span class='gd-jp'>窓が開けている</span>是錯的，會變成「窗戶在開某個東西」。要嘛<span class='gd-jp'>窓が開いている</span>，要嘛<span class='gd-jp'>窓が開けてある</span>。<br>・<span class='gd-jp'>結婚している</span>是「已婚」，不是「正在結婚」；<span class='gd-jp'>知っている</span>是「知道」，不能看到ている就翻「正在」。<br>・口語的「てる」是ている的縮寫，「とく」才是ておく，不要混在一起。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一扇窗，四種講法：<br>・<span class='gd-jp'>窓が開いている。</span>（窗開著：只講看到的樣子）<br>・<span class='gd-jp'>窓が開けてある。</span>（窗已經被人開好了：感覺得出有人為了什麼特意開的）<br>・<span class='gd-jp'>窓を開けておく。</span>（我先把窗打開：為了等一下要用）<br>・<span class='gd-jp'>田中さんが窓を開けている。</span>（田中先生正在開窗：焦點在人的動作）<br>另外，<b>ておいた</b>做完之後，東西的狀態就變成<b>てある</b>：<span class='gd-jp'>昨日資料を準備しておいたから、もう準備してある。</span>（昨天先準備好了，所以已經備好了）</div><div class='gd-warn'>判斷小訣竅：只說東西的樣子用「が＋ている」；想強調「有人弄好、東西留著」用「が＋てある」；說「先做好、為了之後」用「を＋ておく」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>「〜っぱなし」也是讓東西維持原樣，但多半是<b>忘了收、放著不管</b>，帶有不好的感覺：<span class='gd-jp'>窓を開けっぱなしにした。</span>（窗戶開了就沒關），跟刻意開著的<span class='gd-jp'>開けておく</span>剛好相反。</div>",
  "n3-69": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>中文說「幫」很簡單：他幫我、我幫他、我請他幫我。日文會在動詞後面加<b>くれる、あげる、もらう</b>，交代這個「人情」是往哪個方向走。<br><b>くれる</b>：別人 → 我（別人幫我做）<br><b>あげる</b>：我 → 別人（我幫別人做）<br><b>もらう</b>：我從別人那裡得到幫忙（我請別人幫我做）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞先變成て形，後面直接接上去。<br><span class='gd-pair'><span class='gd-jp'>手伝う</span> → <span class='gd-jp'>手伝って</span> → <span class='gd-jp'>手伝ってくれる</span></span><br><span class='gd-pair'><span class='gd-jp'>教える</span> → <span class='gd-jp'>教えて</span> → <span class='gd-jp'>教えてもらう</span></span></div><div class='gd-h'>三個分開看：重點是助詞</div><div class='gd-sec'><span class='gd-tag'>てくれる</span>主角是<b>對方</b>，做的人後面接<b>が</b>。「我」通常不講出來。我的家人也算「我這邊」，所以也能用。</div><div class='gd-ex-line'>・<span class='gd-jp'>友達が引っ越しを手伝ってくれた。</span>（朋友幫我搬家）</div><div class='gd-ex-line'>・<span class='gd-jp'>母がお弁当を作ってくれた。</span>（媽媽幫我做了便當）</div><div class='gd-sec'><span class='gd-tag'>てもらう</span>主角是<b>我</b>，做的人後面接<b>に</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>駅員さんに道を教えてもらった。</span>（我請站務員告訴我怎麼走）</div><div class='gd-ex-line'>・<span class='gd-jp'>先生にほめてもらった。</span>（我得到老師的稱讚）</div><div class='gd-sec'><span class='gd-tag'>てあげる</span>主角是我，對方後面用什麼助詞，<b>看原本的動詞</b>決定。</div><div class='gd-ex-line'>・<span class='gd-jp'>妹に本を読んであげた。</span>（我念書給妹妹聽）</div><div class='gd-ex-line'>・<span class='gd-jp'>友達を駅まで送ってあげた。</span>（我送朋友到車站）</div><div class='gd-h'>最常聽到的樣子：拜託別人</div><div class='gd-sec'>改成問句就是「可以幫我～嗎？」，越後面越客氣。</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょっと手伝ってくれる？</span>（可以幫我一下嗎？對朋友）</div><div class='gd-ex-line'>・<span class='gd-jp'>この書類、確認してもらえますか。</span>（這份文件可以幫我確認一下嗎？）</div><div class='gd-ex-line'>・<span class='gd-jp'>もう少しゆっくり話してもらえませんか。</span>（可以請你講慢一點嗎？）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>方向弄反</b>：くれる只能往「我這邊」。「我教朋友」不能說<span class='gd-jp'>友達に教えてくれた</span>，要說<span class='gd-jp'>友達に教えてあげた</span>。<br>・<b>助詞配錯</b>：くれる配が，もらう配に。<span class='gd-jp'>友達に手伝ってくれた</span>是錯的。<br>・<b>照中文直翻會變冷淡</b>：「他幫我買了」翻成<span class='gd-jp'>彼が買った</span>文法沒錯，但聽起來像沒在感謝。別人為你做事，日本人幾乎都會加<span class='gd-jp'>くれた</span>。<br>・<b>てあげる對長輩很失禮</b>：有「我施恩給你」的感覺。對老師說<span class='gd-jp'>荷物を持ってあげます</span>不行，要說<span class='gd-jp'>お持ちします</span>（我來幫您拿）。就算是朋友，當面說「～てあげる」也可能顯得高高在上，常改說<span class='gd-jp'>手伝おうか？</span>（要我幫忙嗎？）。<br>・<b>もらう不一定是「請」</b>：像<span class='gd-jp'>ほめてもらった</span>，你並沒有拜託老師，只是得到了好處。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>てくれる和てもらう講的常常是<b>同一件事</b>，差在誰當主角。<br><span class='gd-jp'>田中さんが傘を貸してくれた。</span>（田中借我傘：主角是田中，重點在他好心）<br><span class='gd-jp'>田中さんに傘を貸してもらった。</span>（我向田中借到傘：主角是我，常帶有「是我開口的」感覺）</div><div class='gd-warn'>判斷小訣竅：做的人後面是<b>が</b>就接くれる，是<b>に</b>就接もらう；想強調對方的好意用くれる，想說「我拜託人家、得到幫忙」用もらう。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>對老師、主管要換成敬語版：くれる → <span class='gd-jp'>くださる</span>，もらう → <span class='gd-jp'>いただく</span>。<br>・<span class='gd-jp'>先生が教えてくださいました。</span>（老師教了我）<br>・<span class='gd-jp'>先生に教えていただきました。</span>（我請老師教了我）</div>",
  "n3-70": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜させる」就是中文的<b>「叫某人做～」「讓某人做～」</b>。媽媽叫小孩吃青菜、老闆讓員工早點下班，都用它。可能是逼對方做，也可能是答應讓對方做，要看前後文。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>叫人做</span>要求對方做某件事，通常是上對下，例如爸媽對小孩、主管對部下。</div><div class='gd-ex-line'>・<span class='gd-jp'>母は子供に野菜を食べさせた。</span>（媽媽叫小孩吃青菜）</div><div class='gd-sec'><span class='gd-tag'>讓人做</span>對方本來就想做，你答應、放手讓他去做。</div><div class='gd-ex-line'>・<span class='gd-jp'>父は私を一人で旅行に行かせてくれた。</span>（爸爸讓我一個人去旅行）</div><div class='gd-sec'><span class='gd-tag'>讓人有某種心情</span>把人弄哭、讓人開心、讓人擔心。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女を泣かせてしまった。</span>（我把女朋友弄哭了）</div><div class='gd-ex-line'>・<span class='gd-jp'>親を心配させたくない。</span>（我不想讓爸媽擔心）</div><div class='gd-h'>怎麼變：先看動詞是哪一類</div><div class='gd-sec'><b>第一類（五段動詞）</b>：最後一個音換成同一行的「あ」段音，再加「せる」。<br><span class='gd-pair'><span class='gd-jp'>書く</span> → く換成か → <span class='gd-jp'>書かせる</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲ませる</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待たせる</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰らせる</span></span><br>用「う」結尾的要特別注意，「う」是換成<b>わ</b>：<span class='gd-pair'><span class='gd-jp'>買う</span> → う換成わ → <span class='gd-jp'>買わせる</span></span></div><div class='gd-sec'><b>第二類（一段動詞）</b>：把最後的「る」拿掉，加「させる」。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べさせる</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見させる</span></span><span class='gd-pair'><span class='gd-jp'>調べる</span> → <span class='gd-jp'>調べさせる</span></span></div><div class='gd-sec'><b>第三類（只有兩個，直接背）</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>させる</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来させる</span>（こさせる）</span></div><div class='gd-sec'>變好的「〜させる」本身就是一個第二類動詞，後面照第二類的規則變：<span class='gd-jp'>書かせます</span>、<span class='gd-jp'>書かせた</span>、<span class='gd-jp'>書かせて</span>、<span class='gd-jp'>書かせない</span>。</div><div class='gd-h'>誰叫、誰做：助詞怎麼放</div><div class='gd-sec'>基本句型：<b>叫的人</b>＋は／が，<b>做的人</b>＋に或を，最後接〜させる。做的人該用に還是を，看動作本身有沒有「を」：<br><b>動作本來就有「を」的東西</b>（讀書、吃飯、寫作業）：做的人用<b>に</b>，因為を已經被那個東西用掉了。</div><div class='gd-ex-line'>・<span class='gd-jp'>先生は学生に教科書を読ませた。</span>（老師叫學生念課本）</div><div class='gd-sec'><b>動作本身沒有「を」的東西</b>（去、玩、哭、等）：做的人通常用<b>を</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>子供を公園で遊ばせる。</span>（讓小孩在公園玩）</div><div class='gd-sec'>第二種情況也可以用に，例如<span class='gd-jp'>子供に自由に遊ばせる</span>，聽起來比較像「尊重對方，讓他想怎麼做就怎麼做」。剛開始學先記住上面的基本規則就夠了。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>〜させてください</span>「請讓我～」，想做某件事時，客氣地請對方允許。</div><div class='gd-ex-line'>・<span class='gd-jp'>少し考えさせてください。</span>（請讓我考慮一下）</div><div class='gd-ex-line'>・<span class='gd-jp'>ここで働かせてください。</span>（請讓我在這裡工作）</div><div class='gd-sec'><span class='gd-tag'>待たせる</span>「讓人等」，道歉的時候超常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>待たせてごめん。</span>（抱歉讓你等了）</div><div class='gd-ex-line'>・<span class='gd-jp'>お待たせしました。</span>（讓您久等了）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・用「う」結尾的動詞要變成わ：<span class='gd-jp'>買わせる</span>、<span class='gd-jp'>会わせる</span>、<span class='gd-jp'>使わせる</span>，不是買あせる。<br>・<span class='gd-jp'>来させる</span>念<b>こさせる</b>，不是きさせる。<br>・第一類不要多加「さ」：是<span class='gd-jp'>読ませる</span>，不是読まさせる。日本人自己也常這樣講錯，但一般認為不正確。<br>・對老師、主管、客人不能用させる，聽起來像你在命令對方。想請上面的人做事，要用「〜てもらう」「〜ていただく」：<span class='gd-jp'>先生に説明していただきました。</span>（請老師幫我說明了）<br>・中文很愛說「這部電影讓我很感動」，日文直接說<span class='gd-jp'>この映画に感動した</span>比較自然。硬翻成この映画は私を感動させた，會很像翻譯腔。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「打掃房間」這件事，看是誰叫、誰做：<br><b>させる</b>：<span class='gd-jp'>母は私に部屋を掃除させた。</span>（媽媽叫我打掃房間：媽媽叫，我做）<br><b>させられる</b>：<span class='gd-jp'>私は母に部屋を掃除させられた。</span>（我被媽媽逼著打掃房間：一樣是我做，但站在我的角度講，帶著不甘願的感覺）<br><b>てもらう</b>：<span class='gd-jp'>私は母に部屋を掃除してもらった。</span>（我請媽媽幫我打掃房間：我拜託，媽媽做）</div><div class='gd-warn'>判斷小訣竅：主語叫別人做是させる；主語自己被逼著做是させられる；主語請別人幫自己做是てもらう。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>把させる再加上被動，就是「被逼著做～」的<span class='gd-jp'>〜させられる</span>（使役受身）：<span class='gd-jp'>子供のころ、毎日ピアノを練習させられた。</span>（小時候每天被逼著練鋼琴）</div>",
  "n3-71": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜（ら）れる」就是中文的<b>「被～」</b>。把焦點放在「承受動作的人」身上：不是「老師罵我」，而是「我被老師罵了」。日文還有一個特別的用法：發生一件讓你很困擾的事，也會用它來抱怨「我好倒楣」。</div><div class='gd-h'>怎麼變：先看動詞是哪一類</div><div class='gd-sec'><b>第一類（五段動詞）</b>：最後一個音換成同一行的「あ」段音，再加「れる」。<br><span class='gd-pair'><span class='gd-jp'>呼ぶ</span> → ぶ換成ば → <span class='gd-jp'>呼ばれる</span></span><br><span class='gd-pair'><span class='gd-jp'>踏む</span> → <span class='gd-jp'>踏まれる</span></span><span class='gd-pair'><span class='gd-jp'>叱る</span> → <span class='gd-jp'>叱られる</span></span><br><b>う結尾的要特別注意</b>：う不是變あ，是變<b>わ</b>。<br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言われる</span></span><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買われる</span></span><br>最省事的想法：先變成ない形，把ない拿掉，加れる。<span class='gd-pair'><span class='gd-jp'>言わない</span> → <span class='gd-jp'>言われる</span></span></div><div class='gd-sec'><b>第二類（一段動詞）</b>：把最後的「る」拿掉，加「られる」。<br><span class='gd-pair'><span class='gd-jp'>褒める</span> → <span class='gd-jp'>褒められる</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見られる</span></span></div><div class='gd-sec'><b>第三類（只有兩個，直接背）</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>される</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来られる</span>（こられる）</span></div><div class='gd-sec'>變好之後，它自己就是一個第二類動詞，照第二類的規則繼續變：<br><span class='gd-pair'><span class='gd-jp'>褒められる</span> → <span class='gd-jp'>褒められた</span></span><span class='gd-pair'><span class='gd-jp'>褒められます</span></span><span class='gd-pair'><span class='gd-jp'>褒められない</span></span></div><div class='gd-h'>怎麼接</div><div class='gd-sec'>基本句型：<b>我は＋做動作的人に＋被動形</b>。做動作的人後面用「に」。</div><div class='gd-ex-line'>・<span class='gd-jp'>私は先生に叱られた。</span>（我被老師罵了）</div><div class='gd-ex-line'>・<span class='gd-jp'>上司にアイデアを褒められた。</span>（點子被上司稱讚了）</div><div class='gd-sec'>不一定是壞事，被稱讚、被選上也可以用。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>身體、東西被弄</span>腳被踩、錢包被偷，日文習慣說「我＋東西を＋被動形」，主角還是「我」。</div><div class='gd-ex-line'>・<span class='gd-jp'>電車で足を踏まれた。</span>（在電車上被踩到腳）</div><div class='gd-ex-line'>・<span class='gd-jp'>駅で財布を盗まれた。</span>（在車站錢包被偷了）</div><div class='gd-sec'><span class='gd-tag'>倒楣、困擾</span>別人做的事（甚至是天氣）害你很困擾。這種中文常常沒辦法直接用「被」講（像「被寶寶哭」就不通），是日文很有特色的地方。</div><div class='gd-ex-line'>・<span class='gd-jp'>帰りに雨に降られた。</span>（回家路上被雨淋了）</div><div class='gd-ex-line'>・<span class='gd-jp'>夜中に赤ちゃんに泣かれて、全然寝られなかった。</span>（半夜寶寶一直哭，害我完全沒辦法睡）</div><div class='gd-sec'><span class='gd-tag'>客觀描述</span>新聞、介紹裡常用，不帶情緒，不講是誰做的。</div><div class='gd-ex-line'>・<span class='gd-jp'>このお寺は500年前に建てられた。</span>（這間寺廟是500年前蓋的）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・う結尾變<b>わ</b>：是<span class='gd-jp'>買われる</span>，不是買あれる。<br>・做動作的人用「に」：<span class='gd-jp'>先生に叱られた</span>是「我被老師罵」；寫成<span class='gd-jp'>先生が叱られた</span>就變成「老師被罵了」。<br>・中文說「我的腳被踩」，日文不說私の足が踏まれた，要說<span class='gd-jp'>足を踏まれた</span>。<br>・第二類的被動形跟「能～」長得一模一樣：<span class='gd-jp'>食べられる</span>可以是「被吃」，也可以是「能吃」，要看前後文。<br>・<span class='gd-jp'>来られる</span>念<b>こられる</b>，不是きられる。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>られる（被動）</b>＝別人的動作落在我身上，我是「挨」的那個：<br><span class='gd-jp'>弟にケーキを食べられた。</span>（蛋糕被弟弟吃掉了）<br><b>させる（使役）</b>＝我叫、讓別人去做：<br><span class='gd-jp'>弟にケーキを食べさせた。</span>（我讓弟弟吃蛋糕）<br><b>てもらう</b>＝別人幫我做，我心存感謝：<br><span class='gd-jp'>先生に作文を褒めてもらった。</span>（老師稱讚了我的作文，很開心）<br>同一件事用<span class='gd-jp'>褒められた</span>，只是在講「被稱讚」這個事實，沒有特別帶出感謝。</div><div class='gd-warn'>判斷小訣竅：「被～」用れる・られる，「叫人～」用せる・させる，「人家幫我～（很感謝）」用てもらう。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>把使役和被動合在一起，就是「被逼著做～」：<span class='gd-jp'>母に野菜を食べさせられた。</span>（被媽媽逼著吃青菜）</div>",
  "n3-72": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜させられる」就是中文的<b>「被逼著～」「被叫去～」</b>。事情是<b>你自己動手做的</b>，但不是你想做的，是別人要你做。說的時候通常帶著一點委屈、抱怨的口氣。</div><div class='gd-h'>它是怎麼來的</div><div class='gd-sec'>它是兩個文法疊在一起：「させる」＝叫別人做，「られる」＝被。<br>媽媽叫我打掃，這是從媽媽的角度講：</div><div class='gd-ex-line'>・<span class='gd-jp'>母は私に部屋を掃除させた。</span>（媽媽叫我打掃房間）</div><div class='gd-sec'>換成從<b>我</b>的角度講，就變成「我被媽媽叫去打掃」：</div><div class='gd-ex-line'>・<span class='gd-jp'>私は母に部屋を掃除させられた。</span>（我被媽媽逼著打掃房間）</div><div class='gd-sec'>主角變成「我」，逼你的人後面接<b>に</b>。</div><div class='gd-h'>怎麼變：先看動詞是哪一類</div><div class='gd-sec'><b>第一類（五段動詞）</b>：最後一個音換成同一行的「あ」段音，再加「される」。<br><span class='gd-pair'><span class='gd-jp'>書く</span> → く換成か → <span class='gd-jp'>書かされる</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲まされる</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待たされる</span></span><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買わされる</span></span><br>注意「う」結尾的要換成「わ」，不是「あ」。<br>這是口語常用的短版，完整版是<span class='gd-jp'>書かせられる</span>，兩個都對，日常講話比較常聽到短版。</div><div class='gd-sec'><b>第一類裡的例外：「す」結尾</b>的不能用短版，要加「させられる」。<br><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話させられる</span></span><span class='gd-pair'><span class='gd-jp'>出す</span> → <span class='gd-jp'>出させられる</span></span></div><div class='gd-sec'><b>第二類（一段動詞）</b>：把最後的「る」拿掉，加「させられる」。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べさせられる</span></span><span class='gd-pair'><span class='gd-jp'>やめる</span> → <span class='gd-jp'>やめさせられる</span></span></div><div class='gd-sec'><b>第三類（只有兩個，直接背）</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>させられる</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来させられる</span>（こさせられる）</span><br><span class='gd-jp'>残業する</span>、<span class='gd-jp'>スピーチする</span>這種「名詞＋する」也一樣：<span class='gd-pair'><span class='gd-jp'>残業する</span> → <span class='gd-jp'>残業させられる</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>被逼著做</span>最基本的用法，抱怨不想做的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>子どものころ、毎日ピアノを練習させられた。</span>（小時候每天被逼著練鋼琴）</div><div class='gd-ex-line'>・<span class='gd-jp'>飲み会でお酒をたくさん飲まされた。</span>（在聚餐被灌了很多酒）</div><div class='gd-sec'><span class='gd-tag'>被晾著等</span><span class='gd-jp'>待たされる</span>超常用，就是「害我等很久」。</div><div class='gd-ex-line'>・<span class='gd-jp'>病院で一時間も待たされた。</span>（在醫院被晾在那邊等了一個小時）</div><div class='gd-sec'><span class='gd-tag'>不由得</span>接「想、感動」這類詞，意思是「讓人忍不住～」，沒有抱怨的意思。</div><div class='gd-ex-line'>・<span class='gd-jp'>この映画にはいろいろ考えさせられた。</span>（這部電影讓我想了很多）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<span class='gd-jp'>話す</span>變成<span class='gd-jp'>話させられる</span>，不能說「話さされる」。「す」結尾的動詞都一樣。<br>・逼你的人後面用<b>に</b>：<span class='gd-jp'>先生に作文を書かされた。</span>（被老師叫去寫作文）<br>・它帶有「我不想」的感覺。如果是別人好心讓你做、你很感謝，用這個會變成在抱怨，聽起來很失禮。<br>・別把<span class='gd-jp'>書かされる</span>跟一般的被動<span class='gd-jp'>書かれる</span>搞混：多了一個「さ」，意思就從「被寫」變成「被逼著寫」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>られる</b>＝別人<b>對我做</b>，動手的是對方：<span class='gd-jp'>母に叱られた。</span>（被媽媽罵了，罵人的是媽媽）<br><b>させられる</b>＝別人<b>叫我做</b>，動手的是我，而且我不想：<span class='gd-jp'>母に掃除させられた。</span>（被媽媽叫去打掃，打掃的是我）</div><div class='gd-sec'>再看「させてもらう」，一樣是別人讓你做，但心情完全相反：<br><b>させてもらう</b>＝我想做，對方<b>允許</b>我，我很感謝：<span class='gd-jp'>店長に頼んで、休ませてもらった。</span>（我拜託店長，他讓我休假了）<br><b>させられる</b>＝我不想，對方<b>逼</b>我：<span class='gd-jp'>熱があって、店長に無理やり休まされた。</span>（我發燒，被店長硬叫回家休息）</div><div class='gd-warn'>判斷小訣竅：先問「誰動手？」對方動手是られる；我動手又不情願是させられる；我動手而且是我想做的，是させてもらう。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>如果「させる」「られる」還不熟，回頭複習<span class='gd-jp'>〜させる</span>（使役）跟<span class='gd-jp'>〜られる</span>（被動），這個文法就是把它們疊起來而已。</div>",
  "n3-73": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ても」就是中文的<b>「就算～也～」「不管～都～」</b>。前面發生什麼事，後面的結果都<b>不受影響</b>，照樣如此。就像你說「就算下雨我也要去」，下雨也改變不了你要去這件事。</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降っても、行きます。</span>（就算下雨，我也會去）</div><div class='gd-ex-line'>・<span class='gd-jp'>高くても、買いたい。</span>（就算貴，我也想買）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：先變成て形，再加も。<br><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いて</span> → <span class='gd-jp'>書いても</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べても</span></span><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しても</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ても</span>（きても）</span><br>て形本來就是「で」的動詞，加上も就變成「でも」：<span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読んで</span> → <span class='gd-jp'>読んでも</span></span></div><div class='gd-sec'><b>い形容詞</b>：把最後的「い」換成「くても」。<br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高くても</span></span><span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>忙しくても</span></span></div><div class='gd-sec'><b>な形容詞・名詞</b>：直接加「でも」。<br><span class='gd-pair'><span class='gd-jp'>下手</span> → <span class='gd-jp'>下手でも</span></span><span class='gd-pair'><span class='gd-jp'>日曜日</span> → <span class='gd-jp'>日曜日でも</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>料理が下手でも、大丈夫です。</span>（就算不太會做菜也沒關係）</div><div class='gd-ex-line'>・<span class='gd-jp'>日曜日でも、仕事がある。</span>（就算是星期天也要工作）</div><div class='gd-sec'><b>否定的「就算不～」</b>：ない換成なくても。<span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かなくても</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>疑問詞＋ても</span>前面放「什麼、誰、哪裡、什麼時候」，就變成「不管～都～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>何を食べても、おいしい。</span>（不管吃什麼都好吃）</div><div class='gd-ex-line'>・<span class='gd-jp'>いつ行っても、混んでいる。</span>（不管什麼時候去都很多人）</div><div class='gd-ex-line'>・<span class='gd-jp'>何度確認しても、ミスが見つからない。</span>（確認了好幾次還是找不到錯誤）</div><div class='gd-sec'><span class='gd-tag'>どんなに／いくら〜ても</span>「再怎麼～也～」，強調程度再高都沒用。</div><div class='gd-ex-line'>・<span class='gd-jp'>どんなに忙しくても、朝ご飯は必ず食べる。</span>（再怎麼忙，早餐一定會吃）</div><div class='gd-ex-line'>・<span class='gd-jp'>いくら練習しても、上手にならない。</span>（再怎麼練習都沒進步）</div><div class='gd-sec'><span class='gd-tag'>たとえ〜ても</span>「就算真的～」，口氣更堅定，常用在表達決心。</div><div class='gd-ex-line'>・<span class='gd-jp'>たとえ反対されても、留学したい。</span>（就算被反對，我還是想去留學）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞和な形容詞是直接加<b>でも</b>：<span class='gd-jp'>下手でも</span>，不是「下手くても」。<br>・<span class='gd-jp'>いい</span>要變<span class='gd-jp'>よくても</span>，不是「いくても」。<br>・動詞一定要先變て形：<span class='gd-jp'>読んでも</span>，不是「読むでも」。<br>・後面的結果要跟「一般預期」<b>相反</b>才用ても。吃藥退燒是理所當然的結果，不能說「薬を飲んでも、熱が下がった」，要說<span class='gd-jp'>薬を飲んだら、熱が下がった。</span>（吃了藥就退燒了）；用ても的話是<span class='gd-jp'>薬を飲んでも、熱が下がらない。</span>（吃了藥也不退燒）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是下雨天出門，換個文法意思就不同：<br><b>たら</b>＝如果～就（條件成立，結果跟著來）：<span class='gd-jp'>雨が降ったら、行かない。</span>（如果下雨就不去）<br><b>ても</b>＝就算～也（條件改變不了結果）：<span class='gd-jp'>雨が降っても、行く。</span>（就算下雨也去）<br><b>のに</b>＝明明～卻（已經發生的事實，帶著「怎麼會這樣」的意外或不滿）：<span class='gd-jp'>雨が降っているのに、傘を持たないで出かけた。</span>（明明在下雨，卻沒帶傘就出門了）</div><div class='gd-sec'>ても可以講還沒發生的假設，後面也能接「吧」「請」：<span class='gd-jp'>雨が降っても、行きましょう。</span>（就算下雨也去吧）。のに講的是已經發生的事，後面不能接「吧」「請」，所以不能說「雨が降っているのに、行きましょう」。</div><div class='gd-warn'>判斷小訣竅：中文想說「如果～就」用たら，「就算／不管～都」用ても，「明明～卻」用のに。</div>",
  "n3-74": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜たことがある」就是中文的<b>「曾經～過」「有～過的經驗」</b>。重點不是哪一天做了什麼，而是你的人生裡<b>有沒有這個經驗</b>。像朋友問你「你吃過臭豆腐嗎？」，就是在問這個。</div><div class='gd-ex-line'>・<span class='gd-jp'>富士山に登ったことがある。</span>（我爬過富士山）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本の温泉に入ったことがありますか。</span>（你泡過日本的溫泉嗎？）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞的<b>た形</b>（就是「〜た」過去的說法）＋<span class='gd-jp'>ことがある</span>。<br>禮貌一點就說<span class='gd-jp'>ことがあります</span>；沒有這個經驗就把ある換成<span class='gd-jp'>ない</span>：<br><span class='gd-pair'><span class='gd-jp'>食べたことがある</span> → <span class='gd-jp'>食べたことがない</span></span>（沒吃過）</div><div class='gd-h'>怎麼變：先看動詞是哪一類</div><div class='gd-sec'>た形其實就是把て形的「て」換成「た」，會て形就會た形。<br><b>第一類（五段動詞）</b>：看最後一個音。<br><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会った</span></span><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んだ</span></span><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いた</span></span><span class='gd-pair'><span class='gd-jp'>泳ぐ</span> → <span class='gd-jp'>泳いだ</span></span><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話した</span></span><br>特別注意：<span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行った</span></span>，不是行いた。</div><div class='gd-sec'><b>第二類（一段動詞）</b>：把「る」拿掉，加「た」。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べた</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見た</span></span></div><div class='gd-sec'><b>第三類（只有兩個，直接背）</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>した</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来た</span>（きた）</span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>問經驗</span>聊天找話題很好用。回答時不用整句重複，說「あります／ありません」就好。</div><div class='gd-ex-line'>・<span class='gd-jp'>沖縄に行ったことがありますか。</span>（你去過沖繩嗎？）</div><div class='gd-ex-line'>・<span class='gd-jp'>はい、あります。</span>（有，去過）</div><div class='gd-ex-line'>・<span class='gd-jp'>いいえ、一度もありません。</span>（沒有，一次都沒去過）</div><div class='gd-sec'><span class='gd-tag'>加上次數</span>常跟<span class='gd-jp'>一度</span>、<span class='gd-jp'>何度も</span>、<span class='gd-jp'>一度も〜ない</span>一起出現。</div><div class='gd-ex-line'>・<span class='gd-jp'>あの店には何度も行ったことがある。</span>（那家店我去過好幾次）</div><div class='gd-ex-line'>・<span class='gd-jp'>納豆は一度も食べたことがない。</span>（納豆我一次都沒吃過）</div><div class='gd-sec'><span class='gd-tag'>以前的狀態</span>用<span class='gd-jp'>〜ていたことがある</span>，表示「以前有一段時間曾經～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>子どものころ、大阪に住んでいたことがある。</span>（我小時候在大阪住過）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>中文的「過」不一定都是它</b>。「我昨天去過超市了」只是在講昨天做的事，日文說<span class='gd-jp'>昨日スーパーに行きました</span>就好，不能說昨日スーパーに行ったことがあります。<br>・<b>剛剛、最近的事不能用</b>：<span class='gd-jp'>さっき</span>、<span class='gd-jp'>昨日</span>、<span class='gd-jp'>先週</span>這種明確又近的時間點，跟「人生經驗」不搭。像<span class='gd-jp'>子どものころ</span>這種一大段時間就沒問題。<br>・<b>每天都在做、理所當然的事也很怪</b>：說「我吃過白飯」「我搭過捷運」，日本人會覺得：這有什麼好說的？要是比較特別、不是每個人都有的經驗才用。<br>・前面一定是<b>た形</b>。寫成<span class='gd-jp'>行くことがある</span>，意思就整個變掉（看下面）。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「ことがある」，前面接的形不一樣，意思完全不同：<br><b>た形＋ことがある</b>＝<b>曾經</b>做過（過去的經驗）<br><b>辭書形＋ことがある</b>＝<b>有時候會</b>（偶爾發生的事）</div><div class='gd-ex-line'>・<span class='gd-jp'>一人で映画を見に行ったことがある。</span>（我曾經一個人去看過電影）</div><div class='gd-ex-line'>・<span class='gd-jp'>一人で映画を見に行くことがある。</span>（我有時候會一個人去看電影）</div><div class='gd-sec'>第一句只說「有過一次以上」，現在不一定還會；第二句是說現在偶爾就會這樣做。</div><div class='gd-warn'>判斷小訣竅：前面看到「た」就翻「曾經～過」，前面是辭書形就翻「有時候會～」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同樣是「た形」開頭的還有<span class='gd-jp'>〜たばかり</span>（才剛～），講的是剛發生不久的事，剛好跟「經驗」相反，可以一起記。</div>",
  "n3-75": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ことができる」就是中文的<b>「能～」「可以～」</b>。意思跟可能形（像<span class='gd-jp'>話せる</span>、<span class='gd-jp'>行ける</span>這種）差不多，只是講法比較完整、比較正式。公告、說明、面試、正式場合很常看到。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>會做（能力）</span>有學過、有本事做到。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼はピアノを弾くことができる。</span>（他會彈鋼琴）</div><div class='gd-sec'><span class='gd-tag'>允許、辦得到</span>規定上可以做，或條件允許做。</div><div class='gd-ex-line'>・<span class='gd-jp'>ここで写真を撮ることができます。</span>（這裡可以拍照）</div><div class='gd-ex-line'>・<span class='gd-jp'>この展示は予約なしで入場することができます。</span>（這個展覽不用預約就能入場）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞用辭書形（就是字典上查到的原本樣子），後面直接加「ことができる」。好消息是<b>不用管動詞是哪一類</b>，照接就好。<br><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話すことができる</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べることができる</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>することができる</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ることができる</span>（くる）</span></div><div class='gd-sec'>要說「不能」「做到了」，只改最後的「できる」就好：<br><span class='gd-pair'><span class='gd-jp'>できる</span> → <span class='gd-jp'>できない</span>（不能）</span><span class='gd-pair'><span class='gd-jp'>できる</span> → <span class='gd-jp'>できた</span>（做到了）</span></div><div class='gd-sec'><b>名詞也有一種說法</b>：表示語言、運動、技能等「活動」的名詞，可以直接接「ができる」：<span class='gd-jp'>日本語ができる</span>（會日文）、<span class='gd-jp'>テニスができる</span>（會打網球）。<br>一般物品名詞就不行。例如「會開車」要說<span class='gd-jp'>車の運転ができる</span>或<span class='gd-jp'>車を運転することができる</span>，不能說<span class='gd-jp'>車ができる</span>。<span class='gd-jp'>本ができる</span>的意思也是「書做好了」，不是「會看書」。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>ことができます</span>店家、公告告訴你可以怎麼做。</div><div class='gd-ex-line'>・<span class='gd-jp'>カードで払うことができます。</span>（可以刷卡付款）</div><div class='gd-sec'><span class='gd-tag'>ことはできません</span>規定不行。否定的時候，「が」常常換成「は」，聽起來更像在說「這件事是不行的」。</div><div class='gd-ex-line'>・<span class='gd-jp'>ここでたばこを吸うことはできません。</span>（這裡不能抽菸）</div><div class='gd-sec'><span class='gd-tag'>ことができました</span>努力之後終於辦到。</div><div class='gd-ex-line'>・<span class='gd-jp'>やっと切符を買うことができました。</span>（終於買到票了）</div><div class='gd-sec'><span class='gd-tag'>ことができるようになった</span>以前不行，現在變得可以。</div><div class='gd-ex-line'>・<span class='gd-jp'>オンラインで申請することができるようになった。</span>（現在可以線上申請了）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面一定要用辭書形，不能用ます形：要說<span class='gd-jp'>行くことができる</span>，不能說行きますことができる。<br>・動詞前面的「を」不用改：<span class='gd-jp'>日本語を話すことができる</span>。改成可能形時，才常常把「を」換成「が」：<span class='gd-jp'>日本語が話せる</span>。<br>・跟朋友聊天時，用可能形比較自然。問朋友<span class='gd-jp'>明日来ることができる？</span>會聽起來很生硬，一般會說<span class='gd-jp'>明日来られる？</span>（明天能來嗎）。<br>・中文的「會」不一定都能翻成ことができる。「明天會下雨」是在預測，跟能力無關，要說<span class='gd-jp'>明日は雨が降るでしょう</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>「ことができる」跟「ことがある」只差一個字，意思差很多。用同一件事來比：<br><b>ことができる</b>＝能、會：<span class='gd-jp'>納豆を食べることができる。</span>（我敢吃納豆）<br><b>可能形</b>＝意思一樣，比較口語：<span class='gd-jp'>納豆が食べられる。</span>（我敢吃納豆）<br><b>た形＋ことがある</b>＝做過：<span class='gd-jp'>納豆を食べたことがある。</span>（我吃過納豆）<br><b>辭書形＋ことがある</b>＝有時候會：<span class='gd-jp'>納豆を食べることがある。</span>（我有時候會吃納豆）</div><div class='gd-warn'>判斷小訣竅：看最後是「できる」還是「ある」。できる＝能不能；ある＝有沒有（做過，或有時會做）。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>後面加「ようになる」表示「變得能夠～」：<span class='gd-jp'>日本語で電話することができるようになった。</span>（我變得能用日文講電話了）</div>",
  "n3-76": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>這三個都是中文的<b>「～得受不了」「～到不行」「～得要命」</b>。熱到不行、想家想到不行、擔心得要命，那種感覺強到你壓不下來的時候就用它。三個意思差不多，差在口氣和場合。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>身體感覺</span>熱、冷、痛、睏、餓、癢。</div><div class='gd-ex-line'>・<span class='gd-jp'>お腹が空いてたまらない。</span>（餓到不行）</div><div class='gd-ex-line'>・<span class='gd-jp'>足が痛くてしかたがない。</span>（腳痛得要命）</div><div class='gd-sec'><span class='gd-tag'>心情</span>開心、難過、寂寞、擔心、在意。</div><div class='gd-ex-line'>・<span class='gd-jp'>試験の結果が心配でならない。</span>（超擔心考試結果）</div><div class='gd-sec'><span class='gd-tag'>超想做</span>前面放「〜たい」，就是「想～想到不行」。</div><div class='gd-ex-line'>・<span class='gd-jp'>家族に会いたくてたまらない。</span>（好想見家人，想到受不了）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>重點是前面要先變成「て」的樣子，三種詞變法不一樣：<br><b>動詞</b>：直接用て形　<span class='gd-pair'><span class='gd-jp'>気になる</span> → <span class='gd-jp'>気になって</span>しかたがない</span><br><b>い形容詞</b>：把最後的「い」換成「くて」　<span class='gd-pair'><span class='gd-jp'>暑い</span> → <span class='gd-jp'>暑くて</span>たまらない</span><br><b>な形容詞</b>：直接加「で」　<span class='gd-pair'><span class='gd-jp'>心配</span> → <span class='gd-jp'>心配で</span>ならない</span><br>「〜たい」變化跟い形容詞一樣：<span class='gd-pair'><span class='gd-jp'>会いたい</span> → <span class='gd-jp'>会いたくて</span></span></div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「睏得要命」：<br>・<span class='gd-jp'>眠くてたまらない。</span>（最直接、最有感，口語常用）<br>・<span class='gd-jp'>眠くてしかたがない。</span>（一直睏，怎樣都停不下來。口語常講成<span class='gd-jp'>眠くてしょうがない</span>）<br>・<span class='gd-jp'>眠くてならない。</span>（意思一樣，但比較正式、偏書面，日常聊天少用）</div><div class='gd-sec'><b>ならない</b>有一個特別常見的搭配：「<b>總覺得～，這念頭甩不掉</b>」。這時最常用ならない，たまらない很少這樣用。</div><div class='gd-ex-line'>・<span class='gd-jp'>何か忘れているような気がしてならない。</span>（一直覺得好像忘了什麼）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の話は嘘のように思えてならない。</span>（怎麼想都覺得他在說謊）</div><div class='gd-warn'>判斷小訣竅：跟朋友講「～到不行」，用たまらない或しょうがない就對了；寫文章或講「總覺得～」，用ならない。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・い形容詞別直接接て：是<span class='gd-jp'>暑くてたまらない</span>，不是暑いてたまらない。な形容詞是<span class='gd-jp'>心配で</span>，不是心配て。<br>・這是講<b>自己</b>的感覺。講別人要加<span class='gd-jp'>ようだ</span>、<span class='gd-jp'>らしい</span>：<span class='gd-jp'>弟は寂しくてたまらないようだ。</span>（弟弟好像寂寞得不得了）<br>・只能接感覺、情緒，不能接單純的描述：「這房間大得不得了」不能說広くてたまらない，要用<span class='gd-jp'>すごく広い</span>這類說法。<br>・<span class='gd-jp'>てならない</span>不等於<span class='gd-jp'>てはならない</span>！中間多一個「は」，意思就變成「不可以～」：<span class='gd-jp'>ここに入ってはならない。</span>（不可以進來這裡）<br>・<span class='gd-jp'>しかたがない</span>單獨用是「沒辦法」：<span class='gd-jp'>雨だから、しかたがない。</span>（下雨了，沒辦法）。前面接て形才是「～得受不了」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'><span class='gd-jp'>たまらない</span>單獨用，常常是「讚到受不了」：<span class='gd-jp'>仕事の後のビール、たまらない！</span>（下班後來杯啤酒，爽啦！）</div>",
  "n3-77": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜どおりに／〜とおりに」就是中文的<b>「照著～」「跟～一樣」</b>。照食譜做菜、照計畫走、照老師說的寫，都用它。漢字寫成「通り」，可以想成範本已經把路線畫好，你就沿著那條路走。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>照著做</span>手上有一個範本，例如食譜、說明書、計畫、別人說的話，你照著它做。</div><div class='gd-ex-line'>・<span class='gd-jp'>説明書どおりに組み立てた。</span>（照著說明書組裝好了）</div><div class='gd-ex-line'>・<span class='gd-jp'>先生が言ったとおりに書いてください。</span>（請照老師說的寫）</div><div class='gd-sec'><span class='gd-tag'>跟預料的一樣</span>結果跟原本想的、預測的一樣，有點像中文的「果然」。</div><div class='gd-ex-line'>・<span class='gd-jp'>予想どおり、試験は難しかった。</span>（跟預料的一樣，考試很難）</div><div class='gd-ex-line'>・<span class='gd-jp'>思ったとおり、彼は来なかった。</span>（果然跟我想的一樣，他沒來）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>重點是<b>前面接的是名詞還是動詞</b>，念法會不一樣：<br><b>名詞直接接</b>：念<b>どおり</b>（有兩點的濁音）<br><span class='gd-pair'><span class='gd-jp'>計画</span> → <span class='gd-jp'>計画どおり</span></span><span class='gd-pair'><span class='gd-jp'>予定</span> → <span class='gd-jp'>予定どおり</span></span><br><b>名詞中間加「の」</b>：念<b>とおり</b><br><span class='gd-pair'><span class='gd-jp'>説明書</span> → <span class='gd-jp'>説明書のとおり</span></span><br><b>動詞</b>：用辭書形或た形，念<b>とおり</b><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言うとおり</span></span><span class='gd-pair'><span class='gd-jp'>教わった</span> → <span class='gd-jp'>教わったとおり</span></span><br>另外，<span class='gd-jp'>そのとおりです</span>（就是那樣、你說得對）是對方講對時很常用的附和。</div><div class='gd-sec'>後面要看接什麼：<br>接動作用「に」，口語常省略：<span class='gd-jp'>計画どおり進んでいる。</span>（照計畫在進行）<br>接名詞用「の」：<span class='gd-jp'>予想どおりの結果だった。</span>（是跟預料一樣的結果）<br>放句尾用「だ／です」：<span class='gd-jp'>結果は期待どおりだった。</span>（結果跟期待的一樣）</div><div class='gd-h'>辭書形跟た形怎麼選</div><div class='gd-sec'><span class='gd-tag'>た形</span>範本<b>已經發生過</b>，像是已經教過、說過、看過。最常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>見たとおりに話してください。</span>（請照你看到的說）</div><div class='gd-sec'><span class='gd-tag'>辭書形</span>範本<b>正在進行</b>，或是講一般的「聽某人的話」。</div><div class='gd-ex-line'>・<span class='gd-jp'>私が言うとおりに書いてください。</span>（請照我（現在）念的寫下來）</div><div class='gd-ex-line'>・<span class='gd-jp'>親の言うとおりにする。</span>（照爸媽說的做）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞<b>直接</b>接才念どおり，中間有の就變とおり：<span class='gd-jp'>説明書のとおり</span>才對，不是説明書のどおり；<span class='gd-jp'>計画どおり</span>才對，不是計画とおり。<br>・動詞後面念<b>とおり</b>，不要寫成濁音的どおり。<br>・中文說「照著計畫」，但日文前面<b>不加を</b>，計画をどおりに是錯的。<br>・後面接名詞一定要有の：<span class='gd-jp'>予想どおりの結果</span>，不能說予想どおり結果。<br>・在日本看到<span class='gd-jp'>銀座通り</span>這種路名，那個「通り」是「街道」的意思，跟這個文法無關。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>どおりに</b>＝做法跟範本<b>一模一樣</b>：<span class='gd-jp'>マニュアルどおりに対応した。</span>（完全照手冊處理）<br><b>に基づいて</b>＝把它當<b>根據、當基礎</b>：<span class='gd-jp'>マニュアルに基づいて対応した。</span>（以手冊為依據來處理）<br>另外，「結果跟預料一樣」只能用どおり，像是<span class='gd-jp'>予想どおり</span>，不能換成に基づいて。</div><div class='gd-warn'>判斷小訣竅：照著做、做得一模一樣，或是「果然跟想的一樣」，就用どおり／とおり；只是拿來當根據、當基礎，就用に基づいて。</div>",
  "n3-78": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜っけ」是你<b>本來知道、現在一時想不起來</b>的時候用的。就像中文說「欸，明天的會幾點啊？我忘了」「他生日是不是下禮拜？」那種邊想邊問的感覺。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>想不起來</span>問別人，或自己嘀咕。</div><div class='gd-ex-line'>・<span class='gd-jp'>明日のミーティングは何時からだっけ？</span>（明天的會幾點開始啊？我忘了）</div><div class='gd-ex-line'>・<span class='gd-jp'>あれ、鍵どこに置いたっけ？</span>（咦，鑰匙我放哪了？）</div><div class='gd-sec'><span class='gd-tag'>確認記憶</span>你心裡有個答案，想確定自己沒記錯。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の誕生日は来週だっけ？</span>（他生日是下禮拜，對吧？）</div><div class='gd-sec'><span class='gd-tag'>懷念以前</span>對著過去的事自言自語。句尾不上揚，有「那時候啊……」的味道。</div><div class='gd-ex-line'>・<span class='gd-jp'>子どものころ、よくこの公園で遊んだっけ。</span>（小時候常在這個公園玩呢）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>名詞、な形容詞</b>：先加「だ」或「だった」，再加っけ。<br><span class='gd-pair'><span class='gd-jp'>明日</span> → <span class='gd-jp'>明日だっけ</span></span><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かだったっけ</span></span></div><div class='gd-sec'><b>動詞</b>：問以前的事，用た形加っけ。<br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言った</span> → <span class='gd-jp'>言ったっけ</span></span><br>問還沒發生的事，多半說「〜んだっけ」比較自然。<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来るんだっけ</span></span>（他會來，對吧？）</div><div class='gd-sec'><b>い形容詞</b>：把い換成かった，再加っけ。<br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高かったっけ</span></span>（那家很貴嗎？我忘了）</div><div class='gd-sec'><b>想禮貌一點</b>：說「でしたっけ」「ましたっけ」。</div><div class='gd-ex-line'>・<span class='gd-jp'>すみません、お名前は何でしたっけ？</span>（不好意思，請問您貴姓……我一下想不起來）</div><div class='gd-ex-line'>・<span class='gd-jp'>前に言いましたっけ？</span>（我之前有跟您說過嗎？）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞後面不能直接加っけ：說<span class='gd-jp'>明日っけ</span>是錯的，要說<span class='gd-jp'>明日だっけ</span>。<br>・用っけ的前提是你<b>以前知道過</b>。第一次跟路人問路，不能說<span class='gd-jp'>駅はどこだっけ？</span>，要說<span class='gd-jp'>駅はどこですか。</span><br>・明天的事也能用過去形：<span class='gd-jp'>明日の会議、何時からだったっけ？</span>這裡的「た」不是說會議已經結束，而是指「之前聽過的那件事」。<br>・「だっけ」是朋友版。對主管、客人改用「でしたっけ」「ましたっけ」，職場很常聽到；不過面試、正式書信就別用了。<br>・小「っ」要停一拍：<span class='gd-jp'>だっけ</span>念 dakke。少了那一拍念成<span class='gd-jp'>だけ</span>，就變成「只有」的意思。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是問朋友「明天的會幾點」：<br><span class='gd-jp'>明日の会議、何時から？</span>：一般的問法，你本來就不知道。<br><span class='gd-jp'>明日の会議、何時からだっけ？</span>：你聽過，但是忘了。<br><span class='gd-jp'>明日の会議、何時からかな。</span>：自己在心裡想，不一定要對方回答。</div><div class='gd-warn'>判斷小訣竅：「以前知道、現在忘了」用っけ；「本來就不知道」用一般問句。</div>",
  "n3-79": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜反面」就是中文的<b>「有好處也有壞處」「一體兩面」</b>。同一件事，你先講它的一面，再講跟它<b>相反的另一面</b>。例如「這份工作薪水不錯，可是很忙」，這種「同一件事、兩個相反的面」就用反面。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>一好一壞</span>最常見的用法：同一個人、同一個東西，有優點也有缺點。</div><div class='gd-ex-line'>・<span class='gd-jp'>この仕事は給料がいい反面、休みが少ない。</span>（這份工作薪水好，但休假很少）</div><div class='gd-ex-line'>・<span class='gd-jp'>一人暮らしは自由な反面、寂しいこともある。</span>（一個人住很自由，但有時也會寂寞）</div><div class='gd-sec'><span class='gd-tag'>心情很矛盾</span>心裡同時有兩種相反的感覺，也很常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>卒業はうれしい反面、少し寂しい。</span>（畢業很開心，但也有點捨不得）</div><div class='gd-sec'><span class='gd-tag'>放句首</span>前一句講完，下一句用「その反面」開頭，意思是「但另一方面」。</div><div class='gd-ex-line'>・<span class='gd-jp'>スマホは便利だ。その反面、使いすぎると目が疲れる。</span>（手機很方便。但另一方面，用太多眼睛會累）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：直接接，過去式也可以。<br><span class='gd-pair'><span class='gd-jp'>便利になった</span> → <span class='gd-jp'>便利になった反面</span></span><br><b>い形容詞</b>：直接接。<br><span class='gd-pair'><span class='gd-jp'>速い</span> → <span class='gd-jp'>速い反面</span></span><br><b>な形容詞</b>：要加「な」，或是用比較正式的「である」。<br><span class='gd-pair'><span class='gd-jp'>便利</span> → <span class='gd-jp'>便利な反面</span>／<span class='gd-jp'>便利である反面</span></span><br><b>名詞</b>：加「である」。<br><span class='gd-pair'><span class='gd-jp'>有名人</span> → <span class='gd-jp'>有名人である反面</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は有名人である反面、自由な時間が少ない。</span>（她是名人，但相對的自由時間很少）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・な形容詞不能直接接：說<span class='gd-jp'>便利な反面</span>，不要說「便利反面」，也不要說「便利だ反面」。<br>・名詞要用<span class='gd-jp'>である</span>，不要說「学生な反面」。<br>・反面講的是<b>同一個東西</b>的兩面。拿兩個不同的人來比，例如「哥哥很高、弟弟很矮」，用反面就怪怪的。<br>・反面偏書面、偏正式，作文、新聞、報告很常見。跟朋友聊天，一般用<span class='gd-jp'>けど</span>就好：<span class='gd-jp'>給料はいいけど、忙しい。</span>（薪水是不錯啦，可是很忙）<br>・念法是<b>はんめん</b>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>反面</b>＝<b>同一個</b>東西的兩面：<span class='gd-jp'>兄は優しい反面、気が弱い。</span>（哥哥很溫柔，但另一方面個性很軟弱）<br><b>一方で</b>＝可以講同一個東西的兩面，<b>也可以</b>拿兩個不同的東西來對照：<span class='gd-jp'>兄はスポーツが好きな一方で、弟は本が好きだ。</span>（哥哥喜歡運動，弟弟則是喜歡看書）<br><b>に対して</b>＝專門拿<b>兩個不同的東西</b>做對比：<span class='gd-jp'>兄は背が高いのに対して、弟は低い。</span>（哥哥很高，相對的弟弟很矮）</div><div class='gd-warn'>判斷小訣竅：主角只有一個、講它的好與壞，用反面；主角有兩個、拿來互相比，用一方で或に対して。<br>另外，<span class='gd-jp'>一方だ</span>放在句尾是「越來越～」，跟這裡講的「一方で」是不同的東西，別搞混。</div>"
});
(window.GRAMMAR_DETAIL_LV = window.GRAMMAR_DETAIL_LV || {}).n3 = true;
